(339414,37713,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adivina, todo el mundo dice que ... fue lo mejor de todo el show.'::text,'la carga'::text,'una carga'::text,'carga'::text,'Adivina, todo el mundo dice que la carga fue lo mejor de todo el show.'::text),
