(346849,38539,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра опівдні майстер ... свій наступний шпаківник, як він зазвичай робить.'::text,'проєктуватиме'::text,'спроєктує'::text,'проєктує'::text,'Завтра опівдні майстер проєктуватиме свій наступний шпаківник, як він зазвичай робить.'::text),
(346848,38539,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana al mediodía, el artesano ... su próxima casita para pájaros, como hace típicamente.'::text,'estará diseñando'::text,'diseñará'::text,'está diseñando'::text,'Mañana al mediodía, el artesano estará diseñando su próxima casita para pájaros, como hace típicamente.'::text),
(346847,38539,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à midi, l''artisan ... son prochain nichoir, comme il le fait généralement.'::text,'sera en train de concevoir'::text,'concevra'::text,'est en train de concevoir'::text,'Demain à midi, l''artisan sera en train de concevoir son prochain nichoir, comme il le fait généralement.'::text),
(346850,38539,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın öğlen zanaatkâr, tipik olarak yaptığı gibi, bir sonraki kuş evini ...'::text,'tasarlıyor olacak'::text,'tasarlayacak'::text,'tasarlıyor'::text,'Yarın öğlen zanaatkâr, tipik olarak yaptığı gibi, bir sonraki kuş evini tasarlıyor olacak.'::text),
(346851,38539,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap délben a mesterember ... a következő madárodúját, ahogy általában szokta.'::text,'épp tervezni fogja'::text,'megtervezi'::text,'tervezi'::text,'Holnap délben a mesterember épp tervezni fogja a következő madárodúját, ahogy általában szokta.'::text),
(346872,38542,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mal ehrlich, du ... dieses Vogelhaus gerade wie ein echter Architekt.'::text,'entwirfst'::text,'entwirfst'::text,'hast entworfen'::text,'Mal ehrlich, du entwirfst dieses Vogelhaus gerade wie ein echter Architekt.'::text),
(346876,38542,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не буду брехати, ти прямо зараз ... цей шпаківник, як справжній архітектор.'::text,'проєктуєш'::text,'проєктуєш'::text,'спроєктував'::text,'Не буду брехати, ти прямо зараз проєктуєш цей шпаківник, як справжній архітектор.'::text),
(346875,38542,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No voy a mentir, tú ... esta casita para pájaros como un auténtico arquitecto ahora mismo.'::text,'estás diseñando'::text,'diseñas'::text,'has diseñado'::text,'No voy a mentir, tú estás diseñando esta casita para pájaros como un auténtico arquitecto ahora mismo.'::text),
(346874,38542,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, tu ... ce nichoir comme un vrai architecte en ce moment.'::text,'es en train de concevoir'::text,'conçois'::text,'as conçu'::text,'Je vais pas mentir, tu es en train de concevoir ce nichoir comme un vrai architecte en ce moment.'::text),
(346877,38542,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, sen şu an bu kuş evini gerçek bir mimar gibi ...'::text,'tasarlıyorsun'::text,'tasarlarsın'::text,'tasarladın'::text,'Yalan yok, sen şu an bu kuş evini gerçek bir mimar gibi tasarlıyorsun.'::text),
(346878,38542,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hazudok, te most úgy ... ezt a madárodút, mint egy igazi építész.'::text,'tervezed'::text,'tervezed'::text,'megtervezted'::text,'Nem hazudok, te most úgy tervezed ezt a madárodút, mint egy igazi építész.'::text),
(403599,44845,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um neun ... sie gerade an ihrem neuen Arbeitsplatz.'::text,'lernt'::text,'lernt'::text,'lernte'::text,'Morgen um neun lernt sie gerade an ihrem neuen Arbeitsplatz.'::text),
(403603,44845,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра о дев''ятій вона ... за своїм новим робочим місцем.'::text,'навчатиметься'::text,'навчається'::text,'навчалася'::text,'Завтра о дев''ятій вона навчатиметься за своїм новим робочим місцем.'::text),
(403602,44845,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a las nueve, ella ... en su nuevo espacio de trabajo.'::text,'estará estudiando'::text,'estudia'::text,'estudió'::text,'Mañana a las nueve, ella estará estudiando en su nuevo espacio de trabajo.'::text),
(403601,44845,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à neuf heures, elle ... à son nouveau poste de travail.'::text,'sera en train d''étudier'::text,'étudie'::text,'a étudié'::text,'Demain à neuf heures, elle sera en train d''étudier à son nouveau poste de travail.'::text),
(403604,44845,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın saat dokuzda o yeni çalışma alanında ...'::text,'ders çalışıyor olacak'::text,'ders çalışır'::text,'ders çalıştı'::text,'Yarın saat dokuzda o yeni çalışma alanında ders çalışıyor olacak.'::text),
(403605,44845,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap kilenckor ő az új munkasarkában ...'::text,'fog tanulni'::text,'tanul'::text,'tanult'::text,'Holnap kilenckor ő az új munkasarkában fog tanulni.'::text),
(403680,44854,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... ihren Arbeitsplatz schon seit einer Stunde, und er ist offensichtlich immer noch sehr minimalistisch.'::text,'dekoriert'::text,'dekoriert'::text,'dekoriert'::text,'Sie dekoriert ihren Arbeitsplatz schon seit einer Stunde, und er ist offensichtlich immer noch sehr minimalistisch.'::text),
(403684,44854,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... своє робоче місце вже годину, і воно, очевидно, все ще дуже мінімалістичне.'::text,'прикрашає'::text,'прикрашає'::text,'прикрашає'::text,'Вона прикрашає своє робоче місце вже годину, і воно, очевидно, все ще дуже мінімалістичне.'::text),
(403683,44854,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... su espacio de trabajo desde hace una hora, y obviamente sigue siendo muy minimalista.'::text,'ha estado decorando'::text,'está decorando'::text,'decora'::text,'Ella ha estado decorando su espacio de trabajo desde hace una hora, y obviamente sigue siendo muy minimalista.'::text),
(403682,44854,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... son espace de travail depuis une heure, et il est évidemment toujours très minimaliste.'::text,'décore'::text,'décore'::text,'décore'::text,'Elle décore son espace de travail depuis une heure, et il est évidemment toujours très minimaliste.'::text),
(403685,44854,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O bir saattir çalışma alanını ..., ve belli ki hâlâ çok minimalist.'::text,'süslüyor'::text,'süslüyor'::text,'süsler'::text,'O bir saattir çalışma alanını süslüyor, ve belli ki hâlâ çok minimalist.'::text),
(403686,44854,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő már egy órája ... a munkasarkát, és az nyilván még mindig nagyon minimalista.'::text,'díszíti'::text,'díszíti'::text,'díszíti'::text,'Ő már egy órája díszíti a munkasarkát, és az nyilván még mindig nagyon minimalista.'::text),
(346908,38546,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sein Auto anspringen würde, ... er sich im Regen nicht so verzweifelt.'::text,'fühlte'::text,'fühlt'::text,'fühlt'::text,'Wenn sein Auto anspringen würde, fühlte er sich im Regen nicht so verzweifelt.'::text),
(346912,38546,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби його машина завелася, він не ... таким відчайдушним під дощем.'::text,'почувався б'::text,'почуватиметься'::text,'почувається'::text,'Якби його машина завелася, він не почувався б таким відчайдушним під дощем.'::text),
(346911,38546,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si su coche arrancara, él no ... tan desesperado bajo la lluvia.'::text,'se sentiría'::text,'se sentirá'::text,'se siente'::text,'Si su coche arrancara, él no se sentiría tan desesperado bajo la lluvia.'::text),
(346910,38546,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si sa voiture démarrait, il ne ... pas aussi désespéré sous la pluie.'::text,'se sentirait'::text,'se sentira'::text,'se sent'::text,'Si sa voiture démarrait, il ne se sentirait pas aussi désespéré sous la pluie.'::text),
(346913,38546,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arabası çalışsaydı, o yağmurda kendini bu kadar çaresiz ...'::text,'hissetmezdi'::text,'hissetmeyecek'::text,'hissetmiyor'::text,'Arabası çalışsaydı, o yağmurda kendini bu kadar çaresiz hissetmezdi.'::text),
(346914,38546,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha beindulna az autója, ő nem ... ilyen kétségbeesettnek az esőben.'::text,'érezné magát'::text,'fogja érezni magát'::text,'érzi magát'::text,'Ha beindulna az autója, ő nem érezné magát ilyen kétségbeesettnek az esőben.'::text),
(346998,38556,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... schon eine Stunde lang versucht, das Auto zu starten, als er sich schließlich verzweifelt hinsetzte.'::text,'hatte'::text,'hat'::text,'versuchte'::text,'Er hatte schon eine Stunde lang versucht, das Auto zu starten, als er sich schließlich verzweifelt hinsetzte.'::text),
(347002,38556,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... завести машину вже годину, коли нарешті у відчаї сів.'::text,'намагався'::text,'намагається'::text,'намагався'::text,'Він намагався завести машину вже годину, коли нарешті у відчаї сів.'::text),
(347001,38556,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... arrancar el coche una hora cuando por fin se sentó, desesperado.'::text,'llevaba intentando'::text,'lleva intentando'::text,'estaba intentando'::text,'Él llevaba intentando arrancar el coche una hora cuando por fin se sentó, desesperado.'::text),
(347000,38556,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... de démarrer la voiture depuis une heure quand il s''est enfin assis, désespéré.'::text,'essayait'::text,'essaie'::text,'essayait'::text,'Il essayait de démarrer la voiture depuis une heure quand il s''est enfin assis, désespéré.'::text),
(347003,38556,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, sonunda çaresizce oturduğunda bir saattir arabayı çalıştırmaya ...'::text,'çalışıyordu'::text,'çalışıyor'::text,'çalışıyordu'::text,'O, sonunda çaresizce oturduğunda bir saattir arabayı çalıştırmaya çalışıyordu.'::text),
(347004,38556,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő már egy órája ... beindítani az autót, amikor végül kétségbeesetten leült.'::text,'próbálta'::text,'próbálja'::text,'próbálta'::text,'Ő már egy órája próbálta beindítani az autót, amikor végül kétségbeesetten leült.'::text),
(347061,38563,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Leuchtturm soll seit Jahren das Ziel vieler Reisender ...'::text,'gewesen sein'::text,'sein'::text,'sein'::text,'Der Leuchtturm soll seit Jahren das Ziel vieler Reisender gewesen sein.'::text),
(347065,38563,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кажуть, що маяк уже роками ... місцем призначення багатьох мандрівників.'::text,'є'::text,'є'::text,'є'::text,'Кажуть, що маяк уже роками є місцем призначення багатьох мандрівників.'::text),
(347064,38563,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se dice que el faro ... el destino de muchos viajeros durante años.'::text,'ha sido'::text,'es'::text,'siendo'::text,'Se dice que el faro ha sido el destino de muchos viajeros durante años.'::text),
(347063,38563,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On dit que le phare ... la destination de nombreux voyageurs depuis des années.'::text,'est'::text,'est'::text,'est'::text,'On dit que le phare est la destination de nombreux voyageurs depuis des années.'::text),
(347066,38563,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Deniz fenerinin yıllardır birçok gezginin varış noktası ... söyleniyor.'::text,'olduğu'::text,'olduğu'::text,'olduğu'::text,'Deniz fenerinin yıllardır birçok gezginin varış noktası olduğu söyleniyor.'::text),
(347067,38563,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A világítótorony állítólag évek óta ... sok utazó úti célja.'::text,''::text,NULL::text,NULL::text,'A világítótorony állítólag évek óta sok utazó úti célja.'::text),
(365808,40646,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie wünscht sich, dass sie den Leuchtturm früher ..., statt nur auf ein Poster zu schauen.'::text,'besucht hätte'::text,'besucht hat'::text,'besuchen würde'::text,'Sie wünscht sich, dass sie den Leuchtturm früher besucht hätte, statt nur auf ein Poster zu schauen.'::text),
(365812,40646,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона шкодує, що не ... маяк раніше, замість того щоб лише дивитися на постер.'::text,'відвідала'::text,'відвідала'::text,'відвідала б'::text,'Вона шкодує, що не відвідала маяк раніше, замість того щоб лише дивитися на постер.'::text),
(365811,40646,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella desearía ... el faro antes, en lugar de solo mirar un póster.'::text,'haber visitado'::text,'ha visitado'::text,'visitaría'::text,'Ella desearía haber visitado el faro antes, en lugar de solo mirar un póster.'::text),
(365810,40646,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle aimerait ... le phare plus tôt, au lieu de seulement regarder une affiche.'::text,'avoir visité'::text,'a visité'::text,'visiterait'::text,'Elle aimerait avoir visité le phare plus tôt, au lieu de seulement regarder une affiche.'::text),
(365813,40646,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, sadece bir postere bakmak yerine deniz fenerini daha önce ... diliyor.'::text,'ziyaret etmiş olmayı'::text,'ziyaret etmeyi'::text,'ziyaret edeceğini'::text,'O, sadece bir postere bakmak yerine deniz fenerini daha önce ziyaret etmiş olmayı diliyor.'::text),
(365814,40646,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő azt kívánja, bárcsak korábban ... a világítótornyot, ahelyett hogy csak egy posztert nézne.'::text,'meglátogatta volna'::text,'meglátogatta'::text,'meglátogatná'::text,'Ő azt kívánja, bárcsak korábban meglátogatta volna a világítótornyot, ahelyett hogy csak egy posztert nézne.'::text),
(382692,42522,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, das Dach wurde irgendwie zu Schutt, und ...'::text,'die Vorderwand auch.'::text,'die Vorderwand auch.'::text,'die Vorderwand auch.'::text,'Bro, das Dach wurde irgendwie zu Schutt, und die Vorderwand auch.'::text),
(382696,42522,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, дах типу перетворився на руїни, і ...'::text,'передня стіна теж.'::text,'передня стіна теж.'::text,'передня стіна теж.'::text,'Бро, дах типу перетворився на руїни, і передня стіна теж.'::text),
(382695,42522,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, el techo como que se convirtió en escombros, y ...'::text,'la pared delantera también.'::text,'la pared delantera también.'::text,'la pared delantera también.'::text,'Bro, el techo como que se convirtió en escombros, y la pared delantera también.'::text),
(382694,42522,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, le toit s''est genre transformé en gravats, et ...'::text,'le mur de devant aussi.'::text,'le mur de devant aussi.'::text,'le mur de devant aussi.'::text,'Frère, le toit s''est genre transformé en gravats, et le mur de devant aussi.'::text),
(382697,42522,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, çatı resmen moloza döndü, ve ...'::text,'ön duvar da öyle.'::text,'ön duvar da öyle.'::text,'ön duvar da öyle.'::text,'Kanka, çatı resmen moloza döndü, ve ön duvar da öyle.'::text),
(382698,42522,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a tető kábé törmelékké vált, és ...'::text,'az elülső fal is.'::text,'az elülső fal is.'::text,'az elülső fal is.'::text,'Tesó, a tető kábé törmelékké vált, és az elülső fal is.'::text),
(382701,42523,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis heute Abend wird der Bagger das ganze Haus in Schutt ...'::text,'verwandelt haben'::text,'verwandeln'::text,'gerade verwandeln'::text,'Bis heute Abend wird der Bagger das ganze Haus in Schutt verwandelt haben.'::text),
(382705,42523,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До вечора екскаватор ... весь будинок на руїни.'::text,'перетворить'::text,'перетворить'::text,'перетворюватиме'::text,'До вечора екскаватор перетворить весь будинок на руїни.'::text),
(382704,42523,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para esta noche, la excavadora ... toda la casa en escombros.'::text,'habrá convertido'::text,'convertirá'::text,'estará convirtiendo'::text,'Para esta noche, la excavadora habrá convertido toda la casa en escombros.'::text),
(382703,42523,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici ce soir, la pelleteuse ... toute la maison en gravats.'::text,'aura transformé'::text,'transformera'::text,'sera en train de transformer'::text,'D''ici ce soir, la pelleteuse aura transformé toute la maison en gravats.'::text),
(382706,42523,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu akşama kadar ekskavatör bütün evi moloza ...'::text,'çevirmiş olacak'::text,'çevirecek'::text,'çeviriyor olacak'::text,'Bu akşama kadar ekskavatör bütün evi moloza çevirmiş olacak.'::text),
(382707,42523,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Estére a markoló ... az egész házat törmelékké.'::text,'változtatja'::text,'változtatja'::text,'változtatni fogja'::text,'Estére a markoló változtatja az egész házat törmelékké.'::text),
(365862,40652,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Seife, die aus der Flasche fließt, ist flüssig, ...?'::text,'oder'::text,'nicht wahr'::text,'oder'::text,'Die Seife, die aus der Flasche fließt, ist flüssig, oder?'::text),
(365866,40652,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Мило, що ллється з пляшки, рідке, ...?'::text,'так'::text,'правда'::text,'так'::text,'Мило, що ллється з пляшки, рідке, так?'::text),
(365865,40652,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El jabón que sale de la botella es líquido, ¿...?'::text,'verdad'::text,'no'::text,'verdad'::text,'El jabón que sale de la botella es líquido, ¿verdad?'::text),
(365864,40652,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le savon qui coule de la bouteille est liquide, ... ?'::text,'n''est-ce pas'::text,'n''est-ce pas'::text,'n''est-ce pas'::text,'Le savon qui coule de la bouteille est liquide, n''est-ce pas ?'::text),
(365867,40652,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şişeden akan sabun sıvı, ...?'::text,'değil mi'::text,'değil mi'::text,'değil miydi'::text,'Şişeden akan sabun sıvı, değil mi?'::text),
(365868,40652,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az üvegből ömlő szappan folyékony, ...?'::text,'ugye'::text,'ugye'::text,'ugye'::text,'Az üvegből ömlő szappan folyékony, ugye?'::text),
(347169,38575,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Diese Woche hat er dieses Waschmittel dreimal ...'::text,'benutzt'::text,'benutzt'::text,'benutzt'::text,'Diese Woche hat er dieses Waschmittel dreimal benutzt.'::text),
(347173,38575,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... цей засіб для прання тричі цього тижня.'::text,'використав'::text,'використовував'::text,'використовує'::text,'Він використав цей засіб для прання тричі цього тижня.'::text),
(347172,38575,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... este detergente tres veces esta semana.'::text,'ha usado'::text,'ha estado usando'::text,'está usando'::text,'Él ha usado este detergente tres veces esta semana.'::text),
(347171,38575,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... cette lessive trois fois cette semaine.'::text,'a utilisé'::text,'utilise'::text,'utilise'::text,'Il a utilisé cette lessive trois fois cette semaine.'::text),
(347174,38575,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O bu hafta bu deterjanı üç kez ...'::text,'kullandı'::text,'kullanıyor'::text,'kullanıyor'::text,'O bu hafta bu deterjanı üç kez kullandı.'::text),
(347175,38575,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő ezen a héten háromszor ... ezt a mosószert.'::text,'használta'::text,'használta'::text,'használja'::text,'Ő ezen a héten háromszor használta ezt a mosószert.'::text),
(347223,38581,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Also, er hat mir erzählt, dass er dieses Waschmittel wochenlang ..., bevor es endlich gewirkt hat.'::text,'benutzt hatte'::text,'benutzt hat'::text,'benutzt'::text,'Also, er hat mir erzählt, dass er dieses Waschmittel wochenlang benutzt hatte, bevor es endlich gewirkt hat.'::text),
(347227,38581,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Отже, він сказав мені, що ... цей засіб для прання тижнями, поки той нарешті не подіяв.'::text,'використовував'::text,'використовує'::text,'використовує'::text,'Отже, він сказав мені, що використовував цей засіб для прання тижнями, поки той нарешті не подіяв.'::text),
(347226,38581,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, él me dijo que ... este detergente durante semanas antes de que por fin funcionara.'::text,'había estado usando'::text,'ha estado usando'::text,'está usando'::text,'Vale, él me dijo que había estado usando este detergente durante semanas antes de que por fin funcionara.'::text),
(347225,38581,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, il m''a dit qu''il ... cette lessive pendant des semaines avant qu''elle marche enfin.'::text,'avait utilisé'::text,'a utilisé'::text,'utilise'::text,'Bon, il m''a dit qu''il avait utilisé cette lessive pendant des semaines avant qu''elle marche enfin.'::text),
(347228,38581,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, o bana bu deterjanı sonunda işe yarayana kadar haftalarca ... söyledi.'::text,'kullandığını'::text,'kullandığını'::text,'kullandığını'::text,'Tamam, o bana bu deterjanı sonunda işe yarayana kadar haftalarca kullandığını söyledi.'::text),
(347229,38581,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval ő azt mondta nekem, hogy hetekig ... ezt a mosószert, mire végre hatott.'::text,'használta'::text,'használja'::text,'használja'::text,'Szóval ő azt mondta nekem, hogy hetekig használta ezt a mosószert, mire végre hatott.'::text),
(374601,41623,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Hund weiter scharrt, ... die Grube groß genug für beide sein.'::text,'wird'::text,'würde'::text,'war'::text,'Wenn der Hund weiter scharrt, wird die Grube groß genug für beide sein.'::text),
(374605,41623,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо пес і далі копатиме, яма ... достатньо великою для обох.'::text,'буде'::text,'була б'::text,'була'::text,'Якщо пес і далі копатиме, яма буде достатньо великою для обох.'::text),
(374604,41623,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el perro sigue escarbando, el hoyo ... lo bastante grande para los dos.'::text,'será'::text,'sería'::text,'era'::text,'Si el perro sigue escarbando, el hoyo será lo bastante grande para los dos.'::text),
(374603,41623,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le chien continue de gratter, le trou ... assez grand pour eux deux.'::text,'sera'::text,'serait'::text,'était'::text,'Si le chien continue de gratter, le trou sera assez grand pour eux deux.'::text),
(374606,41623,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Köpek kazımaya devam ederse, çukur ikisi için de yeterince büyük ...'::text,'olacak'::text,'olurdu'::text,'oldu'::text,'Köpek kazımaya devam ederse, çukur ikisi için de yeterince büyük olacak.'::text),
(374607,41623,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a kutya tovább kapar, a gödör elég nagy ... mindkettőjüknek.'::text,'lesz'::text,'lenne'::text,'volt'::text,'Ha a kutya tovább kapar, a gödör elég nagy lesz mindkettőjüknek.'::text),
(374646,41628,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, er wird diese Grube bis Sonnenuntergang so tief ..., dass er eine Leiter braucht, echt.'::text,'gegraben haben'::text,'graben'::text,'gräbt'::text,'Bro, er wird diese Grube bis Sonnenuntergang so tief gegraben haben, dass er eine Leiter braucht, echt.'::text),
(374650,41628,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, до заходу сонця він ... цю яму так глибоко, що йому знадобиться драбина, чесно.'::text,'викопає'::text,'копатиме'::text,'копає'::text,'Бро, до заходу сонця він викопає цю яму так глибоко, що йому знадобиться драбина, чесно.'::text),
(374649,41628,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, para el atardecer él ... este hoyo tan hondo que va a necesitar una escalera, en serio.'::text,'habrá cavado'::text,'cavará'::text,'cava'::text,'Bro, para el atardecer él habrá cavado este hoyo tan hondo que va a necesitar una escalera, en serio.'::text),
(374648,41628,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, d''ici le coucher du soleil, il ... ce trou si profond qu''il va lui falloir une échelle, sérieux.'::text,'aura creusé'::text,'creusera'::text,'creuse'::text,'Frère, d''ici le coucher du soleil, il aura creusé ce trou si profond qu''il va lui falloir une échelle, sérieux.'::text),
(374651,41628,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o gün batımına kadar bu çukuru o kadar derin ... ki merdivene ihtiyacı olacak, cidden.'::text,'kazmış olacak'::text,'kazacak'::text,'kazıyor'::text,'Kanka, o gün batımına kadar bu çukuru o kadar derin kazmış olacak ki merdivene ihtiyacı olacak, cidden.'::text),
(374652,41628,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ő naplementére olyan mélyre ... ezt a gödröt, hogy létra kell majd neki, komolyan.'::text,'kiássa'::text,'ásni fogja'::text,'ássa'::text,'Tesó, ő naplementére olyan mélyre kiássa ezt a gödröt, hogy létra kell majd neki, komolyan.'::text),
(376806,41868,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um zwölf ... die Crew die letzte Szene der Produktion am Fenster.'::text,'dreht gerade'::text,'wird drehen'::text,'dreht'::text,'Morgen um zwölf dreht gerade die Crew die letzte Szene der Produktion am Fenster.'::text),
(376810,41868,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра опівдні знімальна група ... останню сцену постановки біля вікна.'::text,'зніматиме'::text,'зніме'::text,'знімає'::text,'Завтра опівдні знімальна група зніматиме останню сцену постановки біля вікна.'::text),
(376809,41868,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana al mediodía, el equipo ... la última escena de la producción junto a la ventana.'::text,'estará grabando'::text,'grabará'::text,'graba'::text,'Mañana al mediodía, el equipo estará grabando la última escena de la producción junto a la ventana.'::text),
(376808,41868,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à midi, l''équipe ... la dernière scène de la production près de la fenêtre.'::text,'sera en train de tourner'::text,'tournera'::text,'tourne'::text,'Demain à midi, l''équipe sera en train de tourner la dernière scène de la production près de la fenêtre.'::text),
(376811,41868,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın öğlen ekip, yapımın son sahnesini pencerenin yanında ...'::text,'çekiyor olacak'::text,'çekecek'::text,'çeker'::text,'Yarın öğlen ekip, yapımın son sahnesini pencerenin yanında çekiyor olacak.'::text),
(376812,41868,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap délben a stáb épp ... a produkció utolsó jelenetét az ablaknál.'::text,'forgatni fogja'::text,'leforgatja'::text,'forgatja'::text,'Holnap délben a stáb épp forgatni fogja a produkció utolsó jelenetét az ablaknál.'::text),
(376896,41878,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Crew klatschte, weil sie gerade die schwierigste Szene der Produktion ...'::text,'beendet hatte'::text,'beendete'::text,'beendet hat'::text,'Die Crew klatschte, weil sie gerade die schwierigste Szene der Produktion beendet hatte.'::text),
(376900,41878,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Знімальна група аплодувала, бо щойно ... найскладнішу сцену постановки.'::text,'завершила'::text,'завершувала'::text,'завершила'::text,'Знімальна група аплодувала, бо щойно завершила найскладнішу сцену постановки.'::text),
(376899,41878,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El equipo aplaudió porque ... la escena más difícil de la producción.'::text,'acababa de terminar'::text,'estaba terminando'::text,'acaba de terminar'::text,'El equipo aplaudió porque acababa de terminar la escena más difícil de la producción.'::text),
(376898,41878,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''équipe a applaudi parce qu''elle ... la scène la plus difficile de la production.'::text,'venait de terminer'::text,'était en train de terminer'::text,'vient de terminer'::text,'L''équipe a applaudi parce qu''elle venait de terminer la scène la plus difficile de la production.'::text),
(376901,41878,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ekip alkışladı çünkü yapımın en zor sahnesini daha yeni ...'::text,'bitirmişti'::text,'bitiriyordu'::text,'bitirdi'::text,'Ekip alkışladı çünkü yapımın en zor sahnesini daha yeni bitirmişti.'::text),
(376902,41878,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A stáb tapsolt, mert épp ... a produkció legnehezebb jelenetét.'::text,'befejezte'::text,'fejezte be'::text,'befejezte'::text,'A stáb tapsolt, mert épp befejezte a produkció legnehezebb jelenetét.'::text),
(331968,36886,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die blauen Kugeln sind an der Stange ..., deshalb bleiben sie an der Stange.'::text,'befestigt'::text,'befestigen'::text,'befestigend'::text,'Die blauen Kugeln sind an der Stange befestigt, deshalb bleiben sie an der Stange.'::text),
(331972,36886,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сині кульки ... до стрижня, тому вони залишаються на стрижні.'::text,'прикріплені'::text,'прикріплюють'::text,'прикріплювання'::text,'Сині кульки прикріплені до стрижня, тому вони залишаються на стрижні.'::text),
(331971,36886,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las bolas azules ... a la varilla, así que se quedan en la varilla.'::text,'están sujetas'::text,'sujetan'::text,'sujetando'::text,'Las bolas azules están sujetas a la varilla, así que se quedan en la varilla.'::text),
(331970,36886,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les boules bleues ... à la tige, donc elles restent sur la tige.'::text,'sont fixées'::text,'fixent'::text,'fixant'::text,'Les boules bleues sont fixées à la tige, donc elles restent sur la tige.'::text),
(331973,36886,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mavi toplar çubuğa ..., bu yüzden çubukta kalıyorlar.'::text,'takılı'::text,'takıyor'::text,'takma'::text,'Mavi toplar çubuğa takılı, bu yüzden çubukta kalıyorlar.'::text),
(331974,36886,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kék golyók a rúdhoz ..., így a rúdon maradnak.'::text,'vannak erősítve'::text,'erősítenek'::text,'erősítés'::text,'A kék golyók a rúdhoz vannak erősítve, így a rúdon maradnak.'::text),
(332031,36893,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerade jetzt ... die Hände eine rote Kugel an einem grünen Becherteil.'::text,'befestigen'::text,'befestigen'::text,'haben befestigt'::text,'Gerade jetzt befestigen die Hände eine rote Kugel an einem grünen Becherteil.'::text),
(332035,36893,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Прямо зараз руки ... червону кульку до зеленої чашечки.'::text,'прикріплюють'::text,'прикріплюють'::text,'прикріпили'::text,'Прямо зараз руки прикріплюють червону кульку до зеленої чашечки.'::text),
(332034,36893,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahora mismo, las manos ... una bola roja a una pieza verde en forma de vaso.'::text,'están sujetando'::text,'sujetan'::text,'han sujetado'::text,'Ahora mismo, las manos están sujetando una bola roja a una pieza verde en forma de vaso.'::text),
(332033,36893,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, les mains ... une boule rouge à une pièce verte en forme de gobelet.'::text,'fixent'::text,'fixent'::text,'ont fixé'::text,'En ce moment, les mains fixent une boule rouge à une pièce verte en forme de gobelet.'::text),
(332036,36893,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda eller kırmızı bir topu yeşil bir fincan parçasına ...'::text,'takıyor'::text,'takar'::text,'taktı'::text,'Şu anda eller kırmızı bir topu yeşil bir fincan parçasına takıyor.'::text),
(332037,36893,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp most a kezek egy piros golyót ... egy zöld pohárdarabhoz.'::text,'erősítenek'::text,'erősítenek'::text,'erősítettek'::text,'Épp most a kezek egy piros golyót erősítenek egy zöld pohárdarabhoz.'::text),
(348213,38691,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Lange vor der Scheidung ließen sie einen Juwelier ihr Hochzeitsdatum in die Ringe ...'::text,'gravieren'::text,'gravieren'::text,'graviert'::text,'Lange vor der Scheidung ließen sie einen Juwelier ihr Hochzeitsdatum in die Ringe gravieren.'::text),
(348217,38691,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Задовго до розлучення вони попросили ювеліра ... дату їхнього весілля всередині каблучок.'::text,'вигравіювати'::text,'вигравіювати'::text,'вигравіюваний'::text,'Задовго до розлучення вони попросили ювеліра вигравіювати дату їхнього весілля всередині каблучок.'::text),
(348216,38691,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mucho antes del divorcio, ellos hicieron que un joyero ... la fecha de su boda dentro de los anillos.'::text,'grabara'::text,'grabar'::text,'grabado'::text,'Mucho antes del divorcio, ellos hicieron que un joyero grabara la fecha de su boda dentro de los anillos.'::text),
(348215,38691,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bien avant le divorce, ils ont fait ... leur date de mariage à l''intérieur des alliances par un bijoutier.'::text,'graver'::text,'graver'::text,'gravé'::text,'Bien avant le divorce, ils ont fait graver leur date de mariage à l''intérieur des alliances par un bijoutier.'::text),
(348218,38691,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Boşanmadan çok önce onlar bir kuyumcuya düğün tarihlerini yüzüklerin içine ...'::text,'kazıttılar'::text,'kazıttılar'::text,'kazınmış'::text,'Boşanmadan çok önce onlar bir kuyumcuya düğün tarihlerini yüzüklerin içine kazıttılar.'::text),
(348219,38691,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jóval a válás előtt ők egy ékszerésszel ... a gyűrűk belsejébe az esküvőjük dátumát.'::text,'gravíroztatták'::text,'gravíroztatták'::text,'gravírozott'::text,'Jóval a válás előtt ők egy ékszerésszel gravíroztatták a gyűrűk belsejébe az esküvőjük dátumát.'::text),
(350895,38989,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Junge wünscht sich, dass die Ärztin ihn vor dem Mittagessen ...; jetzt hat er Hunger.'::text,'untersucht hätte'::text,'untersuchte'::text,'untersuchen würde'::text,'Der Junge wünscht sich, dass die Ärztin ihn vor dem Mittagessen untersucht hätte; jetzt hat er Hunger.'::text),
(350899,38989,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Хлопчик шкодує, що лікарка не ... його до обіду; тепер він голодний.'::text,'оглянула'::text,'оглянула'::text,'оглянула б'::text,'Хлопчик шкодує, що лікарка не оглянула його до обіду; тепер він голодний.'::text),
(350898,38989,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El niño desearía que la doctora lo ... antes de comer; ahora tiene hambre.'::text,'hubiera examinado'::text,'examinara'::text,'examinaría'::text,'El niño desearía que la doctora lo hubiera examinado antes de comer; ahora tiene hambre.'::text),
(350897,38989,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le garçon aimerait que la médecin l''... avant le déjeuner ; maintenant il a faim.'::text,'ait examiné'::text,'examine'::text,'examinerait'::text,'Le garçon aimerait que la médecin l''ait examiné avant le déjeuner ; maintenant il a faim.'::text),
(350900,38989,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çocuk, doktorun onu öğle yemeğinden önce ... diliyor; şimdi acıktı.'::text,'muayene etmiş olmasını'::text,'muayene etmesini'::text,'muayene edeceğini'::text,'Çocuk, doktorun onu öğle yemeğinden önce muayene etmiş olmasını diliyor; şimdi acıktı.'::text),
(350901,38989,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fiú azt szeretné, ha az orvosnő ebéd előtt ... őt; most éhes.'::text,'megvizsgálta volna'::text,'megvizsgálta'::text,'megvizsgálná'::text,'A fiú azt szeretné, ha az orvosnő ebéd előtt megvizsgálta volna őt; most éhes.'::text),
(379128,42126,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Lehrer hatte versprochen, dass die Reaktion für alle sicher ...'::text,'sein würde'::text,'sein wird'::text,'ist'::text,'Der Lehrer hatte versprochen, dass die Reaktion für alle sicher sein würde.'::text),
(379132,42126,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Учитель пообіцяв, що реакція ... безпечною для всіх.'::text,'буде'::text,'буде'::text,'є'::text,'Учитель пообіцяв, що реакція буде безпечною для всіх.'::text),
(379131,42126,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El profesor había prometido que la reacción ... segura para todos.'::text,'sería'::text,'será'::text,'es'::text,'El profesor había prometido que la reacción sería segura para todos.'::text),
(379130,42126,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le prof avait promis que la réaction ... sans danger pour tout le monde.'::text,'serait'::text,'sera'::text,'est'::text,'Le prof avait promis que la réaction serait sans danger pour tout le monde.'::text),
(379133,42126,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öğretmen tepkimenin herkes için güvenli ... söz vermişti.'::text,'olacağına'::text,'olacağına'::text,'olduğuna'::text,'Öğretmen tepkimenin herkes için güvenli olacağına söz vermişti.'::text),
(379134,42126,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tanár megígérte, hogy a reakció mindenkire nézve biztonságos ...'::text,'lesz'::text,'lesz'::text,NULL::text,'A tanár megígérte, hogy a reakció mindenkire nézve biztonságos lesz.'::text),
(379155,42129,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das ist ... Reaktion, die die Klasse je gesehen hat.'::text,'die größte'::text,'eine größte'::text,'größte'::text,'Das ist die größte Reaktion, die die Klasse je gesehen hat.'::text),
(379159,42129,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Це ... реакція, яку клас коли-небудь бачив.'::text,'найбільша'::text,'найбільша'::text,'найбільша'::text,'Це найбільша реакція, яку клас коли-небудь бачив.'::text),
(379158,42129,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Esta es ... reacción que la clase ha visto jamás.'::text,'la mayor'::text,'una mayor'::text,'mayor'::text,'Esta es la mayor reacción que la clase ha visto jamás.'::text),
(379157,42129,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'C''est ... réaction que la classe ait jamais vue.'::text,'la plus grande'::text,'une plus grande'::text,'plus grande'::text,'C''est la plus grande réaction que la classe ait jamais vue.'::text),
(379160,42129,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu, sınıfın şimdiye kadar gördüğü ... tepkime.'::text,'en büyük'::text,'en büyük'::text,'en büyük'::text,'Bu, sınıfın şimdiye kadar gördüğü en büyük tepkime.'::text),
(379161,42129,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez ... reakció, amit az osztály valaha látott.'::text,'a legnagyobb'::text,'egy legnagyobb'::text,'legnagyobb'::text,'Ez a legnagyobb reakció, amit az osztály valaha látott.'::text),
(341481,37943,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn zwei Leute im Armdrücken ..., bleiben beide Ellbogen auf den Polstern.'::text,'gegeneinander antreten'::text,'antreten werden'::text,'antraten'::text,'Wenn zwei Leute im Armdrücken gegeneinander antreten, bleiben beide Ellbogen auf den Polstern.'::text),
(341485,37943,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли двоє людей ... в армреслінгу, обидва лікті залишаються на подушках.'::text,'змагаються'::text,'змагатимуться'::text,'змагалися'::text,'Коли двоє людей змагаються в армреслінгу, обидва лікті залишаються на подушках.'::text),
(341484,37943,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si dos personas ... en un pulso, los dos codos se quedan sobre las almohadillas.'::text,'compiten'::text,'competirán'::text,'competían'::text,'Si dos personas compiten en un pulso, los dos codos se quedan sobre las almohadillas.'::text),
(341483,37943,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si deux personnes ... au bras de fer, les deux coudes restent sur les coussins.'::text,'s''affrontent'::text,'s''affronteront'::text,'s''affrontaient'::text,'Si deux personnes s''affrontent au bras de fer, les deux coudes restent sur les coussins.'::text),
(341486,37943,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İki kişi bilek güreşinde ..., iki dirsek de pedlerin üzerinde kalır.'::text,'yarışırsa'::text,'yarışacaksa'::text,'yarıştıysa'::text,'İki kişi bilek güreşinde yarışırsa, iki dirsek de pedlerin üzerinde kalır.'::text),
(341487,37943,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha két ember szkanderben ..., mindkét könyök a párnákon marad.'::text,'versenyez'::text,'versenyezni fog'::text,'versenyzett'::text,'Ha két ember szkanderben versenyez, mindkét könyök a párnákon marad.'::text),
(341526,37948,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, anscheinend hat er zugegeben, nur gegen sie ..., um die Menge zu beeindrucken.'::text,'angetreten zu sein'::text,'anzutreten'::text,'angetreten'::text,'Mädel, anscheinend hat er zugegeben, nur gegen sie angetreten zu sein, um die Menge zu beeindrucken.'::text),
(341530,37948,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дівчино, кажуть, він зізнався, що ... з нею лише щоб вразити натовп.'::text,'змагався'::text,'змагатися'::text,'змагався'::text,'Дівчино, кажуть, він зізнався, що змагався з нею лише щоб вразити натовп.'::text),
(341529,37948,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer él admitió ... con ella solo para impresionar al público.'::text,'haber competido'::text,'competir'::text,'compitió'::text,'Tía, al parecer él admitió haber competido con ella solo para impresionar al público.'::text),
(341528,37948,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment il a avoué ... avec elle juste pour impressionner la foule.'::text,'avoir concouru'::text,'concourir'::text,'a concouru'::text,'Meuf, apparemment il a avoué avoir concouru avec elle juste pour impressionner la foule.'::text),
(341531,37948,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, güya o sadece kalabalığı etkilemek için onunla ... itiraf etmiş.'::text,'yarıştığını'::text,'yarışmayı'::text,'yarıştı'::text,'Kızım, güya o sadece kalabalığı etkilemek için onunla yarıştığını itiraf etmiş.'::text),
(341532,37948,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag ő bevallotta, hogy csak azért ... vele, hogy lenyűgözze a tömeget.'::text,'versenyzett'::text,'versenyezni'::text,'versenyzett'::text,'Csajszi, állítólag ő bevallotta, hogy csak azért versenyzett vele, hogy lenyűgözze a tömeget.'::text),
(370308,41146,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... gerade mit seinen schlammigen Stiefeln auf der Fußmatte, als er plötzlich beschloss, reinzugehen.'::text,'stampfte'::text,'stampfte'::text,'hat gestampft'::text,'Er stampfte gerade mit seinen schlammigen Stiefeln auf der Fußmatte, als er plötzlich beschloss, reinzugehen.'::text),
(370312,41146,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... брудними чобітьми по килимку, коли раптом вирішив зайти всередину.'::text,'тупав'::text,'тупнув'::text,'тупнув'::text,'Він тупав брудними чобітьми по килимку, коли раптом вирішив зайти всередину.'::text),
(370311,41146,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... sus botas embarradas en el felpudo cuando de repente decidió entrar.'::text,'estaba sacudiendo'::text,'sacudió'::text,'ha sacudido'::text,'Él estaba sacudiendo sus botas embarradas en el felpudo cuando de repente decidió entrar.'::text),
(370310,41146,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... ses bottes boueuses sur le paillasson quand il a soudain décidé d''entrer.'::text,'tapait'::text,'a tapé'::text,'a tapé'::text,'Il tapait ses bottes boueuses sur le paillasson quand il a soudain décidé d''entrer.'::text),
(370313,41146,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O aniden içeri girmeye karar verdiğinde çamurlu botlarını paspasa ...'::text,'vuruyordu'::text,'vurdu'::text,'vurdu'::text,'O aniden içeri girmeye karar verdiğinde çamurlu botlarını paspasa vuruyordu.'::text),
(370314,41146,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő épp ... sáros csizmájával a lábtörlőn, amikor hirtelen úgy döntött, bemegy.'::text,'dobogott'::text,'dobbantott'::text,'dobbantott'::text,'Ő épp dobogott sáros csizmájával a lábtörlőn, amikor hirtelen úgy döntött, bemegy.'::text),
(370362,41152,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er wünscht sich, dass er die Stiefel ...! Der Schlamm hat den Boden komplett ruiniert!'::text,'ausgezogen hätte'::text,'auszog'::text,'ausziehen würde'::text,'Er wünscht sich, dass er die Stiefel ausgezogen hätte! Der Schlamm hat den Boden komplett ruiniert!'::text),
(370366,41152,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він шкодує, що не ... чоботи! Бруд повністю зіпсував підлогу!'::text,'зняв'::text,'зняв'::text,'зняв би'::text,'Він шкодує, що не зняв чоботи! Бруд повністю зіпсував підлогу!'::text),
(370365,41152,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Él desearía ... las botas! ¡El barro ha arruinado el suelo por completo!'::text,'haberse quitado'::text,'quitarse'::text,'quitarse'::text,'¡Él desearía haberse quitado las botas! ¡El barro ha arruinado el suelo por completo!'::text),
(370364,41152,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il aimerait ... ses bottes ! La boue a complètement ruiné le sol !'::text,'avoir enlevé'::text,'enlever'::text,'enlever'::text,'Il aimerait avoir enlevé ses bottes ! La boue a complètement ruiné le sol !'::text),
(370367,41152,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, botlarını ... diliyor! Çamur zemini tamamen mahvetti!'::text,'çıkarmış olmayı'::text,'çıkarmayı'::text,'çıkaracağını'::text,'O, botlarını çıkarmış olmayı diliyor! Çamur zemini tamamen mahvetti!'::text),
(370368,41152,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő azt kívánja, bárcsak ... a csizmáját! A sár teljesen tönkretette a padlót!'::text,'levette volna'::text,'levette'::text,'levenné'::text,'Ő azt kívánja, bárcsak levette volna a csizmáját! A sár teljesen tönkretette a padlót!'::text),
(370083,41121,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katastrophe! Während sie das zweite Regalbrett ..., wäre ihr Bücherstapel fast umgekippt!'::text,'montierte'::text,'montierte'::text,'montiert hat'::text,'Katastrophe! Während sie das zweite Regalbrett montierte, wäre ihr Bücherstapel fast umgekippt!'::text),
(370087,41121,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Катастрофа! Поки вона ... другу полицю, її стос книжок мало не завалився!'::text,'кріпила'::text,'прикріпила'::text,'прикріпила'::text,'Катастрофа! Поки вона кріпила другу полицю, її стос книжок мало не завалився!'::text),
(370086,41121,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Desastre! ¡Mientras ella ... la segunda balda, su pila de libros casi se derrumbó!'::text,'montaba'::text,'montó'::text,'ha montado'::text,'¡Desastre! ¡Mientras ella montaba la segunda balda, su pila de libros casi se derrumbó!'::text),
(370085,41121,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Catastrophe ! Pendant qu''elle ... la deuxième étagère, sa pile de livres a failli s''effondrer !'::text,'fixait'::text,'a fixé'::text,'a fixé'::text,'Catastrophe ! Pendant qu''elle fixait la deuxième étagère, sa pile de livres a failli s''effondrer !'::text),
(370088,41121,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Felaket! O, ikinci rafı ..., kitap yığını neredeyse çöküyordu!'::text,'takarken'::text,'taktığında'::text,'takmışken'::text,'Felaket! O, ikinci rafı takarken, kitap yığını neredeyse çöküyordu!'::text),
(370089,41121,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katasztrófa! Miközben ő ... a második polcot, a könyvkupaca majdnem összedőlt!'::text,'szerelte fel'::text,'felszerelte'::text,'felszerelte'::text,'Katasztrófa! Miközben ő szerelte fel a második polcot, a könyvkupaca majdnem összedőlt!'::text),
(352083,39121,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, wenn der Herbst das ganze Jahr dauern würde, ... ich jeden Tag in diesem Park, echt.'::text,'chillte'::text,'chille'::text,'chille'::text,'Bro, wenn der Herbst das ganze Jahr dauern würde, chillte ich jeden Tag in diesem Park, echt.'::text),
(352087,39121,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, якби осінь тривала цілий рік, я ... в цьому парку щодня, чесно.'::text,'чилив би'::text,'чилитиму'::text,'чилю'::text,'Бро, якби осінь тривала цілий рік, я чилив би в цьому парку щодня, чесно.'::text),
(352086,39121,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, si el otoño durara todo el año, yo ... en este parque todos los días, en serio.'::text,'estaría de chill'::text,'estaré de chill'::text,'estoy de chill'::text,'Bro, si el otoño durara todo el año, yo estaría de chill en este parque todos los días, en serio.'::text),
(352085,39121,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, si l''automne durait toute l''année, je ... dans ce parc tous les jours, sérieux.'::text,'chillerais'::text,'chillerai'::text,'chille'::text,'Frère, si l''automne durait toute l''année, je chillerais dans ce parc tous les jours, sérieux.'::text),
(352088,39121,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, sonbahar bütün yıl sürseydi, ben her gün bu parkta ..., cidden.'::text,'takılırdım'::text,'takılacağım'::text,'takılırım'::text,'Kanka, sonbahar bütün yıl sürseydi, ben her gün bu parkta takılırdım, cidden.'::text),
(352089,39121,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ha az ősz egész évben tartana, én minden nap ebben a parkban ..., komolyan.'::text,'chillelnék'::text,'chillelni fogok'::text,'chillelek'::text,'Tesó, ha az ősz egész évben tartana, én minden nap ebben a parkban chillelnék, komolyan.'::text),
(352119,39125,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mal ehrlich, du fängst Blätter, als ob gerade ... deines Lebens passiert.'::text,'der beste Herbst'::text,'ein bester Herbst'::text,'bester Herbst'::text,'Mal ehrlich, du fängst Blätter, als ob gerade der beste Herbst deines Lebens passiert.'::text),
(352123,39125,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не буду брехати, ти ловиш листя так, ніби зараз відбувається ... твого життя.'::text,'найкраща осінь'::text,'найкраща осінь'::text,'найкраща осінь'::text,'Не буду брехати, ти ловиш листя так, ніби зараз відбувається найкраща осінь твого життя.'::text),
(352122,39125,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No voy a mentir, tú atrapas hojas como si ... de tu vida estuviera pasando ahora.'::text,'el mejor otoño'::text,'un mejor otoño'::text,'mejor otoño'::text,'No voy a mentir, tú atrapas hojas como si el mejor otoño de tu vida estuviera pasando ahora.'::text),
(352121,39125,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, tu attrapes les feuilles comme si ... de ta vie se passait maintenant.'::text,'le plus bel automne'::text,'un plus bel automne'::text,'plus bel automne'::text,'Je vais pas mentir, tu attrapes les feuilles comme si le plus bel automne de ta vie se passait maintenant.'::text),
(352124,39125,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, sen yaprakları sanki hayatının ... şu an yaşanıyormuş gibi yakalıyorsun.'::text,'en güzel sonbaharı'::text,'en güzel sonbaharı'::text,'en güzel sonbaharı'::text,'Yalan yok, sen yaprakları sanki hayatının en güzel sonbaharı şu an yaşanıyormuş gibi yakalıyorsun.'::text),
(352125,39125,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hazudok, te úgy kapkodod a leveleket, mintha most zajlana életed ...'::text,'legjobb ősze'::text,'legjobb ősze'::text,'legjobb ősze'::text,'Nem hazudok, te úgy kapkodod a leveleket, mintha most zajlana életed legjobb ősze.'::text),
(394104,43790,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit ... das Flugzeug das Dorf gerade mit weiteren Kisten.'::text,'versorgt'::text,'versorgte'::text,'versorgt'::text,'Morgen um diese Zeit versorgt das Flugzeug das Dorf gerade mit weiteren Kisten.'::text),
(394108,43790,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра в цей час літак ... село новими ящиками.'::text,'забезпечуватиме'::text,'забезпечив'::text,'забезпечує'::text,'Завтра в цей час літак забезпечуватиме село новими ящиками.'::text),
(394107,43790,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a esta hora, el avión ... al pueblo con más cajas.'::text,'estará abasteciendo'::text,'abasteció'::text,'abastece'::text,'Mañana a esta hora, el avión estará abasteciendo al pueblo con más cajas.'::text),
(394106,43790,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à la même heure, l''avion ... le village avec d''autres caisses.'::text,'sera en train d''approvisionner'::text,'a approvisionné'::text,'approvisionne'::text,'Demain à la même heure, l''avion sera en train d''approvisionner le village avec d''autres caisses.'::text),
(394109,43790,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatte uçak köyü daha fazla sandıkla ...'::text,'ikmal ediyor olacak'::text,'ikmal etti'::text,'ikmal ediyor'::text,'Yarın bu saatte uçak köyü daha fazla sandıkla ikmal ediyor olacak.'::text),
(394110,43790,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor a repülő épp ... a falut újabb ládákkal.'::text,'látja el'::text,'ellátta'::text,'ellátja'::text,'Holnap ilyenkor a repülő épp látja el a falut újabb ládákkal.'::text),
(348717,38747,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... seit zwei Wochen jeden Morgen diese Dosis Öl.'::text,'nimmt'::text,'nimmt'::text,'nimmt'::text,'Sie nimmt seit zwei Wochen jeden Morgen diese Dosis Öl.'::text),
(348721,38747,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона вже два тижні щоранку ... цю дозу олії.'::text,'приймає'::text,'приймає'::text,'приймає'::text,'Вона вже два тижні щоранку приймає цю дозу олії.'::text),
(348720,38747,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... esta dosis de aceite cada mañana desde hace dos semanas.'::text,'ha estado tomando'::text,'está tomando'::text,'toma'::text,'Ella ha estado tomando esta dosis de aceite cada mañana desde hace dos semanas.'::text),
(348719,38747,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... cette dose d''huile chaque matin depuis deux semaines.'::text,'prend'::text,'prend'::text,'prend'::text,'Elle prend cette dose d''huile chaque matin depuis deux semaines.'::text),
(348722,38747,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O iki haftadır her sabah bu doz yağı ...'::text,'alıyor'::text,'alıyor'::text,'alır'::text,'O iki haftadır her sabah bu doz yağı alıyor.'::text),
(348723,38747,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő két hete minden reggel ... ezt az adag olajat.'::text,'szedi'::text,'szedi'::text,'szedi'::text,'Ő két hete minden reggel szedi ezt az adag olajat.'::text),
(348798,38756,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jahrelang ... sie diese Dosis genommen, bevor das Öl endlich nicht mehr wie ein Albtraum schmeckte!'::text,'hatte'::text,'hat'::text,'nimmt'::text,'Jahrelang hatte sie diese Dosis genommen, bevor das Öl endlich nicht mehr wie ein Albtraum schmeckte!'::text),
(348802,38756,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... цю дозу роками, поки олія нарешті не перестала смакувати як жахіття!'::text,'приймала'::text,'приймала'::text,'приймає'::text,'Вона приймала цю дозу роками, поки олія нарешті не перестала смакувати як жахіття!'::text),
(348801,38756,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ella ... esa dosis durante años antes de que el aceite por fin dejara de saber a pesadilla!'::text,'había estado tomando'::text,'ha estado tomando'::text,'está tomando'::text,'¡Ella había estado tomando esa dosis durante años antes de que el aceite por fin dejara de saber a pesadilla!'::text),
(348800,38756,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... cette dose pendant des années avant que l''huile arrête enfin d''avoir un goût de cauchemar !'::text,'avait pris'::text,'prend'::text,'prend'::text,'Elle avait pris cette dose pendant des années avant que l''huile arrête enfin d''avoir un goût de cauchemar !'::text),
(348803,38756,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, yağın tadı sonunda kâbus gibi olmaktan çıkana kadar yıllarca o dozu ...!'::text,'almıştı'::text,'alıyor'::text,'alıyor'::text,'O, yağın tadı sonunda kâbus gibi olmaktan çıkana kadar yıllarca o dozu almıştı!'::text),
(348804,38756,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő évekig ... azt az adagot, mire az olaj végre már nem volt olyan ízű, mint egy rémálom!'::text,'szedte'::text,'szedi'::text,'szedi'::text,'Ő évekig szedte azt az adagot, mire az olaj végre már nem volt olyan ízű, mint egy rémálom!'::text),
(388425,43159,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, dir macht es offensichtlich Spaß, von hier oben Obst zu ...'::text,'zerschmettern'::text,'zerschmettern'::text,'zerschmettern'::text,'Ehrlich, dir macht es offensichtlich Spaß, von hier oben Obst zu zerschmettern.'::text),
(388429,43159,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти явно кайфуєш, коли ... фрукти звідси згори.'::text,'розбиваєш'::text,'розбиваєш'::text,'розбиваєш'::text,'Чесно, ти явно кайфуєш, коли розбиваєш фрукти звідси згори.'::text),
(388428,43159,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, tú claramente disfrutas ... fruta desde aquí arriba.'::text,'reventando'::text,'reventar'::text,'reventar'::text,'Sinceramente, tú claramente disfrutas reventando fruta desde aquí arriba.'::text),
(388427,43159,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu aimes clairement ... des fruits depuis là-haut.'::text,'éclater'::text,'éclater'::text,'éclater'::text,'Franchement, tu aimes clairement éclater des fruits depuis là-haut.'::text),
(388430,43159,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, sen buradan meyve ... bayağı seviyorsun.'::text,'parçalamayı'::text,'parçalamayı'::text,'parçalamayı'::text,'Açıkçası, sen buradan meyve parçalamayı bayağı seviyorsun.'::text),
(388431,43159,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, te láthatóan élvezed, hogy innen fentről ... a gyümölcsöt.'::text,'szétloccsantod'::text,'szétloccsantod'::text,'szétloccsantod'::text,'Őszintén, te láthatóan élvezed, hogy innen fentről szétloccsantod a gyümölcsöt.'::text),
(388479,43165,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Kürbis nicht auf dem Beton zerplatzt wäre, ... er jetzt auf einem Tisch.'::text,'läge'::text,'hätte gelegen'::text,'wird liegen'::text,'Wenn der Kürbis nicht auf dem Beton zerplatzt wäre, läge er jetzt auf einem Tisch.'::text),
(388483,43165,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби гарбуз не розбився об бетон, він зараз ... на столі.'::text,'лежав би'::text,'лежав би'::text,'лежатиме'::text,'Якби гарбуз не розбився об бетон, він зараз лежав би на столі.'::text),
(388482,43165,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la calabaza no se hubiera estrellado contra el hormigón, esta ... ahora en una mesa.'::text,'estaría'::text,'habría estado'::text,'estará'::text,'Si la calabaza no se hubiera estrellado contra el hormigón, esta estaría ahora en una mesa.'::text),
(388481,43165,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la citrouille ne s''était pas écrasée sur le béton, elle ... sur une table maintenant.'::text,'serait'::text,'aurait été'::text,'sera'::text,'Si la citrouille ne s''était pas écrasée sur le béton, elle serait sur une table maintenant.'::text),
(388484,43165,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Balkabağı betona çarpıp parçalanmasaydı, o şimdi bir masanın üstünde ...'::text,'olurdu'::text,'olmuş olurdu'::text,'olacak'::text,'Balkabağı betona çarpıp parçalanmasaydı, o şimdi bir masanın üstünde olurdu.'::text),
(388485,43165,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a tök nem loccsant volna szét a betonon, az most egy asztalon ...'::text,'lenne'::text,'lett volna'::text,'lesz'::text,'Ha a tök nem loccsant volna szét a betonon, az most egy asztalon lenne.'::text),
(388524,43170,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... gerade an dem weißen Tuch, als ihre Nachbarin sie rief. Perfektes Timing, offensichtlich.'::text,'roch'::text,'roch'::text,'hat gerochen'::text,'Sie roch gerade an dem weißen Tuch, als ihre Nachbarin sie rief. Perfektes Timing, offensichtlich.'::text),
(388528,43170,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... біле полотно, коли її покликала сусідка. Ідеальний таймінг, очевидно.'::text,'нюхала'::text,'понюхала'::text,'понюхала'::text,'Вона нюхала біле полотно, коли її покликала сусідка. Ідеальний таймінг, очевидно.'::text),
(388527,43170,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... el paño blanco cuando la llamó su vecina. Un timing perfecto, obviamente.'::text,'estaba oliendo'::text,'olió'::text,'ha olido'::text,'Ella estaba oliendo el paño blanco cuando la llamó su vecina. Un timing perfecto, obviamente.'::text),
(388526,43170,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... le tissu blanc quand sa voisine l''a appelée. Timing parfait, évidemment.'::text,'sentait'::text,'a senti'::text,'a senti'::text,'Elle sentait le tissu blanc quand sa voisine l''a appelée. Timing parfait, évidemment.'::text),
(388529,43170,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O beyaz bezi ..., tam da komşusu ona seslendiğinde. Mükemmel zamanlama, belli ki.'::text,'kokluyordu'::text,'kokladı'::text,'kokladı'::text,'O beyaz bezi kokluyordu, tam da komşusu ona seslendiğinde. Mükemmel zamanlama, belli ki.'::text),
(388530,43170,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő épp ... a fehér kendőt, amikor a szomszédja szólt neki. Tökéletes időzítés, nyilván.'::text,'szagolgatta'::text,'megszagolta'::text,'megszagolta'::text,'Ő épp szagolgatta a fehér kendőt, amikor a szomszédja szólt neki. Tökéletes időzítés, nyilván.'::text),
(388569,43175,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, anscheinend benutzt die Frau, ... Wäsche nach Meer riecht, nie einen Trockner.'::text,'deren'::text,'die'::text,'welche'::text,'Hör mal, anscheinend benutzt die Frau, deren Wäsche nach Meer riecht, nie einen Trockner.'::text),
(388573,43175,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, жінка, ... білизна пахне морем, ніколи не користується сушаркою.'::text,'чия'::text,'яка'::text,'що'::text,'Слухай, кажуть, жінка, чия білизна пахне морем, ніколи не користується сушаркою.'::text),
(388572,43175,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, al parecer la mujer, ... ropa huele a mar, nunca usa secadora.'::text,'cuya'::text,'que'::text,'la cual'::text,'Oye, al parecer la mujer, cuya ropa huele a mar, nunca usa secadora.'::text),
(388571,43175,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment la femme, ... le linge sent la mer, n''utilise jamais de sèche-linge.'::text,'dont'::text,'qui'::text,'que'::text,'Écoute, apparemment la femme, dont le linge sent la mer, n''utilise jamais de sèche-linge.'::text),
(388574,43175,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, güya ... çamaşırları deniz kokan kadın hiç kurutma makinesi kullanmıyormuş.'::text,''::text,NULL::text,NULL::text,'Dinle, güya çamaşırları deniz kokan kadın hiç kurutma makinesi kullanmıyormuş.'::text),
(388575,43175,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag az a nő, ... ruhái tengerillatúak, soha nem használ szárítógépet.'::text,'akinek a'::text,'aki'::text,'amely'::text,'Figyelj, állítólag az a nő, akinek a ruhái tengerillatúak, soha nem használ szárítógépet.'::text),
(364341,40483,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Also, ich habe gehört, dass sie seit sieben Wäsche ..., und sie ist immer noch nicht fertig.'::text,'aufhängt'::text,'aufgehängt hat'::text,'aufhängte'::text,'Also, ich habe gehört, dass sie seit sieben Wäsche aufhängt, und sie ist immer noch nicht fertig.'::text),
(364345,40483,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Отже, я чула, що вона ... білизну з сьомої, і досі не закінчила.'::text,'вішає'::text,'повісила'::text,'повісила'::text,'Отже, я чула, що вона вішає білизну з сьомої, і досі не закінчила.'::text),
(364344,40483,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, yo oí que ella ... ropa desde las siete, y todavía no ha terminado.'::text,'ha estado tendiendo'::text,'ha tendido'::text,'tendió'::text,'Vale, yo oí que ella ha estado tendiendo ropa desde las siete, y todavía no ha terminado.'::text),
(364343,40483,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, j''ai entendu qu''elle ... du linge depuis sept heures, et elle n''a toujours pas fini.'::text,'étend'::text,'a étendu'::text,'a étendu'::text,'Bon, j''ai entendu qu''elle étend du linge depuis sept heures, et elle n''a toujours pas fini.'::text),
(364346,40483,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, ben duydum ki o saat yediden beri çamaşır ..., ve hâlâ bitirmedi.'::text,'asıyormuş'::text,'asmış'::text,'astı'::text,'Tamam, ben duydum ki o saat yediden beri çamaşır asıyormuş, ve hâlâ bitirmedi.'::text),
(364347,40483,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval én azt hallottam, hogy ő hét óta ... a ruhákat, és még mindig nem végzett.'::text,'teregeti'::text,'kiteregette'::text,'kiteregette'::text,'Szóval én azt hallottam, hogy ő hét óta teregeti a ruhákat, és még mindig nem végzett.'::text),
(364404,40490,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als die Wäsche trocken war, ... sie schon stundenlang auf der windigen Terrasse, offensichtlich ein schrecklicher Tag.'::text,'stand'::text,'stand'::text,'hat gestanden'::text,'Als die Wäsche trocken war, stand sie schon stundenlang auf der windigen Terrasse, offensichtlich ein schrecklicher Tag.'::text),
(364408,40490,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли білизна висохла, вона вже годинами ... на вітряній терасі, очевидно, жахливий день.'::text,'стояла'::text,'стояла'::text,'стояла'::text,'Коли білизна висохла, вона вже годинами стояла на вітряній терасі, очевидно, жахливий день.'::text),
(364407,40490,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando la ropa se secó, ella ... horas de pie en la terraza ventosa, obviamente un día terrible.'::text,'había estado'::text,'estaba'::text,'ha estado'::text,'Cuando la ropa se secó, ella había estado horas de pie en la terraza ventosa, obviamente un día terrible.'::text),
(364406,40490,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand le linge a séché, elle ... sur la terrasse venteuse depuis des heures, évidemment une journée horrible.'::text,'était'::text,'était'::text,'est restée'::text,'Quand le linge a séché, elle était sur la terrasse venteuse depuis des heures, évidemment une journée horrible.'::text),
(364409,40490,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çamaşırlar kuruduğunda o saatlerdir rüzgârlı terasta ..., belli ki berbat bir gün.'::text,'duruyordu'::text,'duruyordu'::text,'durdu'::text,'Çamaşırlar kuruduğunda o saatlerdir rüzgârlı terasta duruyordu, belli ki berbat bir gün.'::text),
(364410,40490,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a ruha megszáradt, ő már órák óta ... a szeles teraszon, nyilván szörnyű nap.'::text,'állt'::text,'állt'::text,'állt'::text,'Mire a ruha megszáradt, ő már órák óta állt a szeles teraszon, nyilván szörnyű nap.'::text),
(379551,42173,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Teich letzten Sommer ausgetrocknet wäre, ... dieses Schilf jetzt nicht hier.'::text,'wüchse'::text,'wäre gewachsen'::text,'wird wachsen'::text,'Wenn der Teich letzten Sommer ausgetrocknet wäre, wüchse dieses Schilf jetzt nicht hier.'::text),
(379555,42173,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби ставок висох минулого літа, цей очерет зараз не ... тут.'::text,'ріс би'::text,'виріс би'::text,'ростиме'::text,'Якби ставок висох минулого літа, цей очерет зараз не ріс би тут.'::text),
(379554,42173,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el estanque se hubiera secado el verano pasado, estos juncos no ... aquí ahora.'::text,'estarían creciendo'::text,'habrían crecido'::text,'crecerán'::text,'Si el estanque se hubiera secado el verano pasado, estos juncos no estarían creciendo aquí ahora.'::text),
(379553,42173,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si l''étang s''était asséché l''été dernier, ces roseaux ne ... pas ici maintenant.'::text,'pousseraient'::text,'auraient poussé'::text,'pousseront'::text,'Si l''étang s''était asséché l''été dernier, ces roseaux ne pousseraient pas ici maintenant.'::text),
(379556,42173,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gölet geçen yaz kurusaydı, bu sazlar şimdi burada ...'::text,'büyüyor olmazdı'::text,'büyümemiş olurdu'::text,'büyümeyecek'::text,'Gölet geçen yaz kurusaydı, bu sazlar şimdi burada büyüyor olmazdı.'::text),
(379557,42173,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a tó tavaly nyáron kiszáradt volna, ez a nád most nem ... itt.'::text,'nőne'::text,'nőtt volna'::text,'fog nőni'::text,'Ha a tó tavaly nyáron kiszáradt volna, ez a nád most nem nőne itt.'::text),
(380892,42322,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Reiterin soll schon früher an den Pyramiden auf einem Kamel ...'::text,'geritten sein'::text,'reiten'::text,'reitend'::text,'Die Reiterin soll schon früher an den Pyramiden auf einem Kamel geritten sein.'::text),
(380896,42322,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кажуть, що вершниця вже раніше ... на верблюді біля пірамід.'::text,'їздила'::text,'їздити'::text,'їзда'::text,'Кажуть, що вершниця вже раніше їздила на верблюді біля пірамід.'::text),
(380895,42322,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se dice que la jinete ya ... en camello en las pirámides.'::text,'había montado'::text,'monta'::text,'montando'::text,'Se dice que la jinete ya había montado en camello en las pirámides.'::text),
(380894,42322,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On dit que la cavalière ... à dos de chameau aux pyramides.'::text,'est déjà montée'::text,'monte'::text,'montant'::text,'On dit que la cavalière est déjà montée à dos de chameau aux pyramides.'::text),
(380897,42322,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Binicinin daha önce piramitlerde deveye ... söyleniyor.'::text,'binmiş olduğu'::text,'bindiği'::text,'binmesi'::text,'Binicinin daha önce piramitlerde deveye binmiş olduğu söyleniyor.'::text),
(380898,42322,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Állítólag a lovas korábban már ... tevén a piramisoknál.'::text,'lovagolt'::text,'lovagol'::text,'lovaglás'::text,'Állítólag a lovas korábban már lovagolt tevén a piramisoknál.'::text),
(397776,44198,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Händler bot an, uns eine Schaufel Kurkuma gratis zu ...'::text,'geben'::text,'geben'::text,'gegeben haben'::text,'Der Händler bot an, uns eine Schaufel Kurkuma gratis zu geben.'::text),
(397780,44198,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Торговець запропонував ... нам совок куркуми безкоштовно.'::text,'дати'::text,'давання'::text,'дати'::text,'Торговець запропонував дати нам совок куркуми безкоштовно.'::text),
(397779,44198,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El comerciante se ofreció a ... una cucharada de cúrcuma gratis.'::text,'darnos'::text,'dándonos'::text,'habernos dado'::text,'El comerciante se ofreció a darnos una cucharada de cúrcuma gratis.'::text),
(397778,44198,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le marchand a proposé de nous ... une pelle de curcuma gratuitement.'::text,'donner'::text,'donner'::text,'avoir donné'::text,'Le marchand a proposé de nous donner une pelle de curcuma gratuitement.'::text),
(397781,44198,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tüccar bize bedava bir kepçe zerdeçal ... teklif etti.'::text,'vermeyi'::text,'vermeyi'::text,'vermiş olmayı'::text,'Tüccar bize bedava bir kepçe zerdeçal vermeyi teklif etti.'::text),
(397782,44198,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kereskedő felajánlotta, hogy ... nekünk ingyen egy lapát kurkumát.'::text,'ad'::text,'ad'::text,'adott'::text,'A kereskedő felajánlotta, hogy ad nekünk ingyen egy lapát kurkumát.'::text),
(349716,38858,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Warte, anscheinend wird hier jeder neue Kollege mit einem Ellbogen-Check ...'::text,'begrüßt'::text,'begrüßt'::text,'begrüßend'::text,'Warte, anscheinend wird hier jeder neue Kollege mit einem Ellbogen-Check begrüßt.'::text),
(349720,38858,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Стривай, кажуть, кожного нового колегу тут ... ударом ліктів.'::text,'вітають'::text,'вітає'::text,'вітання'::text,'Стривай, кажуть, кожного нового колегу тут вітають ударом ліктів.'::text),
(349719,38858,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Espera, al parecer aquí a cada nuevo compañero ... con un choque de codos.'::text,'se le saluda'::text,'saluda'::text,'saludando'::text,'Espera, al parecer aquí a cada nuevo compañero se le saluda con un choque de codos.'::text),
(349718,38858,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Attends, apparemment chaque nouveau collègue ... avec un check du coude ici.'::text,'est accueilli'::text,'accueille'::text,'accueillant'::text,'Attends, apparemment chaque nouveau collègue est accueilli avec un check du coude ici.'::text),
(349721,38858,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bekle, güya burada her yeni iş arkadaşı dirsek tokuşturarak ...'::text,'karşılanıyor'::text,'karşılıyor'::text,'karşılama'::text,'Bekle, güya burada her yeni iş arkadaşı dirsek tokuşturarak karşılanıyor.'::text),
(349722,38858,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Várj, állítólag itt minden új kollégát könyökpacsival ...'::text,'üdvözölnek'::text,'üdvözöl'::text,'üdvözlés'::text,'Várj, állítólag itt minden új kollégát könyökpacsival üdvözölnek.'::text),
(350139,38905,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Botschaft, ... Flagge über dem Eingang hängt, nimmt auch in der Dämmerung noch Dokumente an.'::text,'deren'::text,'die'::text,'welche'::text,'Die Botschaft, deren Flagge über dem Eingang hängt, nimmt auch in der Dämmerung noch Dokumente an.'::text),
(350143,38905,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Посольство, ... прапор висить над входом, досі приймає документи в сутінках.'::text,'чий'::text,'яке'::text,'що'::text,'Посольство, чий прапор висить над входом, досі приймає документи в сутінках.'::text),
(350142,38905,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La embajada, ... bandera cuelga sobre la entrada, todavía acepta documentos al anochecer.'::text,'cuya'::text,'que'::text,'la cual'::text,'La embajada, cuya bandera cuelga sobre la entrada, todavía acepta documentos al anochecer.'::text),
(350141,38905,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''ambassade, ... le drapeau flotte au-dessus de l''entrée, accepte encore des documents au crépuscule.'::text,'dont'::text,'qui'::text,'que'::text,'L''ambassade, dont le drapeau flotte au-dessus de l''entrée, accepte encore des documents au crépuscule.'::text),
(350144,38905,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... bayrağı girişin üstünde asılı olan büyükelçilik, alacakaranlıkta hâlâ belge kabul ediyor.'::text,''::text,NULL::text,NULL::text,'Bayrağı girişin üstünde asılı olan büyükelçilik, alacakaranlıkta hâlâ belge kabul ediyor.'::text),
(350145,38905,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nagykövetség, ... zászlaja a bejárat fölött lóg, alkonyatkor is még átvesz dokumentumokat.'::text,'amelynek a'::text,'amely'::text,'ami'::text,'A nagykövetség, amelynek a zászlaja a bejárat fölött lóg, alkonyatkor is még átvesz dokumentumokat.'::text),
(368040,40894,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der riesige Wal ... neben dem Boot eine hohe Fontäne.'::text,'blies'::text,'wurde geblasen'::text,'blasend'::text,'Der riesige Wal blies neben dem Boot eine hohe Fontäne.'::text),
(368044,40894,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Величезний кит ... високий стовп бризок біля човна.'::text,'випустив'::text,'був випущений'::text,'випускання'::text,'Величезний кит випустив високий стовп бризок біля човна.'::text),
(368043,40894,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La enorme ballena ... una alta columna de agua junto al barco.'::text,'lanzó'::text,'fue lanzada'::text,'lanzando'::text,'La enorme ballena lanzó una alta columna de agua junto al barco.'::text),
(368042,40894,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''énorme baleine ... une haute colonne d''écume à côté du bateau.'::text,'a soufflé'::text,'a été soufflée'::text,'soufflant'::text,'L''énorme baleine a soufflé une haute colonne d''écume à côté du bateau.'::text),
(368045,40894,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devasa balina teknenin yanında yüksek bir su sütunu ...'::text,'püskürttü'::text,'püskürtüldü'::text,'püskürtme'::text,'Devasa balina teknenin yanında yüksek bir su sütunu püskürttü.'::text),
(368046,40894,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az óriási bálna magas vízpermet-oszlopot ... a hajó mellett.'::text,'fújt'::text,'ki lett fújva'::text,'fújva'::text,'Az óriási bálna magas vízpermet-oszlopot fújt a hajó mellett.'::text),
(403455,44829,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Kaffee dampft noch, also ... er nicht schon vor langer Zeit am Arbeitsplatz angekommen sein.'::text,'kann'::text,'darf'::text,'sollte'::text,'Der Kaffee dampft noch, also kann er nicht schon vor langer Zeit am Arbeitsplatz angekommen sein.'::text),
(403459,44829,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кава ще парує, тож він не ... прийти на робоче місце давно.'::text,'міг'::text,'смів'::text,'мав'::text,'Кава ще парує, тож він не міг прийти на робоче місце давно.'::text),
(403458,44829,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El café todavía humea, así que él no ... llegado al trabajo hace mucho.'::text,'puede haber'::text,'debe haber'::text,'debería haber'::text,'El café todavía humea, así que él no puede haber llegado al trabajo hace mucho.'::text),
(403457,44829,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le café fume encore, donc il ... arrivé au travail il y a longtemps.'::text,'ne peut pas être'::text,'ne doit pas être'::text,'n''aurait pas dû être'::text,'Le café fume encore, donc il ne peut pas être arrivé au travail il y a longtemps.'::text),
(403460,44829,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kahve hâlâ tütüyor, yani o iş yerine uzun zaman önce ...'::text,'gelmiş olamaz'::text,'gelmemiş olmalı'::text,'gelmemeliydi'::text,'Kahve hâlâ tütüyor, yani o iş yerine uzun zaman önce gelmiş olamaz.'::text),
(403461,44829,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kávé még gőzölög, szóval ő ... már régen a munkahelyre.'::text,'nem érkezhetett meg'::text,'nem szabadott megérkeznie'::text,'nem kellett volna megérkeznie'::text,'A kávé még gőzölög, szóval ő nem érkezhetett meg már régen a munkahelyre.'::text),
(340833,37871,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er will seinem Kollegen die Hand ..., weil man für einen Handschlag zwei Leute braucht.'::text,'geben'::text,'geben'::text,'geben'::text,'Er will seinem Kollegen die Hand geben, weil man für einen Handschlag zwei Leute braucht.'::text),
(340837,37871,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він хоче ... руку своєму колезі, бо для рукостискання потрібні двоє.'::text,'потиснути'::text,'потискання'::text,'потиснути'::text,'Він хоче потиснути руку своєму колезі, бо для рукостискання потрібні двоє.'::text),
(340836,37871,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él quiere ... la mano a su compañero porque un apretón de manos necesita a dos personas.'::text,'estrechar'::text,'estrechando'::text,'estrechar'::text,'Él quiere estrechar la mano a su compañero porque un apretón de manos necesita a dos personas.'::text),
(340835,37871,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il veut ... la main à son collègue parce qu''une poignée de main demande deux personnes.'::text,'serrer'::text,'serrer'::text,'serrer'::text,'Il veut serrer la main à son collègue parce qu''une poignée de main demande deux personnes.'::text),
(340838,37871,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O iş arkadaşıyla ... istiyor çünkü tokalaşmak için iki kişi gerekir.'::text,'tokalaşmak'::text,'tokalaşmak'::text,'tokalaşmak'::text,'O iş arkadaşıyla tokalaşmak istiyor çünkü tokalaşmak için iki kişi gerekir.'::text),
(340839,37871,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő kezet akar ... a kollégájával, mert a kézfogáshoz két ember kell.'::text,'fogni'::text,'fogni'::text,'fogni'::text,'Ő kezet akar fogni a kollégájával, mert a kézfogáshoz két ember kell.'::text),
(340878,37876,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Warte, anscheinend ... sein Kollege bis Freitag genau ein Jahr neben ihm.'::text,'sitzt'::text,'sitzt'::text,'sitzt'::text,'Warte, anscheinend sitzt sein Kollege bis Freitag genau ein Jahr neben ihm.'::text),
(340882,37876,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Стривай, кажуть, до п''ятниці його колега ... поруч із ним рівно рік.'::text,'сидітиме'::text,'сидітиме'::text,'сидітиме'::text,'Стривай, кажуть, до п''ятниці його колега сидітиме поруч із ним рівно рік.'::text),
(340881,37876,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Espera, al parecer para el viernes su compañero ... sentado a su lado exactamente un año.'::text,'habrá estado'::text,'estará'::text,'se sentará'::text,'Espera, al parecer para el viernes su compañero habrá estado sentado a su lado exactamente un año.'::text),
(340880,37876,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Attends, apparemment d''ici vendredi son collègue ... assis à côté de lui depuis exactement un an.'::text,'sera'::text,'sera'::text,'sera'::text,'Attends, apparemment d''ici vendredi son collègue sera assis à côté de lui depuis exactement un an.'::text),
(340883,37876,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bekle, güya cuma gününe kadar iş arkadaşı tam bir yıldır onun yanında ...'::text,'oturuyor olacak'::text,'oturuyor olacak'::text,'oturacak'::text,'Bekle, güya cuma gününe kadar iş arkadaşı tam bir yıldır onun yanında oturuyor olacak.'::text),
(340884,37876,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Várj, állítólag péntekre a kollégája pontosan egy éve ... mellette.'::text,'fog ülni'::text,'fog ülni'::text,'fog ülni'::text,'Várj, állítólag péntekre a kollégája pontosan egy éve fog ülni mellette.'::text),
(360390,40044,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Firma ... monatelang einen neuen Manager gesucht, bevor sie endlich diesen jungen Mann eingestellt hat.'::text,'hatte'::text,'hat'::text,'suchte'::text,'Die Firma hatte monatelang einen neuen Manager gesucht, bevor sie endlich diesen jungen Mann eingestellt hat.'::text),
(360394,40044,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Компанія ... нового менеджера місяцями, поки нарешті не найняла цього молодого чоловіка.'::text,'шукала'::text,'шукає'::text,'шукала'::text,'Компанія шукала нового менеджера місяцями, поки нарешті не найняла цього молодого чоловіка.'::text),
(360393,40044,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La empresa ... un nuevo gerente durante meses antes de contratar por fin a este joven.'::text,'había estado buscando'::text,'ha estado buscando'::text,'estaba buscando'::text,'La empresa había estado buscando un nuevo gerente durante meses antes de contratar por fin a este joven.'::text),
(360392,40044,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''entreprise ... un nouveau manager depuis des mois quand elle a enfin embauché ce jeune homme.'::text,'cherchait'::text,'cherche'::text,'cherchait'::text,'L''entreprise cherchait un nouveau manager depuis des mois quand elle a enfin embauché ce jeune homme.'::text),
(360395,40044,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şirket sonunda bu genç adamı işe almadan önce aylarca yeni bir müdür ...'::text,'arıyordu'::text,'arıyor'::text,'arıyordu'::text,'Şirket sonunda bu genç adamı işe almadan önce aylarca yeni bir müdür arıyordu.'::text),
(360396,40044,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A cég hónapokig ... új menedzsert, mire végre felvette ezt a fiatalembert.'::text,'keresett'::text,'keres'::text,'keresett'::text,'A cég hónapokig keresett új menedzsert, mire végre felvette ezt a fiatalembert.'::text),
(342228,38026,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, anscheinend ist ihm, während er den Vertrag ..., fast der Stift ausgegangen.'::text,'unterschrieb'::text,'unterschrieb'::text,'unterschrieben hat'::text,'Mädel, anscheinend ist ihm, während er den Vertrag unterschrieb, fast der Stift ausgegangen.'::text),
(342232,38026,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дівчино, кажуть, поки він ... контракт, у нього мало не скінчилася ручка.'::text,'підписував'::text,'підписав'::text,'підписав'::text,'Дівчино, кажуть, поки він підписував контракт, у нього мало не скінчилася ручка.'::text),
(342231,38026,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer, mientras él ... el contrato, casi se le acabó el boli.'::text,'firmaba'::text,'firmó'::text,'ha firmado'::text,'Tía, al parecer, mientras él firmaba el contrato, casi se le acabó el boli.'::text),
(342230,38026,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment pendant qu''il ... le contrat, son stylo a failli le lâcher.'::text,'signait'::text,'a signé'::text,'a signé'::text,'Meuf, apparemment pendant qu''il signait le contrat, son stylo a failli le lâcher.'::text),
(342233,38026,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, güya o sözleşmeyi ..., kalemi neredeyse bitiyordu.'::text,'imzalarken'::text,'imzaladığında'::text,'imzaladı'::text,'Kızım, güya o sözleşmeyi imzalarken, kalemi neredeyse bitiyordu.'::text),
(342234,38026,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag miközben ő ... a szerződést, majdnem kifogyott a tolla.'::text,'írta alá'::text,'aláírta'::text,'aláírta'::text,'Csajszi, állítólag miközben ő írta alá a szerződést, majdnem kifogyott a tolla.'::text),
(342273,38031,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er setzt seinen Namen auf die letzte Seite ... für seinen neuen Job, und das Büro klatscht.'::text,'des Vertrags'::text,'eines Vertrags'::text,'Vertrags'::text,'Er setzt seinen Namen auf die letzte Seite des Vertrags für seinen neuen Job, und das Büro klatscht.'::text),
(342277,38031,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ставить своє ім''я на останній сторінці ... на нову роботу, і офіс аплодує.'::text,'контракту'::text,'контракту'::text,'контракту'::text,'Він ставить своє ім''я на останній сторінці контракту на нову роботу, і офіс аплодує.'::text),
(342276,38031,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él pone su nombre en la última página ... de su nuevo trabajo, y la oficina aplaude.'::text,'del contrato'::text,'de un contrato'::text,'de contrato'::text,'Él pone su nombre en la última página del contrato de su nuevo trabajo, y la oficina aplaude.'::text),
(342275,38031,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il met son nom sur la dernière page ... pour son nouveau job, et le bureau applaudit.'::text,'du contrat'::text,'d''un contrat'::text,'de contrat'::text,'Il met son nom sur la dernière page du contrat pour son nouveau job, et le bureau applaudit.'::text),
(342278,38031,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O yeni işi için ... son sayfasına adını yazıyor ve ofis alkışlıyor.'::text,'sözleşmenin'::text,'bir sözleşmenin'::text,'sözleşmenin'::text,'O yeni işi için sözleşmenin son sayfasına adını yazıyor ve ofis alkışlıyor.'::text),
(342279,38031,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő a nevét ... utolsó oldalára írja az új munkájához, és az iroda tapsol.'::text,'a szerződés'::text,'egy szerződés'::text,'szerződés'::text,'Ő a nevét a szerződés utolsó oldalára írja az új munkájához, és az iroda tapsol.'::text),
(339222,37692,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als er aufsah, ... das Chaos schon den ganzen Wohnzimmerboden bedeckt.'::text,'hatte'::text,'hat'::text,'bedeckte'::text,'Als er aufsah, hatte das Chaos schon den ganzen Wohnzimmerboden bedeckt.'::text),
(339226,37692,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли він підвів очі, хаос уже ... всю підлогу вітальні.'::text,'вкрив'::text,'вкрив'::text,'вкрив'::text,'Коли він підвів очі, хаос уже вкрив всю підлогу вітальні.'::text),
(339225,37692,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando él levantó la vista, el caos ya ... todo el suelo del salón.'::text,'había cubierto'::text,'ha cubierto'::text,'cubrió'::text,'Para cuando él levantó la vista, el caos ya había cubierto todo el suelo del salón.'::text),
(339224,37692,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand il a levé les yeux, le chaos ... tout le sol du salon.'::text,'avait recouvert'::text,'a recouvert'::text,'a recouvert'::text,'Quand il a levé les yeux, le chaos avait recouvert tout le sol du salon.'::text),
(339227,37692,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O başını kaldırdığında kaos bütün oturma odası zeminini ...'::text,'kaplamıştı'::text,'kapladı'::text,'kapladı'::text,'O başını kaldırdığında kaos bütün oturma odası zeminini kaplamıştı.'::text),
(339228,37692,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire ő felnézett, a káosz már ... az egész nappali padlóját.'::text,'beterítette'::text,'beterítette'::text,'beterítette'::text,'Mire ő felnézett, a káosz már beterítette az egész nappali padlóját.'::text),
(350310,38924,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die jungen Kletterer ... sie mit lautem Jubel weiter an.'::text,'feuern'::text,'feuern'::text,'feuern'::text,'Die jungen Kletterer feuern sie mit lautem Jubel weiter an.'::text),
(350314,38924,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Молоді скелелази й далі ... її гучними вигуками.'::text,'підбадьорюють'::text,'підбадьорювати'::text,'підбадьорюють'::text,'Молоді скелелази й далі підбадьорюють її гучними вигуками.'::text),
(350313,38924,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los jóvenes escaladores siguen ... con fuertes gritos.'::text,'animándola'::text,'animarla'::text,'animarla'::text,'Los jóvenes escaladores siguen animándola con fuertes gritos.'::text),
(350312,38924,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les jeunes grimpeurs continuent de l''... avec de grands cris.'::text,'encourager'::text,'encourager'::text,'encourager'::text,'Les jeunes grimpeurs continuent de l''encourager avec de grands cris.'::text),
(350315,38924,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genç tırmanıcılar yüksek sesli tezahüratlarla onu ... devam ediyor.'::text,'cesaretlendirmeye'::text,'cesaretlendirmeye'::text,'cesaretlendirmeye'::text,'Genç tırmanıcılar yüksek sesli tezahüratlarla onu cesaretlendirmeye devam ediyor.'::text),
(350316,38924,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fiatal mászók hangos ujjongással tovább ... őt.'::text,'biztatják'::text,'biztatják'::text,'biztatják'::text,'A fiatal mászók hangos ujjongással tovább biztatják őt.'::text),
(350346,38928,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Gruppe sie nicht angefeuert hätte, ... sie nicht so hoch die Wand hinaufgeklettert.'::text,'wäre'::text,'wird'::text,'ist'::text,'Wenn die Gruppe sie nicht angefeuert hätte, wäre sie nicht so hoch die Wand hinaufgeklettert.'::text),
(350350,38928,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби група її не підбадьорила, вона не ... так високо по стіні.'::text,'вилізла б'::text,'вилізе'::text,'вилізла'::text,'Якби група її не підбадьорила, вона не вилізла б так високо по стіні.'::text),
(350349,38928,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el grupo no la hubiera animado, ella no ... tan alto por la pared.'::text,'habría subido'::text,'subirá'::text,'subió'::text,'Si el grupo no la hubiera animado, ella no habría subido tan alto por la pared.'::text),
(350348,38928,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le groupe ne l''avait pas encouragée, elle ... aussi haut sur le mur.'::text,'ne serait pas montée'::text,'ne montera pas'::text,'n''est pas montée'::text,'Si le groupe ne l''avait pas encouragée, elle ne serait pas montée aussi haut sur le mur.'::text),
(350351,38928,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Grup onu cesaretlendirmeseydi, o duvarda bu kadar yükseğe ...'::text,'tırmanmazdı'::text,'tırmanmayacak'::text,'tırmanmadı'::text,'Grup onu cesaretlendirmeseydi, o duvarda bu kadar yükseğe tırmanmazdı.'::text),
(350352,38928,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a csapat nem biztatta volna, ő nem ... ilyen magasra a falon.'::text,'mászott volna fel'::text,'fog felmászni'::text,'mászott fel'::text,'Ha a csapat nem biztatta volna, ő nem mászott volna fel ilyen magasra a falon.'::text),
(369912,41102,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, er hat mir erzählt, dass er sich diesen V8-Motor von einem Kumpel in einen Motorroller ... lässt.'::text,'einbauen'::text,'einbauen'::text,'einbauen'::text,'Mädel, er hat mir erzählt, dass er sich diesen V8-Motor von einem Kumpel in einen Motorroller einbauen lässt.'::text),
(369916,41102,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дівчино, він сказав мені, що друг ... йому той мотор V8 на скутер.'::text,'поставить'::text,'поставить'::text,'поставить'::text,'Дівчино, він сказав мені, що друг поставить йому той мотор V8 на скутер.'::text),
(369915,41102,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, él me dijo que un amigo le va a ... ese motor V8 en un escúter.'::text,'montar'::text,'montar'::text,'montar'::text,'Tía, él me dijo que un amigo le va a montar ese motor V8 en un escúter.'::text),
(369914,41102,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, il m''a dit qu''il se fait ... ce moteur V8 sur un scooter par un pote.'::text,'monter'::text,'monter'::text,'monter'::text,'Meuf, il m''a dit qu''il se fait monter ce moteur V8 sur un scooter par un pote.'::text),
(369917,41102,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, o bana o V8 motoru bir arkadaşına scooter''a ... söyledi.'::text,'taktırdığını'::text,'taktırdığını'::text,'taktırdığını'::text,'Kızım, o bana o V8 motoru bir arkadaşına scooter''a taktırdığını söyledi.'::text),
(369918,41102,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, ő azt mondta, hogy egy haverjával ... azt a V8-as motort egy robogóra.'::text,'szerelteti fel'::text,'szerelteti fel'::text,'szerelteti fel'::text,'Csajszi, ő azt mondta, hogy egy haverjával szerelteti fel azt a V8-as motort egy robogóra.'::text),
(367050,40784,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Ende des Tages wird der Ingenieur jede Anzeige an diesen alten Maschinen ...'::text,'überprüft haben'::text,'überprüfen'::text,'überprüft'::text,'Bis zum Ende des Tages wird der Ingenieur jede Anzeige an diesen alten Maschinen überprüft haben.'::text),
(367054,40784,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До кінця дня інженер ... кожен манометр на цьому старому обладнанні.'::text,'перевірить'::text,'перевірить'::text,'перевіряє'::text,'До кінця дня інженер перевірить кожен манометр на цьому старому обладнанні.'::text),
(367053,40784,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el final del día, el ingeniero ... todos los indicadores de esta vieja maquinaria.'::text,'habrá revisado'::text,'revisará'::text,'revisa'::text,'Para el final del día, el ingeniero habrá revisado todos los indicadores de esta vieja maquinaria.'::text),
(367052,40784,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici la fin de la journée, l''ingénieur ... chaque jauge de ces vieilles machines.'::text,'aura vérifié'::text,'vérifiera'::text,'vérifie'::text,'D''ici la fin de la journée, l''ingénieur aura vérifié chaque jauge de ces vieilles machines.'::text),
(367055,40784,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gün sonuna kadar mühendis bu eski makinelerdeki her göstergeyi ...'::text,'kontrol etmiş olacak'::text,'kontrol edecek'::text,'kontrol ediyor'::text,'Gün sonuna kadar mühendis bu eski makinelerdeki her göstergeyi kontrol etmiş olacak.'::text),
(367056,40784,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nap végére a mérnök ... minden mérőórát ezen a régi gépezeten.'::text,'leellenőriz'::text,'ellenőrizni fog'::text,'ellenőriz'::text,'A nap végére a mérnök leellenőriz minden mérőórát ezen a régi gépezeten.'::text),
(381675,42409,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als der Roboter sich endlich bewegte, ... er schon etwa zehn Befehle eingetippt. Leicht langsamer Service.'::text,'hatte'::text,'hat'::text,'tippt'::text,'Als der Roboter sich endlich bewegte, hatte er schon etwa zehn Befehle eingetippt. Leicht langsamer Service.'::text),
(381679,42409,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли робот нарешті рушив, він ... вже близько десяти команд. Трохи повільне обслуговування.'::text,'набрав'::text,'набрав'::text,'набирає'::text,'Коли робот нарешті рушив, він набрав вже близько десяти команд. Трохи повільне обслуговування.'::text),
(381678,42409,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando el robot por fin se movió, él ya ... unos diez comandos. Un servicio ligeramente lento.'::text,'había escrito'::text,'ha escrito'::text,'escribe'::text,'Para cuando el robot por fin se movió, él ya había escrito unos diez comandos. Un servicio ligeramente lento.'::text),
(381677,42409,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand le robot a enfin bougé, il ... déjà une dizaine de commandes. Service légèrement lent.'::text,'avait tapé'::text,'a tapé'::text,'tape'::text,'Quand le robot a enfin bougé, il avait tapé déjà une dizaine de commandes. Service légèrement lent.'::text),
(381680,42409,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Robot sonunda hareket ettiğinde o yaklaşık on komut ...! Hafif yavaş bir hizmet.'::text,'yazmıştı'::text,'yazdı'::text,'yazıyor'::text,'Robot sonunda hareket ettiğinde o yaklaşık on komut yazmıştı! Hafif yavaş bir hizmet.'::text),
(381681,42409,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a robot végre megmozdult, ő már ... vagy tíz parancsot. Enyhén lassú kiszolgálás.'::text,'begépelt'::text,'begépelt'::text,'gépel'::text,'Mire a robot végre megmozdult, ő már begépelt vagy tíz parancsot. Enyhén lassú kiszolgálás.'::text),
(381738,42416,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'In diesem Labor ist ... auf der grünen Werkbank ein Gelenkarm mit Greifer.'::text,'der Roboter'::text,'ein Roboter'::text,'Roboter'::text,'In diesem Labor ist der Roboter auf der grünen Werkbank ein Gelenkarm mit Greifer.'::text),
(381742,42416,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У цій лабораторії ... на зеленому верстаті — це шарнірна рука з захватом.'::text,'робот'::text,'робот'::text,'робот'::text,'У цій лабораторії робот на зеленому верстаті — це шарнірна рука з захватом.'::text),
(381741,42416,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En este laboratorio, ... del banco verde es un brazo articulado con pinza.'::text,'el robot'::text,'un robot'::text,'robot'::text,'En este laboratorio, el robot del banco verde es un brazo articulado con pinza.'::text),
(381740,42416,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dans ce labo, ... sur l''établi vert est un bras articulé avec une pince.'::text,'le robot'::text,'un robot'::text,'robot'::text,'Dans ce labo, le robot sur l''établi vert est un bras articulé avec une pince.'::text),
(381743,42416,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu laboratuvarda yeşil tezgâhtaki ..., tutucusu olan eklemli bir kol.'::text,'robot'::text,'bir robot'::text,'robot'::text,'Bu laboratuvarda yeşil tezgâhtaki robot, tutucusu olan eklemli bir kol.'::text),
(381744,42416,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ebben a laborban ... a zöld munkapadon egy csuklós kar markolóval.'::text,'a robot'::text,'egy robot'::text,'robot'::text,'Ebben a laborban a robot a zöld munkapadon egy csuklós kar markolóval.'::text),
(350787,38977,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, diese Ziege ... schon die ganze Woche abzuhauen, kein Witz.'::text,'versucht'::text,'versucht'::text,'versucht'::text,'Bro, diese Ziege versucht schon die ganze Woche abzuhauen, kein Witz.'::text),
(350791,38977,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, ця коза ... втекти весь тиждень, без брехні.'::text,'намагається'::text,'намагається'::text,'намагається'::text,'Бро, ця коза намагається втекти весь тиждень, без брехні.'::text),
(350790,38977,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, esta cabra ... escaparse toda la semana, sin mentir.'::text,'lleva intentando'::text,'está intentando'::text,'intenta'::text,'Bro, esta cabra lleva intentando escaparse toda la semana, sin mentir.'::text),
(350789,38977,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, cette chèvre ... de s''échapper toute la semaine, sans mentir.'::text,'essaie'::text,'essaie'::text,'essaie'::text,'Frère, cette chèvre essaie de s''échapper toute la semaine, sans mentir.'::text),
(350792,38977,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bu keçi bütün hafta kaçmaya ..., yalan yok.'::text,'çalışıyor'::text,'çalışıyor'::text,'çalışır'::text,'Kanka, bu keçi bütün hafta kaçmaya çalışıyor, yalan yok.'::text),
(350793,38977,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ez a kecske egész héten ... megszökni, nem kamu.'::text,'próbál'::text,'próbál'::text,'próbál'::text,'Tesó, ez a kecske egész héten próbál megszökni, nem kamu.'::text),
(350841,38983,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Bauer wünscht sich, dass die Ziege nicht durch das Tor ...'::text,'abgehauen wäre'::text,'abhaute'::text,'abhauen würde'::text,'Der Bauer wünscht sich, dass die Ziege nicht durch das Tor abgehauen wäre.'::text),
(350845,38983,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Фермер хотів би, щоб коза не ... через ворота.'::text,'втекла'::text,'втікала'::text,'втекла б'::text,'Фермер хотів би, щоб коза не втекла через ворота.'::text),
(350844,38983,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El granjero desearía que la cabra no ... por la puerta.'::text,'se hubiera escapado'::text,'se escapara'::text,'se escaparía'::text,'El granjero desearía que la cabra no se hubiera escapado por la puerta.'::text),
(350843,38983,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le fermier aimerait que la chèvre ne ... pas par le portail.'::text,'se soit échappée'::text,'s''échappe'::text,'s''échapperait'::text,'Le fermier aimerait que la chèvre ne se soit échappée pas par le portail.'::text),
(350846,38983,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çiftçi, keçinin kapıdan ... diliyor.'::text,'kaçmamış olmasını'::text,'kaçmamasını'::text,'kaçmayacağını'::text,'Çiftçi, keçinin kapıdan kaçmamış olmasını diliyor.'::text),
(350847,38983,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A farmer azt szeretné, ha a kecske nem ... a kapun át.'::text,'szökött volna ki'::text,'szökne ki'::text,'szökne ki'::text,'A farmer azt szeretné, ha a kecske nem szökött volna ki a kapun át.'::text),
(378516,42058,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er die Flagge noch höher zieht, ... sie die Spitze des Mastes.'::text,'erreicht'::text,'erreichte'::text,'erreichte'::text,'Wenn er die Flagge noch höher zieht, erreicht sie die Spitze des Mastes.'::text),
(378520,42058,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо він підніме прапор ще вище, той ... верхівки щогли.'::text,'досягне'::text,'досягнув би'::text,'досягнув'::text,'Якщо він підніме прапор ще вище, той досягне верхівки щогли.'::text),
(378519,42058,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si él sube la bandera más alto, esta ... la punta del mástil.'::text,'alcanzará'::text,'alcanzaría'::text,'alcanzó'::text,'Si él sube la bandera más alto, esta alcanzará la punta del mástil.'::text),
(378518,42058,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il monte le drapeau encore plus haut, il ... le haut du mât.'::text,'atteindra'::text,'atteindrait'::text,'atteignait'::text,'S''il monte le drapeau encore plus haut, il atteindra le haut du mât.'::text),
(378521,42058,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O bayrağı biraz daha yükseltirse, bayrak direğin tepesine ...'::text,'ulaşacak'::text,'ulaşırdı'::text,'ulaştı'::text,'O bayrağı biraz daha yükseltirse, bayrak direğin tepesine ulaşacak.'::text),
(378522,42058,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha még feljebb húzza a zászlót, az ... a rúd tetejét.'::text,'eléri'::text,'elérné'::text,'elérte'::text,'Ha még feljebb húzza a zászlót, az eléri a rúd tetejét.'::text),
(378552,42062,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Trommler ... schon zehn Minuten gespielt, als er endlich die Flagge hisste, eine sehr ruhige Zeremonie.'::text,'hatten'::text,'spielten'::text,'haben'::text,'Die Trommler hatten schon zehn Minuten gespielt, als er endlich die Flagge hisste, eine sehr ruhige Zeremonie.'::text),
(378556,42062,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Барабанщики вже десять хвилин ..., коли він нарешті підняв прапор, дуже тиха церемонія.'::text,'грали'::text,'грали'::text,'грають'::text,'Барабанщики вже десять хвилин грали, коли він нарешті підняв прапор, дуже тиха церемонія.'::text),
(378555,42062,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los tamborileros ... diez minutos tocando cuando por fin izó la bandera, una ceremonia muy tranquila.'::text,'llevaban'::text,'estaban'::text,'llevan'::text,'Los tamborileros llevaban diez minutos tocando cuando por fin izó la bandera, una ceremonia muy tranquila.'::text),
(378554,42062,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les batteurs ... depuis dix minutes quand il a enfin hissé le drapeau, une cérémonie très calme.'::text,'jouaient'::text,'jouaient'::text,'jouent'::text,'Les batteurs jouaient depuis dix minutes quand il a enfin hissé le drapeau, une cérémonie très calme.'::text),
(378557,42062,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O sonunda bayrağı çektiğinde davulcular on dakikadır ..., çok sessiz bir tören.'::text,'çalıyordu'::text,'çalıyordu'::text,'çalıyor'::text,'O sonunda bayrağı çektiğinde davulcular on dakikadır çalıyordu, çok sessiz bir tören.'::text),
(378558,42062,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A dobosok már tíz perce ..., amikor ő végre felhúzta a zászlót, nagyon csendes ceremónia.'::text,'játszottak'::text,'játszottak'::text,'játszanak'::text,'A dobosok már tíz perce játszottak, amikor ő végre felhúzta a zászlót, nagyon csendes ceremónia.'::text),
(333570,37064,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Band weigert sich absolut, ihren Song zu ..., obwohl der ganze Platz schreit!'::text,'beenden'::text,'beenden'::text,'beenden'::text,'Die Band weigert sich absolut, ihren Song zu beenden, obwohl der ganze Platz schreit!'::text),
(333574,37064,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гурт категорично відмовляється ... свою пісню, навіть коли вся площа кричить!'::text,'закінчувати'::text,'закінчення'::text,'закінчувати'::text,'Гурт категорично відмовляється закінчувати свою пісню, навіть коли вся площа кричить!'::text),
(333573,37064,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡La banda se niega rotundamente a ... su canción, aunque toda la plaza está gritando!'::text,'terminar'::text,'terminando'::text,'terminar'::text,'¡La banda se niega rotundamente a terminar su canción, aunque toda la plaza está gritando!'::text),
(333572,37064,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le groupe refuse catégoriquement de ... sa chanson, même avec toute la place qui hurle !'::text,'finir'::text,'finir'::text,'finir'::text,'Le groupe refuse catégoriquement de finir sa chanson, même avec toute la place qui hurle !'::text),
(333575,37064,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Grup, bütün meydan çığlık atsa bile şarkısını ... kesinlikle reddediyor!'::text,'bitirmeyi'::text,'bitirmeyi'::text,'bitirmeyi'::text,'Grup, bütün meydan çığlık atsa bile şarkısını bitirmeyi kesinlikle reddediyor!'::text),
(333576,37064,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A banda határozottan nem hajlandó ... a dalát, még akkor sem, ha az egész tér sikít!'::text,'befejezni'::text,'befejezni'::text,'befejezni'::text,'A banda határozottan nem hajlandó befejezni a dalát, még akkor sem, ha az egész tér sikít!'::text),
(333579,37065,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der ganze Platz schreit nach ..., die diese Band spielt!'::text,'der Musik'::text,'einer Musik'::text,'Musik'::text,'Der ganze Platz schreit nach der Musik, die diese Band spielt!'::text),
(333583,37065,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уся площа кричить, вимагаючи ..., яку грає цей гурт!'::text,'музики'::text,'музики'::text,'музики'::text,'Уся площа кричить, вимагаючи музики, яку грає цей гурт!'::text),
(333582,37065,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Toda la plaza grita por ... que toca esta banda!'::text,'la música'::text,'una música'::text,'música'::text,'¡Toda la plaza grita por la música que toca esta banda!'::text),
(333581,37065,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Toute la place hurle pour ... que joue ce groupe !'::text,'la musique'::text,'une musique'::text,'musique'::text,'Toute la place hurle pour la musique que joue ce groupe !'::text),
(333584,37065,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bütün meydan bu grubun çaldığı ... için çığlık atıyor!'::text,'müzik'::text,'bir müzik'::text,'müzik'::text,'Bütün meydan bu grubun çaldığı müzik için çığlık atıyor!'::text),
(333585,37065,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az egész tér ... után sikít, amit ez a banda játszik!'::text,'a zene'::text,'egy zene'::text,'zene'::text,'Az egész tér a zene után sikít, amit ez a banda játszik!'::text),
(386481,42943,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Beim Anpfiff morgen ... das ganze Stadion wieder. Ein ruhiger Abend, offensichtlich.'::text,'brüllt'::text,'brüllt'::text,'brüllt'::text,'Beim Anpfiff morgen brüllt das ganze Stadion wieder. Ein ruhiger Abend, offensichtlich.'::text),
(386485,42943,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра на початку матчу весь стадіон ... знову. Тихий вечір, очевидно.'::text,'кричатиме'::text,'закричить'::text,'кричить'::text,'Завтра на початку матчу весь стадіон кричатиме знову. Тихий вечір, очевидно.'::text),
(386484,42943,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana en el saque inicial, todo el estadio ... otra vez. Una noche tranquila, obviamente.'::text,'estará gritando'::text,'gritará'::text,'grita'::text,'Mañana en el saque inicial, todo el estadio estará gritando otra vez. Una noche tranquila, obviamente.'::text),
(386483,42943,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain au coup d''envoi, tout le stade ... encore. Une soirée calme, évidemment.'::text,'sera en train de hurler'::text,'hurlera'::text,'hurle'::text,'Demain au coup d''envoi, tout le stade sera en train de hurler encore. Une soirée calme, évidemment.'::text),
(386486,42943,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın başlama vuruşunda bütün stadyum ... yine. Sakin bir akşam, belli ki.'::text,'bağırıyor olacak'::text,'bağıracak'::text,'bağırıyor'::text,'Yarın başlama vuruşunda bütün stadyum bağırıyor olacak yine. Sakin bir akşam, belli ki.'::text),
(386487,42943,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap a kezdőrúgásnál az egész stadion ... megint. Csendes este, nyilván.'::text,'kiabálni fog'::text,'felkiált'::text,'kiabál'::text,'Holnap a kezdőrúgásnál az egész stadion kiabálni fog megint. Csendes este, nyilván.'::text),
(386571,42953,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Stell dir vor, sie hat mir erzählt, dass die Fans schon eine Stunde ..., bevor das Team überhaupt rauskam.'::text,'geschrien hatten'::text,'schrien'::text,'geschrien haben'::text,'Stell dir vor, sie hat mir erzählt, dass die Fans schon eine Stunde geschrien hatten, bevor das Team überhaupt rauskam.'::text),
