(359089,39899,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Опівдні чоловік із веслом уже три години ... туристів угору цією стежкою.'::text,'водитиме'::text,'водитиме'::text,'водитиме'::text,'Опівдні чоловік із веслом уже три години водитиме туристів угору цією стежкою.'::text),
