(359090,39899,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öğlene kadar kürekli adam üç saattir turistlere bu yolda ...'::text,'rehberlik ediyor olacak'::text,'rehberlik ediyor olacak'::text,'rehberlik edecek'::text,'Öğlene kadar kürekli adam üç saattir turistlere bu yolda rehberlik ediyor olacak.'::text),
