(363146,40350,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, j''ai entendu qu''elle ... déjà deux pichets d''eau, et la fête n''a même pas commencé.'::text,'a versé'::text,'verse'::text,'a versé'::text,'Meuf, j''ai entendu qu''elle a versé déjà deux pichets d''eau, et la fête n''a même pas commencé.'::text),
(363149,40350,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, ben duydum ki o şimdiden iki sürahi su ..., ve parti daha başlamadı bile.'::text,'dökmüş'::text,'döküyormuş'::text,'döktü'::text,'Kızım, ben duydum ki o şimdiden iki sürahi su dökmüş, ve parti daha başlamadı bile.'::text),
(363150,40350,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, én azt hallottam, hogy ő már két kancsó vizet ..., és a buli még el sem kezdődött.'::text,'kiöntött'::text,'öntöget'::text,'kiöntött'::text,'Csajszi, én azt hallottam, hogy ő már két kancsó vizet kiöntött, és a buli még el sem kezdődött.'::text),
(363189,40355,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie goss Wasser aus ... mit dem gebogenen Henkel in die Gießkanne.'::text,'dem Krug'::text,'einem Krug'::text,'Krug'::text,'Sie goss Wasser aus dem Krug mit dem gebogenen Henkel in die Gießkanne.'::text),
(363193,40355,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона налила воду з ... з вигнутою ручкою в лійку.'::text,'глека'::text,'глека'::text,'глека'::text,'Вона налила воду з глека з вигнутою ручкою в лійку.'::text),
(363192,40355,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella echó agua de ... con el asa curva en la regadera.'::text,'la jarra'::text,'una jarra'::text,'jarra'::text,'Ella echó agua de la jarra con el asa curva en la regadera.'::text),
(363191,40355,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a versé de l''eau ... à l''anse courbée dans l''arrosoir.'::text,'du pichet'::text,'d''un pichet'::text,'de pichet'::text,'Elle a versé de l''eau du pichet à l''anse courbée dans l''arrosoir.'::text),
(363194,40355,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, kavisli saplı ... suyu sulama kabına döktü.'::text,'sürahideki'::text,'bir sürahideki'::text,'sürahideki'::text,'O, kavisli saplı sürahideki suyu sulama kabına döktü.'::text),
(363195,40355,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő vizet öntött ..., amelynek ívelt füle van, a locsolókannába.'::text,'a kancsóból'::text,'egy kancsóból'::text,'kancsóból'::text,'Ő vizet öntött a kancsóból, amelynek ívelt füle van, a locsolókannába.'::text),
(403833,44871,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Erst wenn die Wunde sauber ist, ... er ein Pflaster darauf.'::text,'klebt'::text,'klebt'::text,'würde'::text,'Erst wenn die Wunde sauber ist, klebt er ein Pflaster darauf.'::text),
(403837,44871,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Лише коли рана буде чистою, він ... на неї пластир.'::text,'наклеїть'::text,'наклеїть'::text,'наклеїв би'::text,'Лише коли рана буде чистою, він наклеїть на неї пластир.'::text),
(403836,44871,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Solo cuando la herida esté limpia, él le ... una tirita.'::text,'pondrá'::text,'pondrá'::text,'pondría'::text,'Solo cuando la herida esté limpia, él le pondrá una tirita.'::text),
(403835,44871,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce n''est que lorsque la plaie sera propre qu''il ... un pansement dessus.'::text,'mettra'::text,'mettra'::text,'mettrait'::text,'Ce n''est que lorsque la plaie sera propre qu''il mettra un pansement dessus.'::text),
(403838,44871,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yara temizlenmeden o üzerine yara bandı ...'::text,'yapıştırmayacak'::text,'yapıştırmayacak'::text,'yapıştırmazdı'::text,'Yara temizlenmeden o üzerine yara bandı yapıştırmayacak.'::text),
(403839,44871,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő csak akkor ... rá sebtapaszt, ha a seb már tiszta.'::text,'tesz'::text,'tesz'::text,'tenne'::text,'Ő csak akkor tesz rá sebtapaszt, ha a seb már tiszta.'::text),
(354594,39400,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... sich gerade, als das Flugzeug zu Beginn des Fluges abhob.'::text,'filmte'::text,'filmte'::text,'hat gefilmt'::text,'Er filmte sich gerade, als das Flugzeug zu Beginn des Fluges abhob.'::text),
(354598,39400,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... себе, коли літак злетів на початку польоту.'::text,'знімав'::text,'зняв'::text,'зняв'::text,'Він знімав себе, коли літак злетів на початку польоту.'::text),
(354597,39400,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él se ... cuando el avión despegó al comienzo del vuelo.'::text,'estaba grabando'::text,'grabó'::text,'ha grabado'::text,'Él se estaba grabando cuando el avión despegó al comienzo del vuelo.'::text),
(354596,39400,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... quand l''avion a décollé au début du vol.'::text,'se filmait'::text,'s''est filmé'::text,'s''est filmé'::text,'Il se filmait quand l''avion a décollé au début du vol.'::text),
(354599,39400,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Uçuşun başında uçak havalandığında o kendini ...'::text,'çekiyordu'::text,'çekti'::text,'çekti'::text,'Uçuşun başında uçak havalandığında o kendini çekiyordu.'::text),
(354600,39400,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő épp ... magát, amikor a repülő a repülőút elején felszállt.'::text,'videózta'::text,'levideózta'::text,'levideózta'::text,'Ő épp videózta magát, amikor a repülő a repülőút elején felszállt.'::text),
(354684,39410,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Sonne ... gerade über den Wolken unter, als die Crew ihm während des Fluges Saft brachte.'::text,'ging'::text,'ging'::text,'war'::text,'Die Sonne ging gerade über den Wolken unter, als die Crew ihm während des Fluges Saft brachte.'::text),
(354688,39410,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сонце ... над хмарами, коли екіпаж приніс йому сік під час польоту.'::text,'сідало'::text,'сіло'::text,'сіло'::text,'Сонце сідало над хмарами, коли екіпаж приніс йому сік під час польоту.'::text),
(354687,39410,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El sol se ... sobre las nubes cuando la tripulación le trajo zumo durante el vuelo.'::text,'estaba poniendo'::text,'puso'::text,'había puesto'::text,'El sol se estaba poniendo sobre las nubes cuando la tripulación le trajo zumo durante el vuelo.'::text),
(354686,39410,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le soleil ... au-dessus des nuages quand l''équipage lui a apporté du jus pendant le vol.'::text,'se couchait'::text,'s''est couché'::text,'s''était couché'::text,'Le soleil se couchait au-dessus des nuages quand l''équipage lui a apporté du jus pendant le vol.'::text),
(354689,39410,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Uçuş sırasında mürettebat ona meyve suyu getirdiğinde güneş bulutların üzerinde ...'::text,'batıyordu'::text,'battı'::text,'batmıştı'::text,'Uçuş sırasında mürettebat ona meyve suyu getirdiğinde güneş bulutların üzerinde batıyordu.'::text),
(354690,39410,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nap épp ... a felhők felett, amikor a személyzet gyümölcslevet hozott neki a repülés alatt.'::text,'ment le'::text,'lement'::text,'már lement'::text,'A nap épp ment le a felhők felett, amikor a személyzet gyümölcslevet hozott neki a repülés alatt.'::text),
(355107,39457,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn das Wasser weiter so fließt, ... das Wasserfahrzeug die Brücke in etwa einer Minute.'::text,'erreicht'::text,'erreichte'::text,'erreichte'::text,'Wenn das Wasser weiter so fließt, erreicht das Wasserfahrzeug die Brücke in etwa einer Minute.'::text),
(355111,39457,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо вода й далі так тектиме, судно ... мосту приблизно за хвилину.'::text,'досягне'::text,'досягло б'::text,'досягло'::text,'Якщо вода й далі так тектиме, судно досягне мосту приблизно за хвилину.'::text),
(355110,39457,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el agua sigue fluyendo así, la embarcación ... el puente en aproximadamente un minuto.'::text,'alcanzará'::text,'alcanzaría'::text,'alcanzó'::text,'Si el agua sigue fluyendo así, la embarcación alcanzará el puente en aproximadamente un minuto.'::text),
(355109,39457,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si l''eau continue de couler ainsi, l''embarcation ... le pont dans environ une minute.'::text,'atteindra'::text,'atteindrait'::text,'a atteint'::text,'Si l''eau continue de couler ainsi, l''embarcation atteindra le pont dans environ une minute.'::text),
(355112,39457,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su böyle akmaya devam ederse, tekne yaklaşık bir dakika içinde köprüye ...'::text,'ulaşacak'::text,'ulaşırdı'::text,'ulaştı'::text,'Su böyle akmaya devam ederse, tekne yaklaşık bir dakika içinde köprüye ulaşacak.'::text),
(355113,39457,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a víz így folyik tovább, a vízi jármű nagyjából egy perc múlva ... a hídhoz.'::text,'ér'::text,'érne'::text,'ért'::text,'Ha a víz így folyik tovább, a vízi jármű nagyjából egy perc múlva ér a hídhoz.'::text),
(356061,39563,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein Fallschirmspringer hielt in der Formation Händchen, und ...'::text,'der nächste auch.'::text,'der nächste auch.'::text,'der nächste auch nicht.'::text,'Ein Fallschirmspringer hielt in der Formation Händchen, und der nächste auch.'::text),
(356065,39563,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Один парашутист тримався за руки у формації, і ...'::text,'наступний теж.'::text,'наступний теж.'::text,'наступний теж ні.'::text,'Один парашутист тримався за руки у формації, і наступний теж.'::text),
(356064,39563,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un paracaidista se dio la mano en la formación, y ...'::text,'el siguiente también.'::text,'el siguiente también.'::text,'el siguiente tampoco.'::text,'Un paracaidista se dio la mano en la formación, y el siguiente también.'::text),
(356063,39563,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un parachutiste tenait la main dans la formation, et ...'::text,'le suivant aussi.'::text,'le suivant aussi.'::text,'le suivant non plus.'::text,'Un parachutiste tenait la main dans la formation, et le suivant aussi.'::text),
(356066,39563,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir paraşütçü formasyonda el ele tuttu, ve ...'::text,'bir sonraki de.'::text,'bir sonraki de.'::text,'bir sonraki de tutmadı.'::text,'Bir paraşütçü formasyonda el ele tuttu, ve bir sonraki de.'::text),
(356067,39563,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az egyik ejtőernyős fogta a kezét a formációban, és ...'::text,'a következő is.'::text,'a következő is.'::text,'a következő sem.'::text,'Az egyik ejtőernyős fogta a kezét a formációban, és a következő is.'::text),
(356097,39567,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, wenn ich mit ihnen trainiert hätte, ... ich jetzt gerade in dieser Formation, kein Witz.'::text,'fiele'::text,'wäre gefallen'::text,'werde fallen'::text,'Alter, wenn ich mit ihnen trainiert hätte, fiele ich jetzt gerade in dieser Formation, kein Witz.'::text),
(356101,39567,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, якби я тренувався з ними, я ... зараз у тій формації, без брехні.'::text,'падав би'::text,'упав би'::text,'падатиму'::text,'Чувак, якби я тренувався з ними, я падав би зараз у тій формації, без брехні.'::text),
(356100,39567,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, si hubiera entrenado con ellos, yo ... en esa formación ahora mismo, sin mentir.'::text,'estaría cayendo'::text,'habría caído'::text,'caeré'::text,'Tío, si hubiera entrenado con ellos, yo estaría cayendo en esa formación ahora mismo, sin mentir.'::text),
(356099,39567,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, si je m''étais entraîné avec eux, je ... dans cette formation en ce moment, sans mentir.'::text,'serais en train de tomber'::text,'serais tombé'::text,'tomberai'::text,'Mec, si je m''étais entraîné avec eux, je serais en train de tomber dans cette formation en ce moment, sans mentir.'::text),
(356102,39567,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, onlarla antrenman yapsaydım, ben şu an o formasyonda ..., yalan yok.'::text,'düşüyor olurdum'::text,'düşmüş olurdum'::text,'düşeceğim'::text,'Kanka, onlarla antrenman yapsaydım, ben şu an o formasyonda düşüyor olurdum, yalan yok.'::text),
(356103,39567,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Haver, ha velük edzettem volna, én most abban a formációban ..., nem kamu.'::text,'zuhannék'::text,'zuhantam volna'::text,'zuhanni fogok'::text,'Haver, ha velük edzettem volna, én most abban a formációban zuhannék, nem kamu.'::text),
(351840,39094,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du wünschst dir bestimmt, du ... den Ofen früher geöffnet, aber ein Fehlschlag definiert dich nicht.'::text,'hättest'::text,'hast'::text,'würdest'::text,'Ehrlich, du wünschst dir bestimmt, du hättest den Ofen früher geöffnet, aber ein Fehlschlag definiert dich nicht.'::text),
(351844,39094,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти, мабуть, шкодуєш, що не ... духовку раніше, але одна невдача тебе не визначає.'::text,'відкрив'::text,'відкрив'::text,'відкрив би'::text,'Чесно, ти, мабуть, шкодуєш, що не відкрив духовку раніше, але одна невдача тебе не визначає.'::text),
(351843,39094,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, tú debes de desear ... el horno antes, pero un fracaso no te define.'::text,'haber abierto'::text,'abrir'::text,'abrirías'::text,'Sinceramente, tú debes de desear haber abierto el horno antes, pero un fracaso no te define.'::text),
(351842,39094,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu voudrais sûrement ... le four plus tôt, mais un échec ne te définit pas.'::text,'avoir ouvert'::text,'ouvrir'::text,'ouvrirais'::text,'Franchement, tu voudrais sûrement avoir ouvert le four plus tôt, mais un échec ne te définit pas.'::text),
(351845,39094,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası sen fırını daha önce ... dilemişsindir, ama tek bir başarısızlık seni tanımlamaz.'::text,'açmış olmayı'::text,'açmayı'::text,'açacağını'::text,'Açıkçası sen fırını daha önce açmış olmayı dilemişsindir, ama tek bir başarısızlık seni tanımlamaz.'::text),
(351846,39094,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, te biztos azt kívánod, bárcsak korábban ... a sütőt, de egy kudarc nem határoz meg téged.'::text,'kinyitottad volna'::text,'kinyitottad'::text,'kinyitnád'::text,'Őszintén, te biztos azt kívánod, bárcsak korábban kinyitottad volna a sütőt, de egy kudarc nem határoz meg téged.'::text),
(355881,39543,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... mit verschränkten Armen da, als sein Freund um Verzeihung bat.'::text,'stand'::text,'stand'::text,'hat gestanden'::text,'Er stand mit verschränkten Armen da, als sein Freund um Verzeihung bat.'::text),
(355885,39543,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... зі схрещеними руками, коли друг попросив пробачення.'::text,'стояв'::text,'стояв'::text,'стояв'::text,'Він стояв зі схрещеними руками, коли друг попросив пробачення.'::text),
(355884,39543,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... de brazos cruzados cuando su amigo le pidió perdón.'::text,'estaba'::text,'estuvo'::text,'ha estado'::text,'Él estaba de brazos cruzados cuando su amigo le pidió perdón.'::text),
(355883,39543,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... les bras croisés quand son ami lui a demandé pardon.'::text,'se tenait'::text,'s''est tenu'::text,'s''est tenu'::text,'Il se tenait les bras croisés quand son ami lui a demandé pardon.'::text),
(355886,39543,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arkadaşı özür dilediğinde o kollarını kavuşturmuş ...'::text,'duruyordu'::text,'durdu'::text,'durdu'::text,'Arkadaşı özür dilediğinde o kollarını kavuşturmuş duruyordu.'::text),
(355887,39543,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő karba tett kézzel ..., amikor a barátja bocsánatot kért.'::text,'állt'::text,'állt'::text,'állt'::text,'Ő karba tett kézzel állt, amikor a barátja bocsánatot kért.'::text),
(355917,39547,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er wünscht sich, dass sein Freund ihm früher ..., statt den ganzen Nachmittag zu ruinieren!'::text,'verziehen hätte'::text,'verzieh'::text,'verzeihen würde'::text,'Er wünscht sich, dass sein Freund ihm früher verziehen hätte, statt den ganzen Nachmittag zu ruinieren!'::text),
(355921,39547,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він хотів би, щоб друг ... йому раніше, а не зіпсував усе пообіддя!'::text,'пробачив'::text,'пробачав'::text,'пробачив би'::text,'Він хотів би, щоб друг пробачив йому раніше, а не зіпсував усе пообіддя!'::text),
(355920,39547,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Él desearía que su amigo lo ... antes en lugar de arruinar toda la tarde!'::text,'hubiera perdonado'::text,'perdonara'::text,'perdonaría'::text,'¡Él desearía que su amigo lo hubiera perdonado antes en lugar de arruinar toda la tarde!'::text),
(355919,39547,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il aimerait que son ami lui ... plus tôt au lieu de gâcher tout l''après-midi !'::text,'ait pardonné'::text,'pardonne'::text,'pardonnerait'::text,'Il aimerait que son ami lui ait pardonné plus tôt au lieu de gâcher tout l''après-midi !'::text),
(355922,39547,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, arkadaşının bütün öğleden sonrayı mahvetmek yerine onu daha önce ... diliyor!'::text,'affetmiş olmasını'::text,'affetmesini'::text,'affedeceğini'::text,'O, arkadaşının bütün öğleden sonrayı mahvetmek yerine onu daha önce affetmiş olmasını diliyor!'::text),
(355923,39547,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő azt kívánja, bárcsak a barátja korábban ... neki, ahelyett hogy tönkretette az egész délutánt!'::text,'megbocsátott volna'::text,'megbocsátott'::text,'megbocsátana'::text,'Ő azt kívánja, bárcsak a barátja korábban megbocsátott volna neki, ahelyett hogy tönkretette az egész délutánt!'::text),
(377184,41910,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als die Schiedsrichterin die Karte hob, ... er schon zweimal seine Unschuld beteuert! Totale Katastrophe!'::text,'hatte'::text,'hat'::text,'beteuert'::text,'Als die Schiedsrichterin die Karte hob, hatte er schon zweimal seine Unschuld beteuert! Totale Katastrophe!'::text),
(377188,41910,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки суддя підняла картку, він уже двічі ... свою невинність! Повна катастрофа!'::text,'доводив'::text,'доводив'::text,'доводить'::text,'Поки суддя підняла картку, він уже двічі доводив свою невинність! Повна катастрофа!'::text),
(377187,41910,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Para cuando la árbitra sacó la tarjeta, él ya ... su inocencia dos veces! ¡Desastre total!'::text,'había defendido'::text,'ha defendido'::text,'defiende'::text,'¡Para cuando la árbitra sacó la tarjeta, él ya había defendido su inocencia dos veces! ¡Desastre total!'::text),
(377186,41910,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Au moment où l''arbitre a levé le carton, il ... son innocence deux fois ! Désastre total !'::text,'avait déjà clamé'::text,'a déjà clamé'::text,'clame'::text,'Au moment où l''arbitre a levé le carton, il avait déjà clamé son innocence deux fois ! Désastre total !'::text),
(377189,41910,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hakem kartı kaldırdığında o masumiyetini iki kez ...! Tam bir felaket!'::text,'savunmuştu'::text,'savundu'::text,'savunuyor'::text,'Hakem kartı kaldırdığında o masumiyetini iki kez savunmuştu! Tam bir felaket!'::text),
(377190,41910,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a bírónő felemelte a lapot, ő már kétszer ... az ártatlanságát! Teljes katasztrófa!'::text,'bizonygatta'::text,'bizonygatta'::text,'bizonygatja'::text,'Mire a bírónő felemelte a lapot, ő már kétszer bizonygatta az ártatlanságát! Teljes katasztrófa!'::text),
(356277,39587,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn ein Knochen einen Bruch hat, ... selbst eine winzige Bewegung schreckliche Schmerzen!'::text,'verursacht'::text,'verursachte'::text,'verursacht'::text,'Wenn ein Knochen einen Bruch hat, verursacht selbst eine winzige Bewegung schreckliche Schmerzen!'::text),
(356281,39587,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо кістка має перелом, навіть найменший рух ... жахливий біль!'::text,'спричиняє'::text,'спричинив'::text,'спричинить'::text,'Якщо кістка має перелом, навіть найменший рух спричиняє жахливий біль!'::text),
(356280,39587,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si un hueso tiene una fractura, hasta un movimiento mínimo ... un dolor terrible!'::text,'causa'::text,'causó'::text,'causará'::text,'¡Si un hueso tiene una fractura, hasta un movimiento mínimo causa un dolor terrible!'::text),
(356279,39587,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si un os est fracturé, même un tout petit mouvement ... une douleur terrible !'::text,'provoque'::text,'a provoqué'::text,'provoquera'::text,'Si un os est fracturé, même un tout petit mouvement provoque une douleur terrible !'::text),
(356282,39587,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir kemikte kırık varsa, en ufak bir hareket bile korkunç bir acıya ...!'::text,'neden olur'::text,'neden oldu'::text,'neden olacak'::text,'Bir kemikte kırık varsa, en ufak bir hareket bile korkunç bir acıya neden olur!'::text),
(356283,39587,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha egy csontban törés van, már egy apró mozdulat is szörnyű fájdalmat ...!'::text,'okoz'::text,'okozott'::text,'okozni fog'::text,'Ha egy csontban törés van, már egy apró mozdulat is szörnyű fájdalmat okoz!'::text),
(356322,39592,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Sommer ... du diesen Bruch hinter dir, und ehrlich, Respekt.'::text,'hast'::text,'hast'::text,'hast'::text,'Bis zum Sommer hast du diesen Bruch hinter dir, und ehrlich, Respekt.'::text),
(356326,39592,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До літа ти ... цей перелом позаду, і чесно, респект.'::text,'залишиш'::text,'залишиш'::text,'залишаєш'::text,'До літа ти залишиш цей перелом позаду, і чесно, респект.'::text),
(356325,39592,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el verano, tú ... esta fractura atrás, y sinceramente, respeto.'::text,'habrás dejado'::text,'dejarás'::text,'dejas'::text,'Para el verano, tú habrás dejado esta fractura atrás, y sinceramente, respeto.'::text),
(356324,39592,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici l''été, tu ... cette fracture derrière toi, et franchement, respect.'::text,'auras laissé'::text,'laisseras'::text,'laisses'::text,'D''ici l''été, tu auras laissé cette fracture derrière toi, et franchement, respect.'::text),
(356327,39592,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yaza kadar sen bu kırığı geride ..., ve açıkçası, saygı duyuyorum.'::text,'bırakmış olacaksın'::text,'bırakacaksın'::text,'bırakıyorsun'::text,'Yaza kadar sen bu kırığı geride bırakmış olacaksın, ve açıkçası, saygı duyuyorum.'::text),
(356328,39592,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyárra te már magad mögött ... ezt a törést, és őszintén, tisztelet.'::text,'hagyod'::text,'hagyod'::text,'hagyod'::text,'Nyárra te már magad mögött hagyod ezt a törést, és őszintén, tisztelet.'::text),
(333057,37007,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, dieser Bäcker hat heute schon 200 Croissants ..., und es ist noch nicht mal Mittag.'::text,'gebacken'::text,'gebacken'::text,'gebacken'::text,'Bro, dieser Bäcker hat heute schon 200 Croissants gebacken, und es ist noch nicht mal Mittag.'::text),
(333061,37007,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, цей пекар сьогодні вже ... 200 круасанів, а ще навіть не обід.'::text,'спік'::text,'пече'::text,'спік'::text,'Бро, цей пекар сьогодні вже спік 200 круасанів, а ще навіть не обід.'::text),
(333060,37007,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, este panadero ... 200 cruasanes hoy y ni siquiera es mediodía.'::text,'ha horneado'::text,'ha estado horneando'::text,'horneó'::text,'Bro, este panadero ha horneado 200 cruasanes hoy y ni siquiera es mediodía.'::text),
(333059,37007,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, ce boulanger ... 200 croissants aujourd''hui et il est même pas midi.'::text,'a fait cuire'::text,'fait cuire'::text,'a fait cuire'::text,'Frère, ce boulanger a fait cuire 200 croissants aujourd''hui et il est même pas midi.'::text),
(333062,37007,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bu fırıncı bugün 200 kruvasan ... ve daha öğlen bile olmadı.'::text,'pişirdi'::text,'pişiriyor'::text,'pişirdi'::text,'Kanka, bu fırıncı bugün 200 kruvasan pişirdi ve daha öğlen bile olmadı.'::text),
(333063,37007,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ez a pék ma már 200 croissant-t ..., és még dél sincs.'::text,'sütött'::text,'süt'::text,'sütött'::text,'Tesó, ez a pék ma már 200 croissant-t sütött, és még dél sincs.'::text),
(333102,37012,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerade ... der Bäcker in ein Baguette wie in ein Telefon. Ein echter Profi.'::text,'spricht'::text,'spricht'::text,'hat gesprochen'::text,'Gerade spricht der Bäcker in ein Baguette wie in ein Telefon. Ein echter Profi.'::text),
(333106,37012,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Прямо зараз пекар ... в багет, як у телефон. Справжній професіонал.'::text,'говорить'::text,'говорить'::text,'говорив'::text,'Прямо зараз пекар говорить в багет, як у телефон. Справжній професіонал.'::text),
(333105,37012,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahora mismo el panadero ... a una baguette como si fuera un teléfono. Un auténtico profesional.'::text,'está hablando'::text,'habla'::text,'ha hablado'::text,'Ahora mismo el panadero está hablando a una baguette como si fuera un teléfono. Un auténtico profesional.'::text),
(333104,37012,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, le boulanger ... dans une baguette comme dans un téléphone. Un vrai pro.'::text,'parle'::text,'parle'::text,'a parlé'::text,'En ce moment, le boulanger parle dans une baguette comme dans un téléphone. Un vrai pro.'::text),
(333107,37012,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda fırıncı bir bagete telefonmuş gibi ...! Tam bir profesyonel.'::text,'konuşuyor'::text,'konuşur'::text,'konuştu'::text,'Şu anda fırıncı bir bagete telefonmuş gibi konuşuyor! Tam bir profesyonel.'::text),
(333108,37012,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp most a pék ... egy bagettbe, mintha telefon lenne. Igazi profi.'::text,'beszél'::text,'beszél'::text,'beszélt'::text,'Épp most a pék beszél egy bagettbe, mintha telefon lenne. Igazi profi.'::text),
(332823,36981,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... den Speck neben das Ei in die schwarze Pfanne.'::text,'legt'::text,'wird gelegt'::text,'legend'::text,'Er legt den Speck neben das Ei in die schwarze Pfanne.'::text),
(332827,36981,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... бекон поруч із яйцем на чорну пательню.'::text,'кладе'::text,'кладеться'::text,'кладучи'::text,'Він кладе бекон поруч із яйцем на чорну пательню.'::text),
(332826,36981,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... el beicon junto al huevo en la sartén negra.'::text,'pone'::text,'es puesto'::text,'poniendo'::text,'Él pone el beicon junto al huevo en la sartén negra.'::text),
(332825,36981,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... le bacon à côté de l''œuf dans la poêle noire.'::text,'pose'::text,'est posé'::text,'posant'::text,'Il pose le bacon à côté de l''œuf dans la poêle noire.'::text),
(332828,36981,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O pastırmayı siyah tavada yumurtanın yanına ...'::text,'koyuyor'::text,'konuyor'::text,'koyarak'::text,'O pastırmayı siyah tavada yumurtanın yanına koyuyor.'::text),
(332829,36981,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő a szalonnát a tojás mellé ... a fekete serpenyőbe.'::text,'teszi'::text,'van téve'::text,'téve'::text,'Ő a szalonnát a tojás mellé teszi a fekete serpenyőbe.'::text),
(332877,36987,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, der Speck ... schon so fünf Minuten und brutzelt immer noch, kein Witz.'::text,'brät'::text,'brät'::text,'brät'::text,'Bro, der Speck brät schon so fünf Minuten und brutzelt immer noch, kein Witz.'::text),
(332881,36987,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, той бекон ... вже хвилин п''ять і досі шкварчить, без брехні.'::text,'смажиться'::text,'смажиться'::text,'смажиться'::text,'Бро, той бекон смажиться вже хвилин п''ять і досі шкварчить, без брехні.'::text),
(332880,36987,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ese beicon ... desde hace como cinco minutos y sigue chisporroteando, sin mentir.'::text,'se ha estado friendo'::text,'se está friendo'::text,'se fríe'::text,'Bro, ese beicon se ha estado friendo desde hace como cinco minutos y sigue chisporroteando, sin mentir.'::text),
(332879,36987,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, ce bacon ... depuis genre cinq minutes et il grésille encore, sans mentir.'::text,'cuit'::text,'cuit'::text,'cuit'::text,'Frère, ce bacon cuit depuis genre cinq minutes et il grésille encore, sans mentir.'::text),
(332882,36987,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o pastırma beş dakikadır falan ... ve hâlâ cızırdıyor, yalan yok.'::text,'kızarıyor'::text,'kızarıyor'::text,'kızarır'::text,'Kanka, o pastırma beş dakikadır falan kızarıyor ve hâlâ cızırdıyor, yalan yok.'::text),
(332883,36987,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, az a szalonna már vagy öt perce ..., és még mindig serceg, nem kamu.'::text,'sül'::text,'sül'::text,'sül'::text,'Tesó, az a szalonna már vagy öt perce sül, és még mindig serceg, nem kamu.'::text),
(357114,39680,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... schon seit zwei Stunden durch diese Galerie.'::text,'läuft'::text,'läuft'::text,'läuft'::text,'Er läuft schon seit zwei Stunden durch diese Galerie.'::text),
(357118,39680,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... цією галереєю вже дві години.'::text,'гуляє'::text,'гуляє'::text,'гуляє'::text,'Він гуляє цією галереєю вже дві години.'::text),
(357117,39680,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... por esta galería desde hace dos horas.'::text,'ha estado paseando'::text,'está paseando'::text,'pasea'::text,'Él ha estado paseando por esta galería desde hace dos horas.'::text),
(357116,39680,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... dans cette galerie depuis deux heures.'::text,'se promène'::text,'se promène'::text,'se promène'::text,'Il se promène dans cette galerie depuis deux heures.'::text),
(357119,39680,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O iki saattir bu galeride ...'::text,'dolaşıyor'::text,'dolaşıyor'::text,'dolaşır'::text,'O iki saattir bu galeride dolaşıyor.'::text),
(357120,39680,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő már két órája ... ebben a galériában.'::text,'sétál'::text,'sétál'::text,'sétál'::text,'Ő már két órája sétál ebben a galériában.'::text),
(357150,39684,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er lässt seine Aktentasche an der Galerietür ..., offensichtlich ein sehr entspannter Besuch.'::text,'kontrollieren'::text,'kontrollieren'::text,'kontrollieren'::text,'Er lässt seine Aktentasche an der Galerietür kontrollieren, offensichtlich ein sehr entspannter Besuch.'::text),
(357154,39684,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він дає ... свій портфель біля дверей галереї, очевидно, дуже розслаблений візит.'::text,'перевірити'::text,'перевірити'::text,'перевірити'::text,'Він дає перевірити свій портфель біля дверей галереї, очевидно, дуже розслаблений візит.'::text),
(357153,39684,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él está haciendo que le ... el maletín en la puerta de la galería, obviamente una visita muy relajada.'::text,'revisen'::text,'revisen'::text,'revisen'::text,'Él está haciendo que le revisen el maletín en la puerta de la galería, obviamente una visita muy relajada.'::text),
(357152,39684,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il fait ... sa mallette à la porte de la galerie, évidemment une visite très détendue.'::text,'contrôler'::text,'contrôler'::text,'contrôler'::text,'Il fait contrôler sa mallette à la porte de la galerie, évidemment une visite très détendue.'::text),
(357155,39684,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, galeri kapısında çantasını ..., belli ki çok rahat bir ziyaret.'::text,'kontrol ettiriyor'::text,'kontrol ettiriyor'::text,'kontrol ettiriyor'::text,'O, galeri kapısında çantasını kontrol ettiriyor, belli ki çok rahat bir ziyaret.'::text),
(357156,39684,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő a galéria ajtajánál ... a táskáját, nyilván nagyon laza látogatás.'::text,'ellenőrizteti'::text,'ellenőrizteti'::text,'ellenőrizteti'::text,'Ő a galéria ajtajánál ellenőrizteti a táskáját, nyilván nagyon laza látogatás.'::text),
(357312,39702,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... jede Nacht stundenlang, bevor sie Profi-Gamerin wurde! Total besessen!'::text,'spielte immer'::text,'spielte früher'::text,'war es gewohnt zu spielen'::text,'Sie spielte immer jede Nacht stundenlang, bevor sie Profi-Gamerin wurde! Total besessen!'::text),
(357316,39702,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... годинами щоночі, поки не стала професійною геймеркою! Повністю одержима!'::text,'грала'::text,'грала'::text,'звикла грати'::text,'Вона грала годинами щоночі, поки не стала професійною геймеркою! Повністю одержима!'::text),
(357315,39702,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ella ... durante horas cada noche antes de convertirse en gamer profesional! ¡Totalmente obsesionada!'::text,'jugaba'::text,'solía jugar'::text,'estaba acostumbrada a jugar'::text,'¡Ella jugaba durante horas cada noche antes de convertirse en gamer profesional! ¡Totalmente obsesionada!'::text),
(357314,39702,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... pendant des heures chaque nuit avant de devenir gamer pro ! Complètement obsédée !'::text,'jouait'::text,'jouait'::text,'avait l''habitude de jouer'::text,'Elle jouait pendant des heures chaque nuit avant de devenir gamer pro ! Complètement obsédée !'::text),
(357317,39702,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, profesyonel bir oyuncu olmadan önce her gece saatlerce ...! Tamamen takıntılıydı!'::text,'oynardı'::text,'oynardı'::text,'oynamaya alışkındı'::text,'O, profesyonel bir oyuncu olmadan önce her gece saatlerce oynardı! Tamamen takıntılıydı!'::text),
(357318,39702,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő minden éjjel órákig ..., mielőtt profi gamer lett! Teljesen megszállott!'::text,'játszott'::text,'játszott'::text,'hozzá volt szokva a játékhoz'::text,'Ő minden éjjel órákig játszott, mielőtt profi gamer lett! Teljesen megszállott!'::text),
(335568,37286,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Mitarbeiterin winkt ihn durch, weil ... schon begonnen hat.'::text,'das Boarding'::text,'das Boarding'::text,'ein Boarding'::text,'Die Mitarbeiterin winkt ihn durch, weil das Boarding schon begonnen hat.'::text),
(335572,37286,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Працівник махає йому проходити, бо ... вже почалася.'::text,'посадка'::text,'посадка'::text,'посадка'::text,'Працівник махає йому проходити, бо посадка вже почалася.'::text),
(335571,37286,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El agente le hace señas para que pase porque ... ya ha empezado.'::text,'el embarque'::text,'el embarque'::text,'un embarque'::text,'El agente le hace señas para que pase porque el embarque ya ha empezado.'::text),
(335570,37286,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''agent lui fait signe de passer parce que ... a déjà commencé.'::text,'l''embarquement'::text,'l''embarquement'::text,'un embarquement'::text,'L''agent lui fait signe de passer parce que l''embarquement a déjà commencé.'::text),
(335573,37286,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Görevli ona geçmesini işaret ediyor çünkü ... çoktan başladı.'::text,'biniş'::text,'biniş'::text,'bir biniş'::text,'Görevli ona geçmesini işaret ediyor çünkü biniş çoktan başladı.'::text),
(335574,37286,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az ügyintéző átinti, mert ... már elkezdődött.'::text,'a beszállás'::text,'a beszállás'::text,'egy beszállás'::text,'Az ügyintéző átinti, mert a beszállás már elkezdődött.'::text),
(354765,39419,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, sie schwört, dass der Schwarm morgen bei Sonnenuntergang ...'::text,'zurückkommt'::text,'gerade zurückkommt'::text,'zurückkommt'::text,'Mädel, sie schwört, dass der Schwarm morgen bei Sonnenuntergang zurückkommt.'::text),
(354769,39419,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дівчино, вона клянеться, що зграя ... завтра на заході сонця.'::text,'повернеться'::text,'повертатиметься'::text,'повертається'::text,'Дівчино, вона клянеться, що зграя повернеться завтра на заході сонця.'::text),
(354768,39419,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, ella jura que la bandada ... mañana al atardecer.'::text,'volverá'::text,'estará volviendo'::text,'vuelve'::text,'Tía, ella jura que la bandada volverá mañana al atardecer.'::text),
(354767,39419,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, elle jure que la nuée ... demain au coucher du soleil.'::text,'reviendra'::text,'sera en train de revenir'::text,'revient'::text,'Meuf, elle jure que la nuée reviendra demain au coucher du soleil.'::text),
(354770,39419,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, o sürünün yarın gün batımında ... yemin ediyor.'::text,'döneceğine'::text,'dönüyor olacağına'::text,'döndüğüne'::text,'Kızım, o sürünün yarın gün batımında döneceğine yemin ediyor.'::text),
(354771,39419,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, ő esküszik, hogy a madárraj holnap naplementekor ...'::text,'visszajön'::text,'épp visszajön'::text,'visszajön'::text,'Csajszi, ő esküszik, hogy a madárraj holnap naplementekor visszajön.'::text),
(354801,39423,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du hast auf den Schwarm gezeigt, bevor irgendjemand sonst ihn ..., ehrlich beeindruckend.'::text,'bemerkt hatte'::text,'bemerkt hat'::text,'bemerkte'::text,'Du hast auf den Schwarm gezeigt, bevor irgendjemand sonst ihn bemerkt hatte, ehrlich beeindruckend.'::text),
(354805,39423,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти показав на зграю раніше, ніж хтось інший її ..., чесно, вражає.'::text,'помітив'::text,'помітив'::text,'помічав'::text,'Ти показав на зграю раніше, ніж хтось інший її помітив, чесно, вражає.'::text),
(354804,39423,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tú señalaste la bandada antes de que nadie más la ..., sinceramente impresionante.'::text,'hubiera visto'::text,'haya visto'::text,'viera'::text,'Tú señalaste la bandada antes de que nadie más la hubiera visto, sinceramente impresionante.'::text),
(354803,39423,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu as montré la nuée du doigt avant que quelqu''un d''autre l''..., franchement impressionnant.'::text,'ait remarquée'::text,'ait remarquée'::text,'remarque'::text,'Tu as montré la nuée du doigt avant que quelqu''un d''autre l''ait remarquée, franchement impressionnant.'::text),
(354806,39423,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sen sürüyü başka kimse ... önce gösterdin, açıkçası etkileyici.'::text,'fark etmeden'::text,'fark etmeden'::text,'fark etmeden'::text,'Sen sürüyü başka kimse fark etmeden önce gösterdin, açıkçası etkileyici.'::text),
(354807,39423,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Te a madárrajra mutattál, mielőtt bárki más ..., őszintén lenyűgöző.'::text,'észrevette volna'::text,'észrevette'::text,'észrevette'::text,'Te a madárrajra mutattál, mielőtt bárki más észrevette volna, őszintén lenyűgöző.'::text),
(357582,39732,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er ein trauriges Lied spielte, ... die Menschenmenge.'::text,'schrumpfte'::text,'wird schrumpfen'::text,'schrumpft'::text,'Wenn er ein trauriges Lied spielte, schrumpfte die Menschenmenge.'::text),
(357586,39732,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби він заграв сумну пісню, юрба ...'::text,'поменшала б'::text,'поменшає'::text,'меншає'::text,'Якби він заграв сумну пісню, юрба поменшала б.'::text),
(357585,39732,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si tocara una canción triste, la multitud ...'::text,'se haría más pequeña'::text,'se hará más pequeña'::text,'se hace más pequeña'::text,'Si tocara una canción triste, la multitud se haría más pequeña.'::text),
(357584,39732,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il jouait une chanson triste, l''attroupement ...'::text,'rétrécirait'::text,'rétrécira'::text,'rétrécit'::text,'S''il jouait une chanson triste, l''attroupement rétrécirait.'::text),
(357587,39732,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O hüzünlü bir şarkı çalsaydı, kalabalık ...'::text,'küçülürdü'::text,'küçülecek'::text,'küçülüyor'::text,'O hüzünlü bir şarkı çalsaydı, kalabalık küçülürdü.'::text),
(357588,39732,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha szomorú dalt játszana, a tömeg ...'::text,'összezsugorodna'::text,'össze fog zsugorodni'::text,'összezsugorodik'::text,'Ha szomorú dalt játszana, a tömeg összezsugorodna.'::text),
(371244,41250,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nie zuvor ... so viele Menschen um ein einziges Neugeborenes herum.'::text,'waren'::text,'waren'::text,'waren'::text,'Nie zuvor waren so viele Menschen um ein einziges Neugeborenes herum.'::text),
(371248,41250,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ніколи раніше ... стільки людей навколо одного новонародженого малюка.'::text,'не було'::text,'не було'::text,'не було'::text,'Ніколи раніше не було стільки людей навколо одного новонародженого малюка.'::text),
(371247,41250,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nunca antes ... tanta gente alrededor de un solo recién nacido.'::text,'había habido'::text,'había habido'::text,'había habido'::text,'Nunca antes había habido tanta gente alrededor de un solo recién nacido.'::text),
(371246,41250,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jamais auparavant il n''y ... autant de monde autour d''un seul nouveau-né.'::text,'avait eu'::text,'avait eu'::text,'avait eu'::text,'Jamais auparavant il n''y avait eu autant de monde autour d''un seul nouveau-né.'::text),
(371249,41250,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Daha önce hiç tek bir yeni doğmuş bebeğin etrafında bu kadar çok insan ...'::text,'olmamıştı'::text,'olmamıştı'::text,'olmamıştı'::text,'Daha önce hiç tek bir yeni doğmuş bebeğin etrafında bu kadar çok insan olmamıştı.'::text),
(371250,41250,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Még soha ... ennyi ember egyetlen újszülött baba körül.'::text,'nem volt'::text,'nem volt'::text,'nem volt'::text,'Még soha nem volt ennyi ember egyetlen újszülött baba körül.'::text),
(403482,44832,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während sie die Messinguhr in der Werkstatt ..., sang die Kuckucksuhr. Nicht ideales Timing.'::text,'reparierte'::text,'reparierte'::text,'repariert hat'::text,'Während sie die Messinguhr in der Werkstatt reparierte, sang die Kuckucksuhr. Nicht ideales Timing.'::text),
(403486,44832,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки вона ... латунний годинник у майстерні, заспівав годинник із зозулею. Не найкращий таймінг.'::text,'лагодила'::text,'полагодила'::text,'полагодила'::text,'Поки вона лагодила латунний годинник у майстерні, заспівав годинник із зозулею. Не найкращий таймінг.'::text),
(403485,44832,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mientras ella ... el reloj de latón en el taller, el reloj de cuco cantó. No es el timing ideal.'::text,'arreglaba'::text,'arregló'::text,'ha arreglado'::text,'Mientras ella arreglaba el reloj de latón en el taller, el reloj de cuco cantó. No es el timing ideal.'::text),
(403484,44832,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant qu''elle ... l''horloge en laiton dans l''atelier, le coucou a chanté. Pas le timing idéal.'::text,'réparait'::text,'a réparé'::text,'a réparé'::text,'Pendant qu''elle réparait l''horloge en laiton dans l''atelier, le coucou a chanté. Pas le timing idéal.'::text),
(403487,44832,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O atölyede pirinç saati ..., guguklu saat öttü. Pek ideal bir zamanlama değil.'::text,'tamir ederken'::text,'tamir ettiğinde'::text,'tamir etti'::text,'O atölyede pirinç saati tamir ederken, guguklu saat öttü. Pek ideal bir zamanlama değil.'::text),
(403488,44832,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miközben ő ... a sárgaréz órát a műhelyben, megszólalt a kakukkos óra. Nem ideális időzítés.'::text,'javította'::text,'megjavította'::text,'megjavította'::text,'Miközben ő javította a sárgaréz órát a műhelyben, megszólalt a kakukkos óra. Nem ideális időzítés.'::text),
(403545,44839,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Werkstatt, ... Wände mit Werkzeug bedeckt sind, beherbergt auch eine geschnitzte Kuckucksuhr.'::text,'deren'::text,'die'::text,'welche'::text,'Die Werkstatt, deren Wände mit Werkzeug bedeckt sind, beherbergt auch eine geschnitzte Kuckucksuhr.'::text),
(403549,44839,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Майстерня, ... стіни вкриті інструментами, також має різьблений годинник із зозулею.'::text,'чиї'::text,'яка'::text,'що'::text,'Майстерня, чиї стіни вкриті інструментами, також має різьблений годинник із зозулею.'::text),
(403548,44839,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El taller, ... paredes están cubiertas de herramientas, también guarda un reloj de cuco tallado.'::text,'cuyas'::text,'que'::text,'el cual'::text,'El taller, cuyas paredes están cubiertas de herramientas, también guarda un reloj de cuco tallado.'::text),
(403547,44839,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''atelier, ... les murs sont couverts d''outils, abrite aussi une horloge à coucou sculptée.'::text,'dont'::text,'qui'::text,'que'::text,'L''atelier, dont les murs sont couverts d''outils, abrite aussi une horloge à coucou sculptée.'::text),
(403550,44839,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... duvarları aletlerle kaplı olan atölyede oymalı bir guguklu saat de var.'::text,''::text,NULL::text,NULL::text,'Duvarları aletlerle kaplı olan atölyede oymalı bir guguklu saat de var.'::text),
(403551,44839,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A műhely, ... falait szerszámok borítják, egy faragott kakukkos órát is rejt.'::text,'amelynek a'::text,'amely'::text,'ami'::text,'A műhely, amelynek a falait szerszámok borítják, egy faragott kakukkos órát is rejt.'::text),
(396201,44023,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, anscheinend ist der Typ, ... ihr auf der Terrasse Saft eingeschenkt hat, ihr neuer Freund.'::text,'der'::text,'das'::text,'dessen'::text,'Mädel, anscheinend ist der Typ, der ihr auf der Terrasse Saft eingeschenkt hat, ihr neuer Freund.'::text),
(396205,44023,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дівчино, кажуть, хлопець, ... налив їй сік на терасі, — її новий хлопець.'::text,'який'::text,'що'::text,'чий'::text,'Дівчино, кажуть, хлопець, який налив їй сік на терасі, — її новий хлопець.'::text),
(396204,44023,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer el chico ... le sirvió zumo en la terraza es su nuevo novio.'::text,'que'::text,'el cual'::text,'cuyo'::text,'Tía, al parecer el chico que le sirvió zumo en la terraza es su nuevo novio.'::text),
(396203,44023,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment le mec ... lui a servi du jus sur la terrasse est son nouveau copain.'::text,'qui'::text,'que'::text,'dont'::text,'Meuf, apparemment le mec qui lui a servi du jus sur la terrasse est son nouveau copain.'::text),
(396206,44023,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, güya ... terasta ona meyve suyu dolduran çocuk onun yeni sevgilisiymiş.'::text,''::text,NULL::text,NULL::text,'Kızım, güya terasta ona meyve suyu dolduran çocuk onun yeni sevgilisiymiş.'::text),
(396207,44023,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag a srác, ... a teraszon gyümölcslevet töltött neki, az új pasija.'::text,'aki'::text,'ami'::text,'akinek'::text,'Csajszi, állítólag a srác, aki a teraszon gyümölcslevet töltött neki, az új pasija.'::text),
(396237,44027,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, deine Terrasse ... so einen charmanten Blick auf den Garten.'::text,'hat'::text,'hat'::text,'hatte'::text,'Ehrlich, deine Terrasse hat so einen charmanten Blick auf den Garten.'::text),
(396241,44027,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, твоя тераса ... такий чарівний вид на сад.'::text,'має'::text,'має'::text,'мала'::text,'Чесно, твоя тераса має такий чарівний вид на сад.'::text),
(396240,44027,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, tu terraza ... una vista tan encantadora del jardín.'::text,'tiene'::text,'está teniendo'::text,'ha tenido'::text,'Sinceramente, tu terraza tiene una vista tan encantadora del jardín.'::text),
(396239,44027,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, ta terrasse ... une vue si charmante sur le jardin.'::text,'a'::text,'a'::text,'a eu'::text,'Franchement, ta terrasse a une vue si charmante sur le jardin.'::text),
(396242,44027,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, terasının bahçeye öyle büyüleyici bir manzarası ...'::text,'var'::text,'var'::text,'vardı'::text,'Açıkçası, terasının bahçeye öyle büyüleyici bir manzarası var.'::text),
(396243,44027,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, a teraszodról olyan elbűvölő kilátás ... a kertre.'::text,'nyílik'::text,'nyílik'::text,'nyílt'::text,'Őszintén, a teraszodról olyan elbűvölő kilátás nyílik a kertre.'::text),
(389955,43329,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während sie ihre Finger durch den Sand ..., funkelten winzige blaue Lichter um ihre Hand.'::text,'zog'::text,'zog'::text,'gezogen hat'::text,'Während sie ihre Finger durch den Sand zog, funkelten winzige blaue Lichter um ihre Hand.'::text),
(389959,43329,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки вона ... пальцями по піску, навколо її руки мерехтіли крихітні сині вогники.'::text,'водила'::text,'провела'::text,'провела'::text,'Поки вона водила пальцями по піску, навколо її руки мерехтіли крихітні сині вогники.'::text),
(389958,43329,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mientras ella ... los dedos por la arena, unas lucecitas azules brillaban alrededor de su mano.'::text,'arrastraba'::text,'arrastró'::text,'ha arrastrado'::text,'Mientras ella arrastraba los dedos por la arena, unas lucecitas azules brillaban alrededor de su mano.'::text),
(389957,43329,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant qu''elle ... ses doigts dans le sable, de minuscules lumières bleues scintillaient autour de sa main.'::text,'passait'::text,'a passé'::text,'a passé'::text,'Pendant qu''elle passait ses doigts dans le sable, de minuscules lumières bleues scintillaient autour de sa main.'::text),
(389960,43329,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O parmaklarını kumda ..., elinin etrafında minik mavi ışıklar parıldadı.'::text,'gezdirirken'::text,'gezdirdiğinde'::text,'gezdirdi'::text,'O parmaklarını kumda gezdirirken, elinin etrafında minik mavi ışıklar parıldadı.'::text),
(389961,43329,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miközben ő ... az ujjait a homokban, apró kék fények szikráztak a keze körül.'::text,'húzta'::text,'végighúzta'::text,'végighúzta'::text,'Miközben ő húzta az ujjait a homokban, apró kék fények szikráztak a keze körül.'::text),
(390045,43339,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das ganze Ufer ... in blauem Licht, als sie vor der Welle zurücktrat.'::text,'funkelte'::text,'hat gefunkelt'::text,'funkelt'::text,'Das ganze Ufer funkelte in blauem Licht, als sie vor der Welle zurücktrat.'::text),
(390049,43339,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Увесь берег ... синім світлом, коли вона відступила від хвилі.'::text,'мерехтів'::text,'замерехтів'::text,'мерехтить'::text,'Увесь берег мерехтів синім світлом, коли вона відступила від хвилі.'::text),
(390048,43339,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Toda la orilla ... de luz azul cuando ella retrocedió ante la ola.'::text,'estaba brillando'::text,'ha brillado'::text,'está brillando'::text,'Toda la orilla estaba brillando de luz azul cuando ella retrocedió ante la ola.'::text),
(390047,43339,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tout le rivage ... de lumière bleue quand elle a reculé devant la vague.'::text,'scintillait'::text,'a scintillé'::text,'scintille'::text,'Tout le rivage scintillait de lumière bleue quand elle a reculé devant la vague.'::text),
(390050,43339,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O dalgadan geri çekildiğinde bütün kıyı mavi ışıkla ...'::text,'parıldıyordu'::text,'parıldadı'::text,'parıldıyor'::text,'O dalgadan geri çekildiğinde bütün kıyı mavi ışıkla parıldıyordu.'::text),
(390051,43339,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az egész part kék fényben ..., amikor ő hátralépett a hullám elől.'::text,'szikrázott'::text,'szikrázott'::text,'szikrázik'::text,'Az egész part kék fényben szikrázott, amikor ő hátralépett a hullám elől.'::text),
(400224,44470,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Nuggets sehen wertvoll aus, also lässt er sie in der Stadt ...'::text,'wiegen'::text,'wiegen'::text,'wiegen'::text,'Die Nuggets sehen wertvoll aus, also lässt er sie in der Stadt wiegen.'::text),
(400228,44470,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Самородки виглядають цінними, тож він дасть їх ... у місті.'::text,'зважити'::text,'зважити'::text,'зважити'::text,'Самородки виглядають цінними, тож він дасть їх зважити у місті.'::text),
(400227,44470,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las pepitas parecen valiosas, así que él las hará ... en el pueblo.'::text,'pesar'::text,'pesar'::text,'pesar'::text,'Las pepitas parecen valiosas, así que él las hará pesar en el pueblo.'::text),
(400226,44470,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les pépites ont l''air précieuses, donc il va les faire ... en ville.'::text,'peser'::text,'peser'::text,'peser'::text,'Les pépites ont l''air précieuses, donc il va les faire peser en ville.'::text),
(400229,44470,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Külçeler değerli görünüyor, bu yüzden o onları kasabada ...'::text,'tarttıracak'::text,'tartacak'::text,'tartmak'::text,'Külçeler değerli görünüyor, bu yüzden o onları kasabada tarttıracak.'::text),
(400230,44470,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A rögök értékesnek tűnnek, ezért ő a városban ... őket.'::text,'lemérteti'::text,'lemér'::text,'lemérni'::text,'A rögök értékesnek tűnnek, ezért ő a városban lemérteti őket.'::text),
(332193,36911,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, wenn du den Stempel ..., ist deine Autorität für alle klar.'::text,'drückst'::text,'drücktest'::text,'drücken wirst'::text,'Ehrlich, wenn du den Stempel drückst, ist deine Autorität für alle klar.'::text),
(332197,36911,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, коли ти ... ту печатку, твій авторитет усім зрозумілий.'::text,'ставиш'::text,'поставила'::text,'поставиш'::text,'Чесно, коли ти ставиш ту печатку, твій авторитет усім зрозумілий.'::text),
(332196,36911,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, cuando tú ... ese sello, tu autoridad queda clara para todos.'::text,'pones'::text,'pusiste'::text,'pondrás'::text,'Sinceramente, cuando tú pones ese sello, tu autoridad queda clara para todos.'::text),
(332195,36911,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, quand tu ... ce tampon, ton autorité est claire pour tout le monde.'::text,'appuies sur'::text,'as appuyé sur'::text,'appuieras sur'::text,'Franchement, quand tu appuies sur ce tampon, ton autorité est claire pour tout le monde.'::text),
(332198,36911,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, sen o mührü ..., otoriten herkes için net.'::text,'bastığında'::text,'bastığında'::text,'basacağında'::text,'Açıkçası, sen o mührü bastığında, otoriten herkes için net.'::text),
(332199,36911,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, amikor te ... azt a pecsétet, a tekintélyed mindenki számára világos.'::text,'lenyomod'::text,'lenyomtad'::text,'le fogod nyomni'::text,'Őszintén, amikor te lenyomod azt a pecsétet, a tekintélyed mindenki számára világos.'::text),
(332238,36916,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, der Assistent hat irgendwie zugegeben, ihre Autorität ..., kein Witz.'::text,'infrage gestellt zu haben'::text,'infrage zu stellen'::text,'stellte infrage'::text,'Bro, der Assistent hat irgendwie zugegeben, ihre Autorität infrage gestellt zu haben, kein Witz.'::text),
(332242,36916,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, помічник типу визнав, що ... її авторитет, без брехні.'::text,'ставив під сумнів'::text,'ставити під сумнів'::text,'поставив під сумнів'::text,'Бро, помічник типу визнав, що ставив під сумнів її авторитет, без брехні.'::text),
(332241,36916,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, el asistente como que admitió ... su autoridad, sin mentir.'::text,'haber cuestionado'::text,'cuestionar'::text,'cuestionó'::text,'Bro, el asistente como que admitió haber cuestionado su autoridad, sin mentir.'::text),
(332240,36916,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, l''assistant a genre avoué ... son autorité, sans mentir.'::text,'avoir remis en question'::text,'remettre en question'::text,'a remis en question'::text,'Frère, l''assistant a genre avoué avoir remis en question son autorité, sans mentir.'::text),
(332243,36916,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, yardımcı resmen onun otoritesini ... itiraf etti, yalan yok.'::text,'sorguladığını'::text,'sorgulamayı'::text,'sorguladı'::text,'Kanka, yardımcı resmen onun otoritesini sorguladığını itiraf etti, yalan yok.'::text),
(332244,36916,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, az asszisztens kábé beismerte, hogy ... a tekintélyét, nem kamu.'::text,'megkérdőjelezte'::text,'megkérdőjelezni'::text,'megkérdőjelezte'::text,'Tesó, az asszisztens kábé beismerte, hogy megkérdőjelezte a tekintélyét, nem kamu.'::text),
(341967,37997,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Konflikt am Tisch geht weiter, ... der Frau, die von der Tür aus zusieht.'::text,'trotz'::text,'obwohl'::text,'damit'::text,'Der Konflikt am Tisch geht weiter, trotz der Frau, die von der Tür aus zusieht.'::text),
(341971,37997,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Конфлікт за столом триває ... жінку, яка дивиться з дверей.'::text,'попри'::text,'хоча'::text,'щоб'::text,'Конфлікт за столом триває попри жінку, яка дивиться з дверей.'::text),
(341970,37997,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El conflicto en la mesa continúa ... la mujer que mira desde la puerta.'::text,'a pesar de'::text,'aunque'::text,'para que'::text,'El conflicto en la mesa continúa a pesar de la mujer que mira desde la puerta.'::text),
(341969,37997,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le conflit à la table continue ... la femme qui regarde depuis la porte.'::text,'malgré'::text,'bien que'::text,'pour que'::text,'Le conflit à la table continue malgré la femme qui regarde depuis la porte.'::text),
(341972,37997,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Masadaki çatışma, kapıdan izleyen kadına ... sürüyor.'::text,'rağmen'::text,'gerçi'::text,'diye'::text,'Masadaki çatışma, kapıdan izleyen kadına rağmen sürüyor.'::text),
(341973,37997,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az asztalnál a konfliktus az ajtóból figyelő nő ... folytatódik.'::text,'ellenére'::text,'bár'::text,'hogy'::text,'Az asztalnál a konfliktus az ajtóból figyelő nő ellenére folytatódik.'::text),
(372576,41398,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie die Unterlagen nicht mitgebracht hätte, ... das Meeting jetzt auf Eis.'::text,'läge'::text,'hätte gelegen'::text,'wird liegen'::text,'Wenn sie die Unterlagen nicht mitgebracht hätte, läge das Meeting jetzt auf Eis.'::text),
(372580,41398,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби вона не принесла документи, нарада зараз ... призупинена.'::text,'була б'::text,'була б'::text,'буде'::text,'Якби вона не принесла документи, нарада зараз була б призупинена.'::text),
(372579,41398,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si no hubiera traído los papeles, la reunión ... en pausa ahora mismo.'::text,'estaría'::text,'habría estado'::text,'estará'::text,'Si no hubiera traído los papeles, la reunión estaría en pausa ahora mismo.'::text),
(372578,41398,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle n''avait pas apporté les papiers, la réunion ... en suspens en ce moment.'::text,'serait'::text,'aurait été'::text,'sera'::text,'Si elle n''avait pas apporté les papiers, la réunion serait en suspens en ce moment.'::text),
(372581,41398,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O belgeleri getirmeseydi, toplantı şu anda askıya alınmış ...'::text,'olurdu'::text,'olmuş olurdu'::text,'olacak'::text,'O belgeleri getirmeseydi, toplantı şu anda askıya alınmış olurdu.'::text),
(372582,41398,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nem hozta volna el az iratokat, a megbeszélés most ... szüneteltetve.'::text,'lenne'::text,'lett volna'::text,'lesz'::text,'Ha nem hozta volna el az iratokat, a megbeszélés most lenne szüneteltetve.'::text),
(374700,41634,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... schon zwanzig Pflanzen gepflanzt, und der Garten ist komplett verwandelt!'::text,'haben'::text,'haben'::text,'pflanzten'::text,'Sie haben schon zwanzig Pflanzen gepflanzt, und der Garten ist komplett verwandelt!'::text),
(374704,41634,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони вже ... двадцять рослин, і сад повністю змінився!'::text,'посадили'::text,'садили'::text,'посадили'::text,'Вони вже посадили двадцять рослин, і сад повністю змінився!'::text),
(374703,41634,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ellos ya ... veinte plantas y el jardín está totalmente transformado!'::text,'han plantado'::text,'han estado plantando'::text,'plantaron'::text,'¡Ellos ya han plantado veinte plantas y el jardín está totalmente transformado!'::text),
(374702,41634,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ... déjà vingt plantes, et le jardin est complètement transformé !'::text,'ont planté'::text,'plantent'::text,'ont planté'::text,'Ils ont planté déjà vingt plantes, et le jardin est complètement transformé !'::text),
(374705,41634,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onlar şimdiden yirmi bitki ... ve bahçe tamamen değişti!'::text,'diktiler'::text,'dikiyorlar'::text,'diktiler'::text,'Onlar şimdiden yirmi bitki diktiler ve bahçe tamamen değişti!'::text),
(374706,41634,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ők már húsz növényt ..., és a kert teljesen átalakult!'::text,'ültettek el'::text,'ültetnek'::text,'ültettek'::text,'Ők már húsz növényt ültettek el, és a kert teljesen átalakult!'::text),
(374745,41639,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, die ganze Familie ... gerade Blumen, irgendwie süß.'::text,'pflanzt'::text,'pflanzt'::text,'hat gepflanzt'::text,'Yo, die ganze Familie pflanzt gerade Blumen, irgendwie süß.'::text),
(374749,41639,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, вся родина зараз ... квіти, якось мило.'::text,'садить'::text,'садить'::text,'посадила'::text,'Йо, вся родина зараз садить квіти, якось мило.'::text),
(374748,41639,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, toda la familia ... flores ahora mismo, qué bonito.'::text,'está plantando'::text,'planta'::text,'ha plantado'::text,'Oye, toda la familia está plantando flores ahora mismo, qué bonito.'::text),
(374747,41639,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, toute la famille ... des fleurs en ce moment, trop mignon.'::text,'plante'::text,'plante'::text,'a planté'::text,'Yo, toute la famille plante des fleurs en ce moment, trop mignon.'::text),
(374750,41639,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, bütün aile şu anda çiçek ..., bayağı tatlı.'::text,'dikiyor'::text,'diker'::text,'dikti'::text,'Yo, bütün aile şu anda çiçek dikiyor, bayağı tatlı.'::text),
(374751,41639,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, az egész család épp virágot ..., elég cuki.'::text,'ültet'::text,'ültet'::text,'ültetett'::text,'Figyu, az egész család épp virágot ültet, elég cuki.'::text),
(383241,42583,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Schleifpapier, ... er zum Schleifen des Dachs benutzte, war in der Mitte gefaltet.'::text,'das'::text,'der'::text,'dessen'::text,'Das Schleifpapier, das er zum Schleifen des Dachs benutzte, war in der Mitte gefaltet.'::text),
(383245,42583,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Наждачний папір, ... він шліфував дах, був складений навпіл.'::text,'яким'::text,'хто'::text,'чий'::text,'Наждачний папір, яким він шліфував дах, був складений навпіл.'::text),
(383244,42583,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La lija ... usó para lijar el tejado estaba doblada por la mitad.'::text,'que'::text,'quien'::text,'cuya'::text,'La lija que usó para lijar el tejado estaba doblada por la mitad.'::text),
(383243,42583,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le papier de verre ... a utilisé pour poncer le toit était plié en deux.'::text,'qu''il'::text,'qui'::text,'dont il'::text,'Le papier de verre qu''il a utilisé pour poncer le toit était plié en deux.'::text),
(383246,42583,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... çatıyı zımparalamak için kullandığı zımpara kâğıdı ikiye katlanmıştı.'::text,''::text,NULL::text,NULL::text,'Çatıyı zımparalamak için kullandığı zımpara kâğıdı ikiye katlanmıştı.'::text),
(383247,42583,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A csiszolópapír, ... a tetőt csiszolta, félbe volt hajtva.'::text,'amivel'::text,'aki'::text,'akinek'::text,'A csiszolópapír, amivel a tetőt csiszolta, félbe volt hajtva.'::text),
(383295,42589,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Handwerker ... das Dach etwa zehn Minuten lang geschliffen, bevor die Oberfläche glatt war.'::text,'hatte'::text,'hat'::text,'schliff'::text,'Der Handwerker hatte das Dach etwa zehn Minuten lang geschliffen, bevor die Oberfläche glatt war.'::text),
(383299,42589,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Майстер ... дах приблизно десять хвилин, поки поверхня не стала гладкою.'::text,'шліфував'::text,'шліфує'::text,'шліфував'::text,'Майстер шліфував дах приблизно десять хвилин, поки поверхня не стала гладкою.'::text),
(383298,42589,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El artesano ... el tejado durante aproximadamente diez minutos antes de que la superficie quedara lisa.'::text,'había estado lijando'::text,'ha estado lijando'::text,'estaba lijando'::text,'El artesano había estado lijando el tejado durante aproximadamente diez minutos antes de que la superficie quedara lisa.'::text),
(383297,42589,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''artisan ... le toit pendant environ dix minutes avant que la surface soit lisse.'::text,'avait poncé'::text,'a poncé'::text,'ponçait'::text,'L''artisan avait poncé le toit pendant environ dix minutes avant que la surface soit lisse.'::text),
(383300,42589,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zanaatkâr, yüzey pürüzsüz hale gelmeden önce çatıyı yaklaşık on dakika ...'::text,'zımparalamıştı'::text,'zımparalıyor'::text,'zımparalıyordu'::text,'Zanaatkâr, yüzey pürüzsüz hale gelmeden önce çatıyı yaklaşık on dakika zımparalamıştı.'::text),
(383301,42589,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A mesterember körülbelül tíz percig ... a tetőt, mire a felület sima lett.'::text,'csiszolta'::text,'csiszolja'::text,'csiszolta'::text,'A mesterember körülbelül tíz percig csiszolta a tetőt, mire a felület sima lett.'::text),
(333309,37035,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn jemand niest, ... die Karten, die er ausbalanciert hat, komplett ein!'::text,'stürzen'::text,'stürzten'::text,'stürzten'::text,'Wenn jemand niest, stürzen die Karten, die er ausbalanciert hat, komplett ein!'::text),
(333313,37035,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо хтось чхне, карти, які він збалансував, ... повністю!'::text,'обваляться'::text,'обвалилися б'::text,'обвалилися'::text,'Якщо хтось чхне, карти, які він збалансував, обваляться повністю!'::text),
(333312,37035,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si alguien estornuda, las cartas que él equilibró se ... por completo!'::text,'derrumbarán'::text,'derrumbarían'::text,'derrumbaron'::text,'¡Si alguien estornuda, las cartas que él equilibró se derrumbarán por completo!'::text),
(333311,37035,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si quelqu''un éternue, les cartes qu''il a équilibrées ... complètement !'::text,'s''effondreront'::text,'s''effondreraient'::text,'se sont effondrées'::text,'Si quelqu''un éternue, les cartes qu''il a équilibrées s''effondreront complètement !'::text),
(333314,37035,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Biri hapşırırsa, onun dengelediği kartlar tamamen ...!'::text,'çökecek'::text,'çökerdi'::text,'çöktü'::text,'Biri hapşırırsa, onun dengelediği kartlar tamamen çökecek!'::text),
(333315,37035,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha valaki tüsszent, a kártyák, amiket ő egyensúlyba hozott, teljesen ...!'::text,'összeomlanak'::text,'összeomlanának'::text,'összeomlottak'::text,'Ha valaki tüsszent, a kártyák, amiket ő egyensúlyba hozott, teljesen összeomlanak!'::text),
(333354,37040,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Abendessen ... er fünfzig Karten zu einem Schloss aufgebaut. Keine große Sache.'::text,'hat'::text,'wird'::text,'baut'::text,'Bis zum Abendessen hat er fünfzig Karten zu einem Schloss aufgebaut. Keine große Sache.'::text),
(333358,37040,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До вечері він ... п''ятдесят карт у замок. Нічого особливого.'::text,'складе'::text,'складе'::text,'складає'::text,'До вечері він складе п''ятдесят карт у замок. Нічого особливого.'::text),
(333357,37040,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para la cena, él ... cincuenta cartas en un castillo. Nada del otro mundo.'::text,'habrá equilibrado'::text,'equilibrará'::text,'equilibra'::text,'Para la cena, él habrá equilibrado cincuenta cartas en un castillo. Nada del otro mundo.'::text),
(333356,37040,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici le dîner, il ... cinquante cartes en château. Rien de fou.'::text,'aura équilibré'::text,'équilibrera'::text,'équilibre'::text,'D''ici le dîner, il aura équilibré cinquante cartes en château. Rien de fou.'::text),
(333359,37040,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Akşam yemeğine kadar o elli kartı bir kale şeklinde ...! Çok da büyük olay değil.'::text,'dengelemiş olacak'::text,'dengeleyecek'::text,'dengeliyor'::text,'Akşam yemeğine kadar o elli kartı bir kale şeklinde dengelemiş olacak! Çok da büyük olay değil.'::text),
(333360,37040,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vacsorára ő ... egy várat ötven kártyából. Semmi különös.'::text,'felépít'::text,'fel fog építeni'::text,'épít'::text,'Vacsorára ő felépít egy várat ötven kártyából. Semmi különös.'::text),
(396759,44085,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er wünscht sich, dass er vor dem großen Tag ..., wie man eine Fliege bindet.'::text,'gelernt hätte'::text,'lernte'::text,'lernen würde'::text,'Er wünscht sich, dass er vor dem großen Tag gelernt hätte, wie man eine Fliege bindet.'::text),
(396763,44085,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він шкодує, що не ... зав''язувати метелика до великого дня.'::text,'навчився'::text,'навчився'::text,'навчився б'::text,'Він шкодує, що не навчився зав''язувати метелика до великого дня.'::text),
(396762,44085,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él desearía ... a atar una pajarita antes del gran día.'::text,'haber aprendido'::text,'aprender'::text,'aprendería'::text,'Él desearía haber aprendido a atar una pajarita antes del gran día.'::text),
(396761,44085,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il aimerait ... à nouer un nœud papillon avant le grand jour.'::text,'avoir appris'::text,'apprendre'::text,'apprendrait'::text,'Il aimerait avoir appris à nouer un nœud papillon avant le grand jour.'::text),
(396764,44085,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, büyük günden önce papyon bağlamayı ... diliyor.'::text,'öğrenmiş olmayı'::text,'öğrenmeyi'::text,'öğreneceğini'::text,'O, büyük günden önce papyon bağlamayı öğrenmiş olmayı diliyor.'::text),
(396765,44085,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő azt kívánja, bárcsak a nagy nap előtt ..., hogyan kell csokornyakkendőt kötni.'::text,'megtanulta volna'::text,'megtanulta'::text,'megtanulná'::text,'Ő azt kívánja, bárcsak a nagy nap előtt megtanulta volna, hogyan kell csokornyakkendőt kötni.'::text),
(359031,39893,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Bräutigam war fertig damit, seine Fliege zu ..., und ging hinaus in den Garten.'::text,'richten'::text,'richten'::text,'richten'::text,'Der Bräutigam war fertig damit, seine Fliege zu richten, und ging hinaus in den Garten.'::text),
(359035,39893,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Наречений закінчив ... метелика й вийшов у сад.'::text,'поправляти'::text,'поправити'::text,'поправити'::text,'Наречений закінчив поправляти метелика й вийшов у сад.'::text),
(359034,39893,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El novio terminó de ... la pajarita y salió al jardín.'::text,'arreglarse'::text,'arreglarse'::text,'arreglarse'::text,'El novio terminó de arreglarse la pajarita y salió al jardín.'::text),
(359033,39893,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le marié a fini d''... son nœud papillon et est sorti dans le jardin.'::text,'ajuster'::text,'ajuster'::text,'ajuster'::text,'Le marié a fini d''ajuster son nœud papillon et est sorti dans le jardin.'::text),
(359036,39893,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Damat papyonunu ... bitirdi ve bahçeye çıktı.'::text,'düzeltmeyi'::text,'düzeltmeyi'::text,'düzeltmeyi'::text,'Damat papyonunu düzeltmeyi bitirdi ve bahçeye çıktı.'::text),
(359037,39893,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vőlegény befejezte a csokornyakkendője ..., és kiment a kertbe.'::text,'igazgatását'::text,'igazgatását'::text,'igazgatását'::text,'A vőlegény befejezte a csokornyakkendője igazgatását, és kiment a kertbe.'::text),
(359058,39896,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Bräutigam ... vor der Hochzeit eine Stunde lang vor dem Spiegel gestanden! Ein Albtraum!'::text,'hatte'::text,'hat'::text,'stand'::text,'Der Bräutigam hatte vor der Hochzeit eine Stunde lang vor dem Spiegel gestanden! Ein Albtraum!'::text),
(359062,39896,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Наречений ... перед дзеркалом цілу годину перед весіллям! Жах!'::text,'стояв'::text,'стоїть'::text,'стояв'::text,'Наречений стояв перед дзеркалом цілу годину перед весіллям! Жах!'::text),
(359061,39896,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El novio ... una hora delante del espejo antes de la boda! ¡Una pesadilla!'::text,'había estado'::text,'ha estado'::text,'estaba'::text,'¡El novio había estado una hora delante del espejo antes de la boda! ¡Una pesadilla!'::text),
(359060,39896,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le marié ... devant le miroir pendant une heure avant le mariage ! Un cauchemar !'::text,'était resté'::text,'est resté'::text,'restait'::text,'Le marié était resté devant le miroir pendant une heure avant le mariage ! Un cauchemar !'::text),
(359063,39896,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Damat düğünden önce bir saat boyunca aynanın karşısında ...! Tam bir kâbus!'::text,'durmuştu'::text,'duruyor'::text,'duruyordu'::text,'Damat düğünden önce bir saat boyunca aynanın karşısında durmuştu! Tam bir kâbus!'::text),
(359064,39896,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vőlegény egy órán át ... a tükör előtt az esküvő előtt! Rémálom!'::text,'állt'::text,'áll'::text,'állt'::text,'A vőlegény egy órán át állt a tükör előtt az esküvő előtt! Rémálom!'::text),
(335901,37323,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Frau, ... den Blumenstrauß mitgebracht hat, trägt auch eine Flasche.'::text,'die'::text,'das'::text,'deren'::text,'Die Frau, die den Blumenstrauß mitgebracht hat, trägt auch eine Flasche.'::text),
(335905,37323,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жінка, ... принесла букет, несе й пляшку.'::text,'яка'::text,'що'::text,'чия'::text,'Жінка, яка принесла букет, несе й пляшку.'::text),
(335904,37323,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La mujer ... trajo el ramo también lleva una botella.'::text,'que'::text,'la cual'::text,'cuya'::text,'La mujer que trajo el ramo también lleva una botella.'::text),
(335903,37323,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La femme ... a apporté le bouquet porte aussi une bouteille.'::text,'qui'::text,'que'::text,'dont'::text,'La femme qui a apporté le bouquet porte aussi une bouteille.'::text),
(335906,37323,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... buketi getiren kadın bir şişe de taşıyor.'::text,''::text,NULL::text,NULL::text,'Buketi getiren kadın bir şişe de taşıyor.'::text),
(335907,37323,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nő, ... a csokrot hozta, egy üveget is visz.'::text,'aki'::text,'ami'::text,'akinek'::text,'A nő, aki a csokrot hozta, egy üveget is visz.'::text),
(335937,37327,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, anscheinend hat der Gastgeber dieses Jahr schon zweimal Blumensträuße von ihr ...'::text,'bekommen'::text,'bekommen'::text,'bekommen'::text,'Mädel, anscheinend hat der Gastgeber dieses Jahr schon zweimal Blumensträuße von ihr bekommen.'::text),
(335941,37327,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дівчино, кажуть, господар цього року вже двічі ... від неї букети.'::text,'отримав'::text,'отримує'::text,'отримує'::text,'Дівчино, кажуть, господар цього року вже двічі отримав від неї букети.'::text),
(335940,37327,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer el anfitrión ... ramos de ella dos veces este año.'::text,'ha recibido'::text,'recibe'::text,'está recibiendo'::text,'Tía, al parecer el anfitrión ha recibido ramos de ella dos veces este año.'::text),
(335939,37327,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment l''hôte ... des bouquets de sa part deux fois cette année.'::text,'a reçu'::text,'reçoit'::text,'reçoit'::text,'Meuf, apparemment l''hôte a reçu des bouquets de sa part deux fois cette année.'::text),
(335942,37327,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, güya ev sahibi bu yıl ondan iki kez buket ...'::text,'almış'::text,'alıyor'::text,'alıyor'::text,'Kızım, güya ev sahibi bu yıl ondan iki kez buket almış.'::text),
(335943,37327,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag a házigazda idén kétszer ... tőle csokrot.'::text,'kapott'::text,'kap'::text,'kap'::text,'Csajszi, állítólag a házigazda idén kétszer kapott tőle csokrot.'::text),
(397632,44182,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während sie das blaue Städtchen ..., blockierte ein Esel die Gasse. Ein leicht ungeplanter Stopp.'::text,'besichtigten'::text,'besichtigten'::text,'besichtigt haben'::text,'Während sie das blaue Städtchen besichtigten, blockierte ein Esel die Gasse. Ein leicht ungeplanter Stopp.'::text),
(397636,44182,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки вони ... синє містечко, віслюк перегородив провулок. Трохи незапланована зупинка.'::text,'оглядали'::text,'оглянули'::text,'оглянули'::text,'Поки вони оглядали синє містечко, віслюк перегородив провулок. Трохи незапланована зупинка.'::text),
(397635,44182,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mientras ellos ... el pueblo azul, un burro bloqueó el callejón. Una parada un poco imprevista.'::text,'recorrían'::text,'recorrieron'::text,'han recorrido'::text,'Mientras ellos recorrían el pueblo azul, un burro bloqueó el callejón. Una parada un poco imprevista.'::text),
(397634,44182,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant qu''ils ... la ville bleue, un âne a bloqué la ruelle. Un arrêt un peu imprévu.'::text,'visitaient'::text,'ont visité'::text,'ont visité'::text,'Pendant qu''ils visitaient la ville bleue, un âne a bloqué la ruelle. Un arrêt un peu imprévu.'::text),
(397637,44182,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onlar mavi kasabayı ..., bir eşek ara sokağı kapattı. Biraz plansız bir mola.'::text,'gezerken'::text,'gezdiklerinde'::text,'gezdiler'::text,'Onlar mavi kasabayı gezerken, bir eşek ara sokağı kapattı. Biraz plansız bir mola.'::text),
(397638,44182,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miközben ők ... a kék városkát, egy szamár elállta a sikátort. Kicsit nem tervezett megálló.'::text,'járták'::text,'bejárták'::text,'bejárták'::text,'Miközben ők járták a kék városkát, egy szamár elállta a sikátort. Kicsit nem tervezett megálló.'::text),
(397650,44184,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee, wenn der Esel sich nicht bewegt hätte, ... wir den Platz überhaupt nicht besichtigt, Bro.'::text,'hätten'::text,'werden'::text,'haben'::text,'Nee, wenn der Esel sich nicht bewegt hätte, hätten wir den Platz überhaupt nicht besichtigt, Bro.'::text),
(397654,44184,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не, якби віслюк не зрушив, ми ... площу взагалі, бро.'::text,'не оглянули б'::text,'не оглянемо'::text,'не оглянули'::text,'Не, якби віслюк не зрушив, ми не оглянули б площу взагалі, бро.'::text),
(397653,44184,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué va, si el burro no se hubiera movido, nosotros no ... la plaza para nada, bro.'::text,'habríamos visto'::text,'veremos'::text,'vimos'::text,'Qué va, si el burro no se hubiera movido, nosotros no habríamos visto la plaza para nada, bro.'::text),
(397652,44184,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nan, si l''âne n''avait pas bougé, on ... la place du tout, frère.'::text,'n''aurait pas visité'::text,'ne visitera pas'::text,'n''a pas visité'::text,'Nan, si l''âne n''avait pas bougé, on n''aurait pas visité la place du tout, frère.'::text),
(397655,44184,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok, eşek kıpırdamasaydı, biz meydanı hiç ..., kanka.'::text,'gezmezdik'::text,'gezmeyeceğiz'::text,'gezmedik'::text,'Yok, eşek kıpırdamasaydı, biz meydanı hiç gezmezdik, kanka.'::text),
(397656,44184,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Á, ha a szamár nem mozdult volna meg, mi egyáltalán nem ... a teret, tesó.'::text,'jártuk volna be'::text,'fogjuk bejárni'::text,'jártuk be'::text,'Á, ha a szamár nem mozdult volna meg, mi egyáltalán nem jártuk volna be a teret, tesó.'::text),
(348492,38722,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Sonne beim Sonnenuntergang auf die Kuppel ..., leuchtet sie orange.'::text,'trifft'::text,'traf'::text,'treffen wird'::text,'Wenn die Sonne beim Sonnenuntergang auf die Kuppel trifft, leuchtet sie orange.'::text),
(348496,38722,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли сонце на заході ... на купол, він світиться помаранчевим.'::text,'падає'::text,'впало'::text,'впаде'::text,'Коли сонце на заході падає на купол, він світиться помаранчевим.'::text),
(348495,38722,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el sol ... la cúpula al atardecer, esta brilla naranja.'::text,'toca'::text,'tocó'::text,'tocará'::text,'Si el sol toca la cúpula al atardecer, esta brilla naranja.'::text),
(348494,38722,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le soleil ... le dôme au crépuscule, il brille d''orange.'::text,'frappe'::text,'a frappé'::text,'frappera'::text,'Si le soleil frappe le dôme au crépuscule, il brille d''orange.'::text),
(348497,38722,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gün batımında güneş kubbeye ..., kubbe turuncu parlar.'::text,'vurursa'::text,'vurduysa'::text,'vuracaksa'::text,'Gün batımında güneş kubbeye vurursa, kubbe turuncu parlar.'::text),
(348498,38722,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha naplementekor a nap ... a kupolára, az narancssárgán izzik.'::text,'süt'::text,'sütött'::text,'sütni fog'::text,'Ha naplementekor a nap süt a kupolára, az narancssárgán izzik.'::text),
(336090,37344,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Stylistin ... den Zopf entlang des Scheitels fertig.'::text,'flicht'::text,'flicht'::text,'flicht'::text,'Die Stylistin flicht den Zopf entlang des Scheitels fertig.'::text),
(336094,37344,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Стилістка закінчує ... косу вздовж маківки.'::text,'плести'::text,'плести'::text,'плести'::text,'Стилістка закінчує плести косу вздовж маківки.'::text),
(336093,37344,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La estilista termina de ... la trenza a lo largo de la coronilla.'::text,'hacer'::text,'hacer'::text,'hacer'::text,'La estilista termina de hacer la trenza a lo largo de la coronilla.'::text),
(336092,37344,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La coiffeuse finit de ... la tresse le long du sommet du crâne.'::text,'tresser'::text,'tresser'::text,'tresser'::text,'La coiffeuse finit de tresser la tresse le long du sommet du crâne.'::text),
(336095,37344,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kuaför tepe boyunca örgüyü ... bitiriyor.'::text,'örmeyi'::text,'örmeyi'::text,'örmeyi'::text,'Kuaför tepe boyunca örgüyü örmeyi bitiriyor.'::text),
(336096,37344,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fodrász befejezi a copf ... a fejtető mentén.'::text,'fonását'::text,'fonását'::text,'fonását'::text,'A fodrász befejezi a copf fonását a fejtető mentén.'::text),
(336144,37350,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Salon 2 Stylistinnen eingeteilt hätte, ... der Zopf vor der Deadline fertig gewesen.'::text,'wäre'::text,'wird'::text,'war'::text,'Wenn der Salon 2 Stylistinnen eingeteilt hätte, wäre der Zopf vor der Deadline fertig gewesen.'::text),
(336148,37350,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби салон призначив 2 стилісток, коса ... до дедлайну.'::text,'була б готова'::text,'буде готова'::text,'була готова'::text,'Якби салон призначив 2 стилісток, коса була б готова до дедлайну.'::text),
(336147,37350,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el salón hubiera asignado 2 estilistas, la trenza ... antes de la fecha límite.'::text,'habría estado terminada'::text,'estará terminada'::text,'estaba terminada'::text,'Si el salón hubiera asignado 2 estilistas, la trenza habría estado terminada antes de la fecha límite.'::text),
(336146,37350,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le salon avait affecté 2 coiffeuses, la tresse ... avant la deadline.'::text,'aurait été terminée'::text,'sera terminée'::text,'était terminée'::text,'Si le salon avait affecté 2 coiffeuses, la tresse aurait été terminée avant la deadline.'::text),
(336149,37350,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Salon 2 kuaför görevlendirseydi, örgü son tarihten önce ...'::text,'bitirilmiş olurdu'::text,'bitirilecek'::text,'bitirildi'::text,'Salon 2 kuaför görevlendirseydi, örgü son tarihten önce bitirilmiş olurdu.'::text),
(336150,37350,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a szalon 2 fodrászt osztott volna be, a copf a határidő előtt ...'::text,'elkészült volna'::text,'el fog készülni'::text,'elkészült'::text,'Ha a szalon 2 fodrászt osztott volna be, a copf a határidő előtt elkészült volna.'::text),
(343074,38120,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während sie durch den Flur ..., drängten sich zwei Männer mit einer Kiste vorbei.'::text,'ging'::text,'ging'::text,'gegangen ist'::text,'Während sie durch den Flur ging, drängten sich zwei Männer mit einer Kiste vorbei.'::text),
(343078,38120,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки вона ... коридором, двоє чоловіків протиснулися повз із коробкою.'::text,'йшла'::text,'пройшла'::text,'пройшла'::text,'Поки вона йшла коридором, двоє чоловіків протиснулися повз із коробкою.'::text),
(343077,38120,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mientras ella ... por el pasillo, dos hombres pasaron apretujados con una caja.'::text,'caminaba'::text,'caminó'::text,'ha caminado'::text,'Mientras ella caminaba por el pasillo, dos hombres pasaron apretujados con una caja.'::text),
(343076,38120,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant qu''elle ... dans le couloir, deux hommes se sont faufilés avec un carton.'::text,'marchait'::text,'a marché'::text,'a marché'::text,'Pendant qu''elle marchait dans le couloir, deux hommes se sont faufilés avec un carton.'::text),
(343079,38120,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O koridorda ..., iki adam bir kutuyla yanından sıkışarak geçti.'::text,'yürürken'::text,'yürüdüğünde'::text,'yürüdü'::text,'O koridorda yürürken, iki adam bir kutuyla yanından sıkışarak geçti.'::text),
(343080,38120,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miközben ő ... a folyosón, két férfi egy dobozzal elpréselődött mellette.'::text,'ment'::text,'végigment'::text,'végigment'::text,'Miközben ő ment a folyosón, két férfi egy dobozzal elpréselődött mellette.'::text),
(343137,38127,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie wusste, dass dieser Flur am Umzugstag ein totaler Albtraum ...!'::text,'sein würde'::text,'sein wird'::text,'ist'::text,'Sie wusste, dass dieser Flur am Umzugstag ein totaler Albtraum sein würde!'::text),
(343141,38127,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона знала, що цей коридор ... справжнім жахіттям у день переїзду!'::text,'буде'::text,'буде'::text,'є'::text,'Вона знала, що цей коридор буде справжнім жахіттям у день переїзду!'::text),
(343140,38127,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ella sabía que ese pasillo ... una pesadilla total el día de la mudanza!'::text,'sería'::text,'será'::text,'es'::text,'¡Ella sabía que ese pasillo sería una pesadilla total el día de la mudanza!'::text),
(343139,38127,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle savait que ce couloir ... un vrai cauchemar le jour du déménagement !'::text,'serait'::text,'sera'::text,'est'::text,'Elle savait que ce couloir serait un vrai cauchemar le jour du déménagement !'::text),
(343142,38127,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, o koridorun taşınma günü tam bir kâbus ... biliyordu!'::text,'olacağını'::text,'olacağını'::text,'olduğunu'::text,'O, o koridorun taşınma günü tam bir kâbus olacağını biliyordu!'::text),
(343143,38127,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő tudta, hogy az a folyosó a költözés napján totális rémálom ...!'::text,'lesz'::text,'lesz'::text,NULL::text,'Ő tudta, hogy az a folyosó a költözés napján totális rémálom lesz!'::text),
(376023,41781,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der kurze Pfahl ist aus Holz, und der hohe ...'::text,'auch'::text,'auch'::text,'auch nicht'::text,'Der kurze Pfahl ist aus Holz, und der hohe auch.'::text),
(376027,41781,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Короткий стовпчик дерев''яний, і високий ...'::text,'теж'::text,'теж'::text,'теж ні'::text,'Короткий стовпчик дерев''яний, і високий теж.'::text),
(376026,41781,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El poste corto es de madera, y el alto ...'::text,'también'::text,'también'::text,'tampoco'::text,'El poste corto es de madera, y el alto también.'::text),
(376025,41781,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le poteau court est en bois, et le grand ...'::text,'aussi'::text,'aussi'::text,'non plus'::text,'Le poteau court est en bois, et le grand aussi.'::text),
(376028,41781,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kısa direk tahta, ve uzun olan ...'::text,'da öyle'::text,'da öyle'::text,'da değil'::text,'Kısa direk tahta, ve uzun olan da öyle.'::text),
(376029,41781,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A rövid oszlop fából van, és a magas ...'::text,'is'::text,'is'::text,'sem'::text,'A rövid oszlop fából van, és a magas is.'::text),
(376050,41784,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du hast darauf bestanden, jeden Pfahl selbst ..., und ehrlich, das ist echt cool.'::text,'einzuschlagen'::text,'einzuschlagen'::text,'eingeschlagen zu haben'::text,'Du hast darauf bestanden, jeden Pfahl selbst einzuschlagen, und ehrlich, das ist echt cool.'::text),
(376054,41784,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти наполіг на тому, щоб ... кожен стовпчик сам, і чесно, це реально крутий хід.'::text,'забити'::text,'забивати'::text,'забив'::text,'Ти наполіг на тому, щоб забити кожен стовпчик сам, і чесно, це реально крутий хід.'::text),
(376053,41784,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tú insististe en ... cada poste tú mismo, y sinceramente, eso es muy guay.'::text,'clavar'::text,'clavar'::text,'clavaste'::text,'Tú insististe en clavar cada poste tú mismo, y sinceramente, eso es muy guay.'::text),
(376052,41784,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu as tenu à ... chaque poteau toi-même, et franchement, c''est vraiment cool.'::text,'enfoncer'::text,'enfoncer'::text,'avoir enfoncé'::text,'Tu as tenu à enfoncer chaque poteau toi-même, et franchement, c''est vraiment cool.'::text),
(376055,41784,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sen her direği kendin ... ısrar ettin, ve açıkçası bu gerçekten havalı.'::text,'çakmakta'::text,'çakmakta'::text,'çaktın'::text,'Sen her direği kendin çakmakta ısrar ettin, ve açıkçası bu gerçekten havalı.'::text),
(376056,41784,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Te ragaszkodtál hozzá, hogy minden oszlopot magad ..., és őszintén, ez tényleg menő.'::text,'verj be'::text,'verj be'::text,'vertél be'::text,'Te ragaszkodtál hozzá, hogy minden oszlopot magad verj be, és őszintén, ez tényleg menő.'::text),
(395652,43962,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dieses Team ... seit 6 Monaten zusammen als Teamkollegen, und das Ziel ist das Finale.'::text,'trainiert'::text,'trainiert'::text,'trainiert'::text,'Dieses Team trainiert seit 6 Monaten zusammen als Teamkollegen, und das Ziel ist das Finale.'::text),
(395656,43962,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ця команда ... разом як партнери по команді вже 6 місяців, і мета — фінал.'::text,'тренується'::text,'тренується'::text,'тренується'::text,'Ця команда тренується разом як партнери по команді вже 6 місяців, і мета — фінал.'::text),
(395655,43962,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Este equipo ... junto como compañeros desde hace 6 meses, y el objetivo es la final.'::text,'ha estado entrenando'::text,'está entrenando'::text,'entrena'::text,'Este equipo ha estado entrenando junto como compañeros desde hace 6 meses, y el objetivo es la final.'::text),
(395654,43962,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cette équipe ... ensemble en tant que coéquipiers depuis 6 mois, et l''objectif, c''est la finale.'::text,'s''entraîne'::text,'s''entraîne'::text,'s''entraîne'::text,'Cette équipe s''entraîne ensemble en tant que coéquipiers depuis 6 mois, et l''objectif, c''est la finale.'::text),
(395657,43962,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu kadro 6 aydır takım arkadaşları olarak birlikte ..., ve hedef final.'::text,'antrenman yapıyor'::text,'antrenman yapıyor'::text,'antrenman yapar'::text,'Bu kadro 6 aydır takım arkadaşları olarak birlikte antrenman yapıyor, ve hedef final.'::text),
(395658,43962,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez a csapat 6 hónapja ... együtt csapattársakként, és a cél a döntő.'::text,'edz'::text,'edz'::text,'edz'::text,'Ez a csapat 6 hónapja edz együtt csapattársakként, és a cél a döntő.'::text),
(395742,43972,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Von den sechs Spielern lacht ..., der den letzten Ball verpasst hat, am lautesten.'::text,'der Mitspieler'::text,'ein Mitspieler'::text,'Mitspieler'::text,'Von den sechs Spielern lacht der Mitspieler, der den letzten Ball verpasst hat, am lautesten.'::text),
(395746,43972,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'З шести гравців найгучніше сміється ..., який пропустив останній м''яч.'::text,'партнер по команді'::text,'партнер по команді'::text,'партнер по команді'::text,'З шести гравців найгучніше сміється партнер по команді, який пропустив останній м''яч.'::text),
(395745,43972,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'De los seis jugadores, ... que falló el último balón es quien más se ríe.'::text,'el compañero'::text,'un compañero'::text,'compañero'::text,'De los seis jugadores, el compañero que falló el último balón es quien más se ríe.'::text),
(395744,43972,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Des six joueurs, ... qui a raté le dernier ballon rit le plus fort.'::text,'le coéquipier'::text,'un coéquipier'::text,'coéquipier'::text,'Des six joueurs, le coéquipier qui a raté le dernier ballon rit le plus fort.'::text),
(395747,43972,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Altı oyuncudan son topu kaçıran ... en yüksek sesle gülüyor.'::text,'takım arkadaşı'::text,'bir takım arkadaşı'::text,'takım arkadaşı'::text,'Altı oyuncudan son topu kaçıran takım arkadaşı en yüksek sesle gülüyor.'::text),
