(359454,39940,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... seiner geringen Größe fertigt der Hafen typischerweise große Containerschiffe ab.'::text,'Trotz'::text,'Obwohl'::text,'Aufgrund'::text,'Trotz seiner geringen Größe fertigt der Hafen typischerweise große Containerschiffe ab.'::text),
(359458,39940,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... свій невеликий розмір, гавань зазвичай обслуговує великі контейнеровози.'::text,'Попри'::text,'Хоча'::text,'Завдяки'::text,'Попри свій невеликий розмір, гавань зазвичай обслуговує великі контейнеровози.'::text),
(359457,39940,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... su pequeño tamaño, el puerto suele recibir grandes buques portacontenedores.'::text,'A pesar de'::text,'Aunque'::text,'Debido a'::text,'A pesar de su pequeño tamaño, el puerto suele recibir grandes buques portacontenedores.'::text),
