(359459,39940,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Küçük boyutuna ... liman genellikle büyük konteyner gemilerini ağırlıyor.'::text,'rağmen'::text,'gerçi'::text,'sayesinde'::text,'Küçük boyutuna rağmen liman genellikle büyük konteyner gemilerini ağırlıyor.'::text),
