(382539,42505,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... dir gerade den Stress weg, als der Chef vorbeiging, so smooth.'::text,'riebst'::text,'riebst'::text,'hast gerieben'::text,'Du riebst dir gerade den Stress weg, als der Chef vorbeiging, so smooth.'::text),
(382543,42505,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти якраз ... стрес, коли повз проходив бос, так плавно.'::text,'розтирала'::text,'розтерла'::text,'розтерла'::text,'Ти якраз розтирала стрес, коли повз проходив бос, так плавно.'::text),
(382542,42505,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tú te ... el estrés cuando pasó el jefe, qué estilo.'::text,'estabas frotando'::text,'frotaste'::text,'has frotado'::text,'Tú te estabas frotando el estrés cuando pasó el jefe, qué estilo.'::text),
