(382544,42505,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Patron yanından geçtiğinde sen stresini ovarak ..., çok şık.'::text,'atıyordun'::text,'attın'::text,'attın'::text,'Patron yanından geçtiğinde sen stresini ovarak atıyordun, çok şık.'::text),
(382545,42505,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Te épp ... magadról a stresszt, amikor a főnök elment melletted, olyan laza.'::text,'masszíroztad le'::text,'lemasszíroztad'::text,'lemasszíroztad'::text,'Te épp masszíroztad le magadról a stresszt, amikor a főnök elment melletted, olyan laza.'::text),
(382575,42509,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Diese Kopfschmerzen sind ein Albtraum! Sie muss jemanden finden, der ihr die Schultern ...!'::text,'massiert'::text,'massiert'::text,'massiert'::text,'Diese Kopfschmerzen sind ein Albtraum! Sie muss jemanden finden, der ihr die Schultern massiert!'::text),
(382579,42509,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Цей головний біль — жах! Вона мусить знайти когось, хто ... їй плечі!'::text,'розімне'::text,'розімне'::text,'розминання'::text,'Цей головний біль — жах! Вона мусить знайти когось, хто розімне їй плечі!'::text),
(382578,42509,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Este dolor de cabeza es una pesadilla! ¡Ella necesita que alguien le ... los hombros!'::text,'frote'::text,'frote'::text,'frotando'::text,'¡Este dolor de cabeza es una pesadilla! ¡Ella necesita que alguien le frote los hombros!'::text),
(382577,42509,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce mal de tête est un cauchemar ! Elle doit trouver quelqu''un pour lui ... les épaules !'::text,'masser'::text,'masser'::text,'masser'::text,'Ce mal de tête est un cauchemar ! Elle doit trouver quelqu''un pour lui masser les épaules !'::text),
