(382581,42509,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez a fejfájás egy rémálom! Ő kell, hogy találjon valakit, aki ... a vállát!'::text,'megmasszírozza'::text,'megmasszírozza'::text,'masszírozás'::text,'Ez a fejfájás egy rémálom! Ő kell, hogy találjon valakit, aki megmasszírozza a vállát!'::text)
) v(id, eid, lang, n_intro_text, n_correct_answer, n_distractor_1, n_distractor_2, n_full_sentence, o_intro_text, o_correct_answer, o_distractor_1, o_distractor_2, o_full_sentence)
